app.get("/fetch-fiscal-data", (req, res) => {


  // Get all organizations
  const orgQuery = `
    SELECT OrgId, OrgName, DBName, Address1, Address2, Phone1, Phone2, Fax, Email, LastSavedDateTime, Remarks
    FROM SAJILODB.dbo.tbOrgMaster
    ORDER BY LastSavedDateTime;
  `;

  sql.query(connectionString, orgQuery, (err, orgResults) => {
    if (err) {
      console.error("ERROR fetching organizations:", err.message);
      return res.status(500).send("Error fetching organization data");
    }

    if (!Array.isArray(orgResults) || orgResults.length === 0) {
      console.log("No organization data found");
      return res.json([]);
    }

    const allData = [];
    let processed = 0;

    orgResults.forEach((org) => {
      const orgId = org.OrgId;
      const orgDBName = org.DBName;
      const orgConnString = createConnectionString(orgDBName);

      // Step 1: Fetch DateType from this organization's own DB
      const dateTypeQuery = `
        SELECT TOP 1 DateType FROM [${orgDBName}].dbo.tbSystemSettings;
      `;

      sql.query(orgConnString, dateTypeQuery, (err1, dateTypeResult) => {
        const dateType = (!err1 && dateTypeResult?.[0]?.DateType) ? dateTypeResult[0].DateType : "AD";
        // console.log(`OrgId ${orgId} uses date type: ${dateType}`);

        // Step 2: Fetch Current Fiscal Year
        const fiscalYearQuery = `
          SELECT StartDate, EndDate
          FROM [${orgDBName}].dbo.tbFiscalYearMaster
          WHERE CurrentFiscal = 1;
        `;

        sql.query(orgConnString, fiscalYearQuery, (err2, fiscalResult) => {
          let startDate = "No date found";
          let endDate = "No date found";

          if (!err2 && fiscalResult?.length > 0) {
            const rawStartDate = formatDate(fiscalResult[0].StartDate);
            const rawEndDate = formatDate(fiscalResult[0].EndDate);

            // If DateType is LD, convert using tbLocalDate in master DB
            if (dateType === "LD") {
              const localDateQuery = `
                SELECT M_date, M_Miti
                FROM SAJILODB.dbo.tbLocalDate
                WHERE M_date IN ('${rawStartDate}', '${rawEndDate}');
              `;

              sql.query(connectionString, localDateQuery, (err3, localDates) => {
                let startDateLocal = rawStartDate;
                let endDateLocal = rawEndDate;



                if (!err3 && Array.isArray(localDates)) {
                  localDates.forEach((row) => {
                    if (formatDate(row.M_date) === rawStartDate) startDateLocal = formatDate(row.M_Miti);
                    if (formatDate(row.M_date) === rawEndDate) endDateLocal = formatDate(row.M_Miti);
                  });
                }

                pushOrgData(startDateLocal, endDateLocal);
                
              });
            } else {
              // AD: use raw dates
              pushOrgData(rawStartDate, rawEndDate);
            }
          } else {
            
            pushOrgData(startDate, endDate);
          }

          // Helper to accumulate data and return response
          function pushOrgData(startDateValue, endDateValue) {
            allData.push({
              orgid: orgId,
              orgDb: orgDBName,
              orgName: org.OrgName,
              orgAddress: org.Address1,
              orgPhone: org.Phone1,
              lastSavedDateTime: formatDate(org.LastSavedDateTime),
              startDate: startDateValue,
              endDate: endDateValue,
              dateType,
              remarks: org.Remarks
            });

            processed++;
            if (processed === orgResults.length) {

              res.json(allData);
              
            }
          }
        });
      });
    });
  });
});



const formatDate = (date) => {
  if (!date) return "No date found";

  if (typeof date === "string") {
    let parsedDate;

    // Check if the format is DD-MM-YYYY
    if (/^\d{2}-\d{2}-\d{4}$/.test(date)) {
      const [day, month, year] = date.split("-");
      parsedDate = new Date(`${year}-${month}-${day}`);
    }
    // Check if the format is DD/MM/YYYY
    else if (/^\d{2}\/\d{2}\/\d{4}$/.test(date)) {
      const [day, month, year] = date.split("/");
      parsedDate = new Date(`${year}-${month}-${day}`);
    } else {
      // Assume it's a date format like YYYY-MM-DD or YYYY-MM-DD HH:MM:SS
      parsedDate = new Date(date.split(" ")[0]); // Removes time part if it exists
    }

    return isNaN(parsedDate)
      ? "No date found"
      : parsedDate.toISOString().split("T")[0];
  }

  if (date.toISOString) {
    return date.toISOString().split("T")[0];
  }

  return "No date found";
};

// Login route - only validates credentials, then redirects to database selection
app.post("/login", (req, res) => {
  const { username, password } = req.body;

  if (!username) {
    return res.status(400).json({ 
      message: "Username is required.", 
      success: false 
    });
  }

  // Query to check if user exists no password verification for simplicityand testing
  const query = `
    SELECT UserID FROM tbUserMaster
    WHERE UserName = ? AND Password = ?
  `;

  sql.query(connectionString, query, [username, password], (err, rows) => {
    if (err) {
      console.error("Login failed:", err);
      return res.status(500).json({ 
        message: "Internal server error. Please try again later.", 
        success: false 
      });
    }

    if (!rows || rows.length === 0) {
      console.log("Invalid login attempt for username or password:", username);
      return res.status(401).json({ 
        message: "Invalid username or password.", 
        success: false 
      });
    }

    // User is admin - store in session and redirect to database selection
    const userID = rows[0].UserID;
    req.session.username = username;
    req.session.userID = userID;
    req.session.loggedIn = true;
    
    console.log('Login successful for admin user:', username);
    // Render the database-selection view and send as HTML
    return res.render('database-selection', { username });
  });
});


// New route to handle database selection
app.post("/select-database", (req, res) => {
  const { dbName, startDateInput, endDateInput } = req.body;
  const username = req.session.username;
  const userID = req.session.userID;
  const computerName = os.hostname();
  const winUserName = os.userInfo().username;
  const deviceType = req.useragent.isMobile ? 'Mobile' :
    req.useragent.isTablet ? 'Tablet' :
      req.useragent.isDesktop ? 'pc' : 'Unknown';

  if (!dbName || !startDateInput || !endDateInput) {
    return res.status(400).json({ 
      message: "Database and dates are required.", 
      success: false 
    });
  }

  // Get OrgID for the selected database
  const queryOrgID = `
    SELECT OrgID FROM tbOrgMaster WHERE DBName = ?
  `;

  sql.query(connectionString, queryOrgID, [dbName], (err, rows) => {
    if (err) {
      console.error("Database selection failed:", err);
      return res.status(500).json({ 
        message: "Internal server error", 
        success: false 
      });
    }

    if (!rows || rows.length === 0) {
      console.log("No organization found for:", dbName);
      return res.status(400).json({
        message: `No organization found with the name '${dbName}'.`,
        success: false,
      });
    }

    const orgID = rows[0].OrgID;

    // If no dates found, show FiscalYearInsert form instead of error
    if (startDateInput === "No date found" || endDateInput === "No date found") {
      return res.render('FiscalYearInsert', { 
        orgID: orgID, 
        dbName: dbName,
        username: username,
        userID: userID,
        message: 'Please set up fiscal year dates for this organization.'
      });
    }

    // Insert login log entry
    const logQuery = `
      INSERT INTO tbUserLog (UserID, OrgID, ComputerName, WinUserName, LoginDateTime)
      VALUES (?, ?, ?, ?, GETDATE())
    `;

    sql.query(connectionString, logQuery, [userID, orgID, computerName, winUserName], (err) => {
      if (err) {
        console.error("Error saving login log:", err);
        return res.status(500).json({ 
          message: "Error saving login data", 
          success: false 
        });
      }

      // Store database info in session
      req.session.dbName = dbName;
      req.session.conn = `Server=localhost;Database=${dbName};UID=sa;PWD=123;Driver={ODBC Driver 17 for SQL Server};`;
      req.session.selectedStartDateLocal = startDateInput;
      req.session.selectedEndDateLocal = endDateInput;

      console.log('Database selection successful for user:', username, 'Database:', dbName);
      return res.redirect('/docclass.html');
    });
  });
});

app.post("/logout", (req, res) => {
  const userId = req.session.userID;

  const query = `
    UPDATE tbUserLog
    SET LogoutDateTime = GETDATE()
    WHERE LoginID = (
        SELECT TOP 1 LoginID
        FROM tbUserLog
        WHERE UserID = ? AND LogoutDateTime IS NULL
        ORDER BY LoginDateTime DESC
    )
  `;

  sql.query(connectionString, query, [userId], (err) => {
    if (err) {
      console.error("Logout update failed:", err);
    }

    req.session.destroy((destroyErr) => {
      if (destroyErr) {
        console.error("Session destroy failed:", destroyErr);
        res.clearCookie("connect.sid");
        return res.status(500).json({ success: false, message: "Error destroying session" });
      }

      res.clearCookie("connect.sid");
      return res.json({ success: true, message: "Logout successful" });
    });
  });
});



