app.post("/account/bigTransaction", async (req, res) => {
  try {
    const { SlAlias, GLName, accName, amount, transactionType } = req.body;
    const account = await Account.findOne({ SlAlias }).exec();

    if (!account) {
      return res.status(404).send("Account does not exist.");
    }

    const parsedAmount = parseFloat(amount);
    if (parsedAmount <= 0) return res.status(400).send("Invalid amount");

    if (transactionType === "deposit") {
      account.amount += parsedAmount;
    } else if (transactionType === "withdraw") {
      if (parsedAmount > account.Balance) {
        return res.status(400).send("Insufficient balance");
      }
      account.amount -= parsedAmount;
    }

    await account.save();
    res.send(account);
  } catch (err) {
    res.status(500).send("Error processing transaction");
  }
});

