app.post("/delete-doc-class", (req, res) => {
  const { name } = req.body; // Receive the document class name from the frontend
  const conn = req.session.conn; // Get the database connection from the session

  // Step 1: Find the DocClassID corresponding to the DocClassName
  const queryDocClassID = `
    SELECT DocClassID
    FROM dbo.tbDocClassMaster
    WHERE DocClassName = ?
  `;

  sql.query(conn, queryDocClassID, [name], (err, result) => {
    if (err) {
      console.error("Error retrieving DocClassID:", err);
      return res.status(500).send("Error retrieving DocClassID.");
    }

    if (result.length === 0) {
      // If no matching DocClassName is found
      return res.status(404).send("Document class not found.");
    }

    const docClassID = result[0].DocClassID; // Get the DocClassID from the result

    // Step 2: Check if the DocClassID exists in tbJournalMaster
    const queryCheckJournal = `
      SELECT 1
      FROM dbo.tbJournalMaster
      WHERE DocClassID = ?
    `;

    sql.query(conn, queryCheckJournal, [docClassID], (err, journalResult) => {
      if (err) {
        console.error("Error checking DocClassID in tbJournalMaster:", err);
        return res
          .status(500)
          .send("Error checking DocClassID in tbJournalMaster.");
      }

      if (journalResult.length > 0) {
        // If the DocClassID is found in tbJournalMaster, do not allow deletion
        return res
          .status(400)
          .send(
            "Cannot delete document class because it is used in tbJournalMaster."
          );
      }

      // Step 3: If DocClassID is not found in tbJournalMaster, proceed to delete the document class
      const queryDeleteDocClass = `
        DELETE FROM dbo.tbDocClassMaster
        WHERE DocClassID = ?
      `;

      sql.query(
        conn,
        queryDeleteDocClass,
        [docClassID],
        (err, deleteResult) => {
          if (err) {
            console.error("SQL error deleting document class:", err);
            return res.status(500).send("Error deleting document class.");
          }

          res.send("Document class deleted successfully!");
        }
      );
    });
  });
});
