// Helper function to format dates with debugging
app.post("/clone-databaseS", (req, res) => {
  const existingDatabases = req.body.existingDatabases;
  const newDatabases = req.body.newDatabases;
  const conn = req.session.conn;

  let responseSent = false; // Flag to track if a response has been sent

  const createDatabaseSQLS = `CREATE DATABASE [${newDatabases}_DB];`;
  const cloneTablesSQLS = `
      DECLARE @TableName NVARCHAR(128);
      DECLARE TableCursor CURSOR FOR
      SELECT TABLE_NAME
      FROM [${existingDatabases}].INFORMATION_SCHEMA.TABLES
      WHERE TABLE_TYPE = 'BASE TABLE';

      OPEN TableCursor;
      FETCH NEXT FROM TableCursor INTO @TableName;

      WHILE @@FETCH_STATUS = 0
      BEGIN
          EXEC('SELECT TOP 0 * INTO [${newDatabases}_DB].dbo.' + @TableName + ' FROM [${existingDatabases}].dbo.' + @TableName);
          FETCH NEXT FROM TableCursor INTO @TableName;
      END

      CLOSE TableCursor;
      DEALLOCATE TableCursor;
  `;

  sql.query(conn, createDatabaseSQLS, (err) => {
    if (err) {
      console.error("Error creating database:", err);
      if (!responseSent) {
        // Check if the response has been sent
        res
          .status(500)
          .send({ success: false, message: "Error creating database." });
        responseSent = true; // Mark that a response has been sent
      }
      return;
    }

    sql.query(conn, cloneTablesSQLS, (err) => {
      if (err) {
        console.error("Error cloning table structures:", err);
        if (!responseSent) {
          // Check if the response has been sent
          res
            .status(500)
            .send({
              success: false,
              message: "Error cloning table structures.",
            });
          responseSent = true; // Mark that a response has been sent
        }
        return;
      }

      if (!responseSent) {
        // Send the success response if not already sent
        res
          .status(200)
          .send({ success: true, message: "Database cloned successfully!" });
        responseSent = true; // Mark that a response has been sent
      }
    });
  });
});

// Parse the connection string into a configuration object for mssql
function parseConnectionString(connectionString) {
  const config = {};
  const params = connectionString.split(";");

  params.forEach((param) => {
    const [key, value] = param.split("=");
    if (key && value) {
      config[key.trim()] = value.trim();
    }
  });

  return {
    user: config.user,
    password: config.password,
    server: config.Server, // 'Server' from the string is 'server' for mssql
    database: config.Database, // 'Database' from the string is 'database' for mssql
    options: {
      encrypt: true, // Always use encryption
      trustServerCertificate: true, // Skip certificate validation for self-signed certificates
    },
  };
}

