app.post("/add-district", (req, res) => {
  console.log("Request body:", req.body);
  const conn = req.session.conn;
  const { district, districtalias } = req.body;

  if (!district || !districtalias) {
    return res
      .status(400)
      .json({ message: "District and Alias are required.", success: false });
  }

  const checkQuery = `SELECT COUNT(*) AS count FROM tbDistrictMaster WHERE District = ?`;

  sql.query(conn, checkQuery, [district], (err, results) => {
    if (err) {
      console.error("Error checking district:", err);
      return res
        .status(500)
        .json({ message: "Error checking district.", success: false });
    }

    if (results[0].count > 0) {
      return res
        .status(400)
        .json({ message: "District name already exists.", success: false });
    }

    const insertQuery = `
      INSERT INTO tbDistrictMaster (District, Alias)
      VALUES (?, ?)
    `;

    sql.query(conn, insertQuery, [district, districtalias], (err) => {
      if (err) {
        console.error("Error inserting District:", err);
        return res
          .status(500)
          .json({ message: "Error saving district.", success: false });
      }
      return res
        .status(200)
        .json({ message: "District added successfully!", success: true });
    });
  });
});


