// Route to delete district from the database
app.post("/deleteDistrict", (req, res) => {
  const { districtName } = req.body;
  const conn = req.session.conn;

  // Check if the district name is provided
  if (!districtName) {
    return res
      .status(400)
      .send({ success: false, message: "District name is required" });
  }

  // Trim the district name to avoid hidden characters like spaces
  const districtNameTrimmed = districtName.trim();

  // Ensure we have a connection
  if (!conn) {
    return res
      .status(500)
      .send({ success: false, message: "Database connection not found" });
  }

  // SQL query (case-insensitive deletion)
  const query = `DELETE FROM dbo.tbDistrictMaster WHERE LOWER(District) = LOWER(?)`;

  // Execute the query
  sql.query(conn, query, [districtNameTrimmed], (err, result) => {
    if (err) {
      console.error(`Error deleting district "${districtNameTrimmed}":`, err);
      return res
        .status(500)
        .send({ success: false, message: "Error deleting district" });
    }

    // If no rows were affected, handle as an error
    if (result.affectedRows === 0) {
      console.log(`No district found for deletion: "${districtNameTrimmed}"`);
      return res.status(404).send({
        success: false,
        message: `District "${districtNameTrimmed}" not found for deletion.`,
      });
    }

    // If the district was deleted
    res.send({
      success: true,
      message: `District "${districtNameTrimmed}" deleted successfully`,
    });
  });
});

