app.post("/deleteQualification", (req, res) => {
  const { qualificationName } = req.body;
  const conn = req.session.conn;

  if (!qualificationName) {
    return res.status(400).send({
      success: false,
      message: "Qualification name is required",
    });
  }

  const qualificationNameTrimmed = qualificationName.trim();

  if (!conn) {
    return res.status(500).send({
      success: false,
      message: "Database connection not found",
    });
  }

  // STEP 1: Get the QualificationID for the given Qualification name
  const getIdQuery = `
    SELECT QualificationID
    FROM dbo.tbQualificationMaster
    WHERE LOWER(Qualification) = LOWER(?)
  `;

  sql.query(conn, getIdQuery, [qualificationNameTrimmed], (err, result) => {
    if (err) {
      console.error("Error fetching QualificationID:", err);
      return res.status(500).send({
        success: false,
        message: "Error checking qualification",
      });
    }

    if (result.length === 0) {
      return res.status(404).send({
        success: false,
        message: `Qualification "${qualificationNameTrimmed}" not found.`,
      });
    }

    const qualificationId = result[0].QualificationID;

    // STEP 2: Check if this QualificationID is referenced in tbMemberMaster
    const checkReferenceQuery = `
      SELECT COUNT(*) AS count
      FROM dbo.tbMemberMaster
      WHERE QualificationID = ?
    `;

    sql.query(conn, checkReferenceQuery, [qualificationId], (err, refResult) => {
      if (err) {
        console.error("Error checking references:", err);
        return res.status(500).send({
          success: false,
          message: "Error checking qualification usage",
        });
      }

      const referenceCount = refResult[0].count;

      if (referenceCount > 0) {
        return res.status(400).send({
          success: false,
          message: `This qualification "${qualificationNameTrimmed} is referenced or in use so can't delete it.`,
        });
      }

      // STEP 3: No references → proceed to delete
      const deleteQuery = `
        DELETE FROM dbo.tbQualificationMaster
        WHERE QualificationID = ?
      `;

      sql.query(conn, deleteQuery, [qualificationId], (err, deleteResult) => {
        if (err) {
          console.error("Error deleting qualification:", err);
          return res.status(500).send({
            success: false,
            message: "Error deleting qualification",
          });
        }

        if (deleteResult.affectedRows === 0) {
          return res.status(404).send({
            success: false,
            message: `Qualification "${qualificationNameTrimmed}" not found for deletion.`,
          });
        }

        res.send({
          success: true,
          message: `Qualification "${qualificationNameTrimmed}" deleted successfully.`,
        });
      });
    });
  });
});


