// To edit an existing qualification
app.post("/edit-qualification", (req, res) => {
  const {
    qualificationName,
    qualificationAlias,
    newQualificationName,
    newQualificationAlias,
  } = req.body;

  // Log the incoming request data for debugging
  console.log("Request data:", req.body);

  // Validate if all required fields exist
  if (
    !qualificationName ||
    !qualificationAlias ||
    !newQualificationName ||
    !newQualificationAlias
  ) {
    return res
      .status(400)
      .json({ message: "All fields are required.", success: false });
  }

  // Normalize values (trim and lowercase)
  let qualificationNameTrimmed,
    qualificationAliasTrimmed,
    newQualificationNameTrimmed,
    newQualificationAliasTrimmed;

  try {
    qualificationNameTrimmed = qualificationName.trim().toLowerCase();
    qualificationAliasTrimmed = qualificationAlias.trim().toLowerCase();
    newQualificationNameTrimmed = newQualificationName.trim().toLowerCase();
    newQualificationAliasTrimmed = newQualificationAlias.trim().toLowerCase();
  } catch (err) {
    // Catch and handle case when any of the fields are undefined or null
    console.error("Error processing input data:", err);
    return res
      .status(400)
      .json({
        message:
          "Error processing input data. Please ensure all fields are valid strings.",
        success: false,
      });
  }

  // Log trimmed and normalized values for debugging
  console.log("Trimmed and normalized values:", {
    qualificationNameTrimmed,
    qualificationAliasTrimmed,
    newQualificationNameTrimmed,
    newQualificationAliasTrimmed,
  });

  // Check if there are any changes
  if (
    qualificationNameTrimmed === newQualificationNameTrimmed &&
    qualificationAliasTrimmed === newQualificationAliasTrimmed
  ) {
    return res
      .status(200)
      .json({
        success: true,
        message: "No changes made, qualification is up to date.",
      });
  }

  // SQL query to update qualification
  const query = `
    UPDATE dbo.tbQualificationMaster
    SET Qualification = ?, Alias = ?
    WHERE LTRIM(RTRIM(LOWER(Qualification))) = LTRIM(RTRIM(LOWER(?)))
    AND LTRIM(RTRIM(LOWER(Alias))) = LTRIM(RTRIM(LOWER(?)))
  `;

  const conn = req.session.conn;

  // Execute the update query
  sql.query(
    conn,
    query,
    [
      newQualificationNameTrimmed,
      newQualificationAliasTrimmed,
      qualificationNameTrimmed,
      qualificationAliasTrimmed,
    ],
    (err, result) => {
      if (err) {
        console.error("Error updating qualification:", err);
        return res
          .status(500)
          .json({ message: "Error updating qualification", success: false });
      }

      // If no rows are affected, that means the qualification was not found or nothing changed
      if (result.affectedRows === 0 && result.changedRows === 0) {
        return res
          .status(400)
          .json({
            message: "Qualification not found or no changes were made.",
            success: false,
          });
      }

      // Return success if the qualification was updated
      return res.json({
        success: true,
        message: "Qualification updated successfully!",
      });
    }
  );
});
