// Route to delete route from the database
app.post("/deleteRoute", (req, res) => {
  const { routeName } = req.body;
  const conn = req.session.conn;

  // Check if the route name is provided
  if (!routeName) {
    return res
      .status(400)
      .send({ success: false, message: "Route name is required" });
  }

  // Trim the route name to avoid hidden characters like spaces
  const routeNameTrimmed = routeName.trim();

  // Ensure we have a connection
  if (!conn) {
    return res
      .status(500)
      .send({ success: false, message: "Database connection not found" });
  }

  // SQL query (case-insensitive deletion)
  const query = `DELETE FROM dbo.tbRouteMaster WHERE LOWER(Route) = LOWER(?)`;

  // Execute the query
  sql.query(conn, query, [routeNameTrimmed], (err, result) => {
    if (err) {
      console.error(`Error deleting route "${routeNameTrimmed}":`, err);
      return res
        .status(500)
        .send({ success: false, message: "Error deleting route" });
    }

    // If no rows were affected, handle as an error
    if (result.affectedRows === 0) {
      console.log(`No route found for deletion: "${routeNameTrimmed}"`);
      return res.status(404).send({
        success: false,
        message: `Route "${routeNameTrimmed}" not found for deletion.`,
      });
    }

    // If the route was deleted
    res.send({
      success: true,
      message: `Route "${routeNameTrimmed}" deleted successfully`,
    });
  });
});
