// Route to delete a denomination from the database
app.post("/deleteDenomination", (req, res) => {
  const { denominationName } = req.body;
  const conn = req.session.conn;

  // Check if the denomination name is provided
  if (!denominationName) {
    return res
      .status(400)
      .send({ success: false, message: "Denomination name is required" });
  }

  // Trim the denomination name to avoid hidden characters like spaces
  const denominationNameTrimmed = denominationName.trim();

  // Ensure we have a valid database connection
  if (!conn) {
    return res
      .status(500)
      .send({ success: false, message: "Database connection not found" });
  }

  // SQL query (case-insensitive deletion)
  const query = `DELETE FROM dbo.tbDenominationMaster WHERE LOWER(Denomination) = LOWER(?)`;

  // Execute the query to delete the denomination
  sql.query(conn, query, [denominationNameTrimmed], (err, result) => {
    if (err) {
      console.error(
        `Error deleting denomination "${denominationNameTrimmed}":`,
        err
      );
      return res
        .status(500)
        .send({ success: false, message: "Error deleting denomination" });
    }

    // If no rows were affected, handle as an error (denomination not found)
    if (result.affectedRows === 0) {
      console.log(
        `No denomination found for deletion: "${denominationNameTrimmed}"`
      );
      return res.status(404).send({
        success: false,
        message: `Denomination "${denominationNameTrimmed}" not found for deletion.`,
      });
    }

    // If the denomination was deleted successfully
    res.send({
      success: true,
      message: `Denomination "${denominationNameTrimmed}" deleted successfully`,
    });
  });
});
