//Route to edit an existing Denomination
app.post("/edit-denomination", (req, res) => {
  const { denominationName, description, newDenominationName, newDescription } =
    req.body;

  // Trim and normalize the values
  const denominationNameTrimmed = denominationName.trim().toLowerCase();
  const descriptionTrimmed = description.trim().toLowerCase();
  const newDenominationNameTrimmed = newDenominationName.trim().toLowerCase();
  const newDescriptionTrimmed = newDescription.trim().toLowerCase();

  console.log("Request data:", req.body);
  console.log("Trimmed and normalized values:", {
    denominationNameTrimmed,
    descriptionTrimmed,
    newDenominationNameTrimmed,
    newDescriptionTrimmed,
  });

  // SQL query to check if any fields have changed
  if (
    denominationNameTrimmed === newDenominationNameTrimmed &&
    descriptionTrimmed === newDescriptionTrimmed
  ) {
    return res
      .status(200)
      .json({
        success: true,
        message: "No changes made, denomination is up to date.",
      });
  }

  // SQL query to update denomination
  const query = `
      UPDATE tbDenominationMaster
      SET Denomination = ?, Description = ?
      WHERE LTRIM(RTRIM(LOWER(Denomination))) = LTRIM(RTRIM(LOWER(?)))
      AND LTRIM(RTRIM(LOWER(Description))) = LTRIM(RTRIM(LOWER(?)))
  `;

  const conn = req.session.conn;

  // Execute the update query
  sql.query(
    conn,
    query,
    [
      newDenominationNameTrimmed,
      newDescriptionTrimmed,
      denominationNameTrimmed,
      descriptionTrimmed,
    ],
    (err, result) => {
      if (err) {
        console.error("Error updating denomination:", err);
        return res
          .status(500)
          .json({ message: "Error updating denomination", success: false });
      }

      // If no rows are affected, that means the denomination was not found or nothing changed
      if (result.affectedRows === 0 && result.changedRows === 0) {
        return res
          .status(400)
          .json({
            message: "Denomination not found or no changes were made.",
            success: false,
          });
      }

      // Return success if the denomination was updated
      return res.json({
        success: true,
        message: "Denomination updated successfully!",
      });
    }
  );
});
// POST route for saving VDC municipality
app.post("/add-vdc-municipality", (req, res) => {
  try {
    // Log the request body to see what you're receiving
    console.log("Request body:", req.body);

    // Destructure and sanitize input data
    const { vdcmunicipality, vdcalias } = req.body;
    const vdcmunicipalityTrimmed = vdcmunicipality.trim();
    const vdcaliasTrimmed = vdcalias.trim();

    const conn = req.session.conn;

    // Validate request
    if (!vdcmunicipalityTrimmed || !vdcaliasTrimmed) {
      return res
        .status(400)
        .json({ message: "VDC and Alias are required.", success: false });
    }

    // Check if the VDC already exists in the database
    const checkVdcQuery = `SELECT COUNT(*) AS count FROM tbVdcMaster WHERE Vdc = ?`;
    sql.query(conn, checkVdcQuery, [vdcmunicipalityTrimmed], (err, results) => {
      if (err) {
        console.error("Error checking VDC:", err.message || err);
        return res
          .status(500)
          .send({ message: "Error checking VDC.", success: false });
      }

      // If VDC already exists, send a response with an error message
      if (results[0].count > 0) {
        return res
          .status(400)
          .send({ message: "VDC name already exists.", success: false });
      }

      // SQL query to insert the new VDC into the database
      const insertQuery = `
        INSERT INTO tbVdcMaster (Vdc, Alias)
        VALUES (?, ?)
      `;
      sql.query(
        conn,
        insertQuery,
        [vdcmunicipalityTrimmed, vdcaliasTrimmed],
        (err, result) => {
          if (err) {
            console.error("Error inserting VDC:", err.message || err);
            return res
              .status(500)
              .json({ message: "Error saving VDC.", success: false });
          }

          // Return success message if VDC is inserted successfully
          return res
            .status(200)
            .json({ message: "VDC added successfully!", success: true });
        }
      );
    });
  } catch (error) {
    // Catch any unexpected errors
    console.error("Unexpected error:", error.message || error);
    return res
      .status(500)
      .json({ message: "An unexpected error occurred.", success: false });
  }
});

