// POST route for saving a Narration
app.post("/add-narration", (req, res) => {
  console.log("Request body:", req.body); // Log the entire body to see what you're receiving
  const conn = req.session.conn;

  // Destructuring the request body to get the fields from the frontend form
  const { narration } = req.body;

  // Check if narration is provided
  if (!narration) {
    return res
      .status(400)
      .json({ message: "Narration is required.", success: false });
  }

  // SQL query to check if the narration already exists
  const checkQuery = `SELECT COUNT(*) AS count FROM dbo.tbNarrationMaster WHERE Narration = ?`;

  // Execute the check query to see if the narration already exists
  sql.query(conn, checkQuery, [narration], (err, results) => {
    if (err) {
      console.error("Error checking narration:", err);
      return res
        .status(500)
        .send({ message: "Error checking narration.", success: false });
    }

    if (results[0].count > 0) {
      // If narration already exists
      return res
        .status(400)
        .send({ message: "Narration already exists.", success: false });
    }

    // SQL query to insert the new narration into the database
    const insertQuery = `
      INSERT INTO dbo.tbNarrationMaster (Narration)
      VALUES (?)
    `;

    // Execute the insert query to save the new narration
    sql.query(conn, insertQuery, [narration], (err, result) => {
      if (err) {
        console.error("Error inserting narration:", err);
        return res
          .status(500)
          .json({ message: "Error saving narration.", success: false });
      }
      // Send success response
      return res
        .status(200)
        .json({ message: "Narration added successfully!", success: true });
    });
  });
});

