app.post("/submit-fiscal-year", (req, res) => {
  const { startDate, endDate, transactionStartDate, currentFiscal, remarks } =
    req.body;
  const conn = req.session.conn;

  // Check if the 'currentFiscal' checkbox is checked
  const currentFiscalValue = currentFiscal ? 1 : 0;

  // Step 1: Set the `CurrentFiscal` column to 0 for all other records
  const resetCurrentFiscalQuery = `
      UPDATE tbFiscalYearMaster
      SET CurrentFiscal = 0
  `;

  sql.query(conn, resetCurrentFiscalQuery, (err, result) => {
    if (err) {
      console.error("Error resetting CurrentFiscal:", err.message);
      return res
        .status(500)
        .send({ message: "Error resetting fiscal year", success: false });
    }

    // Step 2: Insert the new fiscal year record with appropriate values
    const insertQuery = `
          INSERT INTO tbFiscalYearMaster (TransactionStartDate, StartDate, EndDate, CurrentFiscal, Remarks, LastSavedDateTime)
          VALUES ('${transactionStartDate}', '${startDate}', '${endDate}', ${currentFiscalValue}, '${remarks}',GETDATE())
      `;

    sql.query(conn, insertQuery, (err, result) => {
      if (err) {
        console.error("Error inserting fiscal year data:", err.message);
        return res
          .status(500)
          .send({ message: "Error inserting fiscal year", success: false });
      }

      res
        .status(200)
        .send({ message: "Fiscal year added successfully", success: true });
    });
  });
});

