app.get("/api/fiscal-year", (req, res) => {
  const { orgName, orgAlias } = req.query;

  // Step 1: Fetch the DBName for the selected organization
  const orgQuery =
    "SELECT DBName FROM tbOrgMaster WHERE OrgName = ? AND OrgAlias = ?";

  sql.query(connectionString, orgQuery, [orgName, orgAlias], (err, orgRows) => {
    if (err) {
      console.error("Error fetching DBName:", err);
      return res.status(500).send("Database query failed");
    }

    if (orgRows.length > 0) {
      const reqdbName = orgRows[0].DBName;
      console.log("Choosed Database", reqdbName);
      req.session.reqdbName = reqdbName;

      const dynamicConnectionString = `Server=localhost;Database=${reqdbName};user=sa;password=123;Trusted_Connection=Yes;Driver={SQL Server Native Client 11.0};`;
      // Step 2: Fetch the fiscal year from the selected organization's database
      const systemSettingQuery = `SELECT TOP 1 DateType FROM tbSystemSettings `
      sql.query(dynamicConnectionString, systemSettingQuery, (err, systemRes) => {
        if (err) {
          console.error("Error fetching DateType:", err);
          return res.status(500).send("DateType query failed");
        }
        const dateType = systemRes[0].DateType;

        const fiscalQuery = `
        SELECT StartDate, EndDate
        FROM ${reqdbName}.dbo.tbFiscalYearMaster
        WHERE CurrentFiscal = 1`;

        sql.query(dynamicConnectionString, fiscalQuery, (err, fiscalRows) => {
          if (err) {
            console.error("Error fetching fiscal year data:", err);
            return res.status(500).send("Fiscal year query failed");
          }

          if (fiscalRows.length > 0) {
            const { StartDate, EndDate } = fiscalRows[0];

            // Step 3: Fetch M_Miti from SAJILODB
            const mitiQuery = `
            SELECT 
              (SELECT M_Miti FROM SAJILODB.dbo.tbLocalDate WHERE M_Date = ?) AS StartMiti,
              (SELECT M_Miti FROM SAJILODB.dbo.tbLocalDate WHERE M_Date = ?) AS EndMiti`;

            sql.query(
              connectionString,
              mitiQuery,
              [StartDate, EndDate],
              (err, mitiRows) => {
                if (err) {
                  console.error("Error fetching M_Miti data:", err);
                  return res.status(500).send("M_Miti query failed");
                }

                if (mitiRows.length > 0) {
                  const { StartMiti, EndMiti } = mitiRows[0];

                  if (dateType === "LD") {
                    res.json({
                      StartMiti: StartMiti || "N/A",
                      EndMiti: EndMiti || "N/A",
                    });
                  } else {
                    res.json({
                      StartDate,
                      EndDate,
                    });
                  }
                } else {
                  res.status(404).send("No M_Miti found for the provided dates");
                }

              }
            );
          } else {
            res.status(404).send("No fiscal year found for the current fiscal");
          }
        });
      });
    } else {
      res.status(404).send("Organization not found");
    }
  });

});

// Example connection strings (replace with actual details)
const getConnectionString = (dbName) =>
  `Server=localhost;Database=${dbName};Trusted_Connection=Yes;Driver={SQL Server Native Client 11.0};`;



function formatDateForSQL(date) {
  const pad = (n) => (n < 10 ? '0' + n : n);
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
}

async function copyTableData(sourceConnString, targetConnString, tableName, primaryKey) {
  const selectQuery = `SELECT * FROM ${tableName}`;
  console.log(`Fetching data from source table: ${sourceConnString.split('Database=')[1].split(';')[0]}.dbo.${tableName}`);

  return new Promise((resolve, reject) => {
    sql.query(sourceConnString, selectQuery, (err, rows) => {
      if (err) {
        console.error(`❌ Error fetching data from ${tableName}:`, err);
        return reject(err);
      }

      if (!rows || rows.length === 0) {
        console.warn(`⚠️  Source table ${tableName} is empty. Nothing to copy.`);
        return resolve(); // Skip copying, no failure
      }

      console.log(`✅ Fetched ${rows.length} rows from ${tableName}. Starting copy...`);

      const columns = Object.keys(rows[0]).filter((col) => col !== primaryKey);
      if (columns.length < 1) {
        return reject(
          new Error(
            `Table ${tableName} must have at least one column (excluding primary key) to insert.`
          )
        );
      }

      const insertPromises = rows.map((row) => {
        const col1 = columns[0];
        const col1Value = row[col1] == null ? "NULL" : `'${row[col1].toString().replace(/'/g, "''")}'`;

        const whereClause = `${col1} = ${col1Value}`;

        const values = columns.map((col) => {
          const value = row[col];

          if (value == null) return "NULL";

          // Date handling
          if (value instanceof Date) {
            return `'${formatDateForSQL(value)}'`;
          }

          const parsed = new Date(value);
          if (!isNaN(parsed.getTime()) && col.toLowerCase().includes("date")) {
            return `'${formatDateForSQL(parsed)}'`;
          }

          // Fallback for normal values
          return `'${value.toString().replace(/'/g, "''")}'`;
        });

        const checkExistQuery = `
          IF NOT EXISTS (
            SELECT 1 FROM ${tableName} WHERE ${whereClause}
          )
          BEGIN
            INSERT INTO ${tableName} (${columns.join(", ")})
            VALUES (${values.join(", ")});
          END
        `;

        return new Promise((resolveInsert, rejectInsert) => {
          sql.query(targetConnString, checkExistQuery, (insertErr) => {
            if (insertErr) {
              console.error(`❌ Insert error in ${tableName}:`, insertErr);
              return rejectInsert(insertErr);
            }
            resolveInsert();
          });
        });
      });

      Promise.allSettled(insertPromises)
        .then((results) => {
          const failed = results.filter(r => r.status === 'rejected');
          if (failed.length > 0) {
            console.warn(`⚠️ ${failed.length} rows failed to insert into ${tableName}.`);
          } else {
            console.log(`✅ All rows copied successfully to ${tableName}.`);
          }
          resolve(); // Always resolve, even if some rows failed
        })
        .catch((insertErr) => {
          console.error(`❌ Error during inserts for ${tableName}:`, insertErr);
          reject(insertErr);
        });
    });
  });
}





