//To add a new ledger group
app.post("/save-ledger", (req, res) => {
  const conn = req.session.conn;
  const {
    ledgerName,
    alias,
    altAlias,
    LedgerGroup1,
    subGroup,
    category,
    PostingLedger,
    pearlsSetting,
    address1,
    address2,
    phone1,
    phone2,
    fax,
    email,
    pan,
    maturityDate,
    remarks,
  } = req.body;

  // Map category to initials
  const categoryMap = {
    Others: "O",
    Cash: "C",
    Bank: "B",
    "Account Type": "AT",
    Customer: "CU",
  };
  const categoryInitial = categoryMap[category] || null;

  const queryLedgerGroup = `SELECT LgrGrpID FROM tbLedgerGroup WHERE GrpName = ?`;
  const queryLedgerSubGroup = `SELECT LgrSubGrpID FROM tbLedgerSubGroup WHERE SubGrpName = ?`;
  const queryPostingLedger = `SELECT GLID FROM tbLedgerMaster WHERE GLName = ?`;
  const insertQuery = `
      INSERT INTO tbLedgerMaster
      (GLName, GlAlias, AltAlias, LgrGrpID, LgrSubGrpID, Category, GLIDTransfer, PEARLSSetting, Address1, Address2, Phone1, Phone2, Fax, Email, Pan, MaturityDate, Remarks)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `;

  sql.open(conn, (err, conn) => {
    if (err) {
      console.error("Database connection error:", err);
      return res.status(500).send({ success: false, message: "Database connection error" });
    }

    // Step 1: Get LgrGrpID
    conn.query(queryLedgerGroup, [LedgerGroup1], (err, ledgerGroupResult) => {
      if (err) {
        console.error("Error querying Ledger Group:", err);
        return res.status(500).send({ success: false, message: "Error querying Ledger Group" });
      }
      if (!ledgerGroupResult[0]?.LgrGrpID) {
        return res.status(400).send({ success: false, message: "Ledger Group not found" });
      }

      const lgrGrpID = ledgerGroupResult[0].LgrGrpID;

      // Step 2: Get LgrSubGrpID
      conn.query(queryLedgerSubGroup, [subGroup], (err, subGroupResult) => {
        if (err) {
          console.error("Error querying Ledger SubGroup:", err);
          return res.status(500).send({ success: false, message: "Error querying Ledger SubGroup" });
        }
        if (!subGroupResult[0]?.LgrSubGrpID) {
          return res.status(400).send({ success: false, message: "Ledger SubGroup not found" });
        }

        const lgrSubGrpID = subGroupResult[0].LgrSubGrpID;

        // Step 3: Get Posting Ledger GLID
        conn.query(queryPostingLedger, [PostingLedger], (err, postingLedgerResult) => {
          if (err) {
            console.error("Error querying Posting Ledger:", err);
            return res.status(500).send({ success: false, message: "Error querying Posting Ledger" });
          }
          if (!postingLedgerResult[0]?.GLID) {
            return res.status(400).send({ success: false, message: "Posting Ledger not found" });
          }

          const glidTransfer = postingLedgerResult[0].GLID;

          // Step 4: Insert
          conn.query(
            insertQuery,
            [
              ledgerName,
              alias,
              altAlias,
              lgrGrpID,
              lgrSubGrpID,
              categoryInitial,
              glidTransfer,
              pearlsSetting,
              address1,
              address2,
              phone1,
              phone2,
              fax,
              email,
              pan,
              maturityDate,
              remarks,
            ],
            (err, result) => {
              if (err) {
                console.error("Error inserting Ledger:", err);
                return res.status(500).send({
                  success: false,
                  message: "Error inserting Ledger",
                });
              }

              console.log("Ledger saved successfully");
              return res.status(201).send({
                success: true,
                message: "Ledger saved successfully!",
              });
            }
          );
        });
      });
    });
  });
});


