app.post("/update-ledger", (req, res) => {
  const conn = req.session.conn;
  const {
    ledgerID,
    ledgerName,
    alias,
    altAlias,
    LedgerGroup1,
    subGroup,
    category,
    PostingLedger,
    pearlsSetting,
    address1,
    address2,
    phone1,
    phone2,
    fax,
    email,
    pan,
    maturityDate,
    remarks,
    username,
  } = req.body;

  // Map category to initials
  const categoryMap = {
    Others: "O",
    Cash: "C",
    Bank: "B",
    "Account Type": "AT",
    Customer: "CU",
  };
  const categoryInitial = categoryMap[category] || null;

  const queryLedgerGroup = `SELECT LgrGrpID FROM tbLedgerGroup WHERE GrpName = ?`;
  const querySubGroup = `SELECT LgrSubGrpID FROM tbLedgerSubGroup WHERE SubGrpName = ?`;
  const queryPostingLedger = `SELECT GLID FROM tbLedgerMaster WHERE GLName = ?`;
  const queryGetUserID = `SELECT UserID FROM dbo.tbUserMaster WHERE UserName = ?`;

  // Execute the query to get the UserID
  sql.query(connectionString, queryGetUserID, [username], (err, userResult) => {
    if (err) {
      console.error("Error retrieving UserID:", err);
      return res.status(500).send("Error retrieving UserID.");
    }

    if (userResult.length > 0) {
      const userID = userResult[0].UserID;
      console.log(`Retrieved UserID for username: ${username}`, userID);

      const updateQuery = `
        UPDATE tbLedgerMaster
        SET GLName = ?, GlAlias = ?, AltAlias = ?, LgrGrpID = ?, LgrSubGrpID = ?, Category = ?, GLIDTransfer = ?, PEARLSSetting = ?, 
            Address1 = ?, Address2 = ?, Phone1 = ?, Phone2 = ?, Fax = ?, Email = ?, Pan = ?, MaturityDate = ?, Remarks = ?, 
            LastSavedBy = ?, LastSavedDateTime = GETDATE()
        WHERE GLID = ?
      `;

      sql.open(conn, (err, conn) => {
        if (err) {
          console.error("Error connecting to the database:", err);
          return res.status(500).send("Database connection error");
        }

        // Step 1: Get LgrGrpID from tbLedgerGroup
        conn.query(queryLedgerGroup, [LedgerGroup1], (err, ledgerGroupResult) => {
          if (err) {
            console.error("Error querying Ledger Group:", err);
            return res.status(500).send("Error querying Ledger Group");
          }

          const lgrGrpID = ledgerGroupResult[0]?.LgrGrpID || null;

          // Step 2: Get LgrSubGrpID from tbLedgerSubGroup
          const subGroupString = subGroup ? String(subGroup) : "";
          conn.query(querySubGroup, [subGroupString], (err, subGroupResult) => {
            if (err) {
              console.error("Error querying Ledger SubGroup:", err);
              return res.status(500).send("Error querying Ledger SubGroup");
            }

            const lgrSubGrpID = subGroupResult[0]?.LgrSubGrpID || null;

            // Step 3: Get GLID for Posting Ledger
            conn.query(queryPostingLedger, [PostingLedger], (err, postingLedgerResult) => {
              if (err) {
                console.error("Error querying Posting Ledger:", err);
                return res.status(500).send("Error querying Posting Ledger");
              }

              const glidTransfer = postingLedgerResult[0]?.GLID || null;

              // Step 4: Update the Ledger Master
              conn.query(
                updateQuery,
                [
                  ledgerName,
                  alias,
                  altAlias,
                  lgrGrpID,
                  lgrSubGrpID,
                  categoryInitial,
                  glidTransfer,
                  pearlsSetting,
                  address1,
                  address2,
                  phone1,
                  phone2,
                  fax,
                  email,
                  pan,
                  maturityDate,
                  remarks,
                  userID,
                  ledgerID,
                ],
                (err, result) => {
                  if (err) {
                    console.error("Error updating tbLedgerMaster:", err);
                    return res.status(500).send("Error updating Ledger");
                  }

                  res.status(220).send({
                    success: true,
                    message: "Ledger updated successfully!",
                  });
                  console.log("Ledger updated successfully");
                }
              );
            });
          });
        });
      });
    }
  });
});

