app.post("/search-ledger", (req, res) => {
  const {
    ledgerNames,
    ledgerGroup3,
    category,
    address,
    phone,
    fax,
    email,
    panNo,
    incomeTaxNo,
  } = req.body;
  const conn = req.session.conn;

  // Define category initials
  const categoryInitials = {
    Others: "O",
    Cash: "C",
    Bank: "B",
    "Account Type": "AT",
    Customer: "CU",
    All: null, // If "All" is selected, ignore category filtering.
  };

  const selectedCategory = categoryInitials[category] || null;

  // Construct the query with joins and filters
  let query = `
      SELECT 
          lm.GLName, lm.GlAlias, lm.AltAlias, 
          lg.GrpName AS LedgerGroupName, lsg.SubGrpName AS LedgerSubGroupName, 
          lm.Address1, lm.Address2, lm.Phone1, lm.Phone2, lm.Fax, lm.Email, lm.Pan, lm.MaturityDate 
      FROM tbLedgerMaster lm
      LEFT JOIN tbLedgerGroup lg ON lm.LgrGrpID = lg.LgrGrpID
      LEFT JOIN tbLedgerSubGroup lsg ON lm.LgrSubGrpID = lsg.LgrSubGrpID
      WHERE 1=1
  `;

  // Apply filters
  if (ledgerNames) {
    // Ensure the search matches only the initial of the first word in GLName
    query += ` AND LEFT(lm.GLName, 1) = '${ledgerNames.charAt(0)}'`;
  }
  if (ledgerGroup3) {
    query += ` AND lg.GrpName LIKE '%${ledgerGroup3}%'`;
  }
  if (selectedCategory && selectedCategory !== null) {
    query += ` AND lm.Category = '${selectedCategory}'`;
  }
  if (address) {
    query += ` AND (lm.Address1 LIKE '%${address}%' OR lm.Address2 LIKE '%${address}%')`;
  }
  if (phone) {
    query += ` AND (lm.Phone1 LIKE '%${phone}%' OR lm.Phone2 LIKE '%${phone}%')`;
  }
  if (fax) {
    query += ` AND lm.Fax LIKE '%${fax}%'`;
  }
  if (email) {
    query += ` AND lm.Email LIKE '%${email}%'`;
  }
  if (panNo) {
    query += ` AND lm.Pan LIKE '%${panNo}%'`;
  }
  if (incomeTaxNo) {
    query += ` AND lm.IncomeTaxNo LIKE '%${incomeTaxNo}%'`;
  }

  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.error("Error executing query:", err);
      res
        .status(500)
        .send({ success: false, message: "Internal Server Error" });
    } else {
      res.json(rows);
    }
  });
});

