app.post("/insert-share-data", (req, res) => {
  const { generateDate, generateCode, totalShares, remarks } = req.body;
  const conn = req.session.conn;
  const shareRate = 100; // Default ShareRate
  const createdDateTime = new Date().toISOString(); // Current timestamp

  const fetchLastShareNoToQuery = `SELECT ISNULL(MAX(ShareNoTo), 0) AS LastShareNoTo FROM tbShareNumberMaster`;

  const insertMasterQuery = `
    INSERT INTO tbShareNumberMaster (GenerateNo, GenerateDate, TotalShare, ShareRate, Remarks, ShareNoFrom, ShareNoTo, CreatedDateTime)
    OUTPUT Inserted.ShareNumberID
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `;

  sql.query(conn, fetchLastShareNoToQuery, (err, rows) => {
    if (err) {
      console.error("Error fetching last ShareNoTo:", err.message);
      return res
        .status(500)
        .send({ success: false, message: "Failed to fetch last ShareNoTo." });
    }

    const lastShareNoTo = rows[0].LastShareNoTo || 0;
    const shareNoFrom = lastShareNoTo + 1; // Starting number
    const shareNoTo = shareNoFrom + parseInt(totalShares) - 1; // Ending number

    const masterParams = [
      generateCode,
      generateDate,
      totalShares,
      shareRate,
      remarks,
      shareNoFrom,
      shareNoTo,
      createdDateTime,
    ];

    sql.query(conn, insertMasterQuery, masterParams, (err, result) => {
      if (err) {
        console.error("Error inserting into tbShareNumberMaster:", err.message);
        return res
          .status(500)
          .send({
            success: false,
            message: "Failed to insert into tbShareNumberMaster.",
          });
      }

      const shareNumberID = result[0].ShareNumberID; // Get the generated ShareNumberID

      // Prepare detailsParams for bulk insert
      const detailsParams = [];
      for (let i = shareNoFrom; i <= shareNoTo; i++) {
        detailsParams.push([shareNumberID, i, i]); // SNo and ShareNo are the same
      }

      // Function to insert in batches
      const insertBatch = (params, batchSize = 1000) => {
        const batches = Math.ceil(params.length / batchSize);
        let currentIndex = 0;

        const insertNextBatch = () => {
          if (currentIndex < batches) {
            const currentBatch = params.slice(
              currentIndex * batchSize,
              (currentIndex + 1) * batchSize
            );
            const preparedQuery = currentBatch
              .map(() => "(?, ?, ?)")
              .join(", ");

            const bulkInsertQuery = `INSERT INTO tbShareNumberDetails (ShareNumberID, SNo, ShareNo) VALUES ${preparedQuery}`;

            const flatParams = currentBatch.flat();

            sql.query(conn, bulkInsertQuery, flatParams, (err) => {
              if (err) {
                console.error(
                  "Error inserting batch into tbShareNumberDetails:",
                  err.message
                );
                return res
                  .status(500)
                  .send({
                    success: false,
                    message: "Failed to insert into tbShareNumberDetails.",
                  });
              }

              currentIndex++;
              insertNextBatch();
            });
          } else {
            // All batches inserted
            res
              .status(200)
              .send({
                success: true,
                message: "Data inserted into both tables successfully.",
              });
          }
        };

        insertNextBatch();
      };

      // Start inserting in batches
      insertBatch(detailsParams, 1000); // Set batch size to 1000
    });
  });
});

