app.get("/journal-voucher-list", (req, res) => {
  const conn = req.session.conn;
  const voucherType = req.query.type;
  
  if (!conn) {
    return res.status(500).send("Database connection is not available.");
  }

  if (!voucherType) {
    return res.status(400).send("Voucher type is required.");
  }

  let udvNo;

  if (voucherType === "journal-voucher") {
    udvNo = 1;
  } else if (voucherType === "transaction") {
    udvNo = 6;
  } else if (voucherType === "receipt-voucher") {
    udvNo = 2;
  } else if (voucherType === "payment-voucher") {
    udvNo = 3;
  } else if (voucherType === "collection") {
    udvNo = 7;
  } else if (voucherType === "distribution") {
    udvNo = 8;
  } else if (voucherType === "interest-posting") {
    udvNo = 9;
  } else if (voucherType === "multiple-transaction") {
    udvNo = 5;
  } else if (voucherType === "auto-journal") {
    udvNo = 4;
  } else {
    return res.status(400).send("Invalid voucher type.");
  }

  const query = `
        SELECT VoucherNo
        FROM tbJournalMaster
        WHERE UDVNo = ?
        ORDER BY VoucherNo;
    `;

  sql.query(conn, query, [udvNo], (err, rows) => {
    if (err) {
      console.error("Error querying tbJournalMaster:", err);
      return res.status(500).send("Error fetching journal voucher numbers.");
    }

    const vouchers = Array.isArray(rows)
      ? rows.map((row) => ({ voucherNo: row.VoucherNo }))
      : [];

    res.json({ vouchers });
  });
});

app.get("/getSubLedgerDetails", (req, res) => {
  const { SlAlias } = req.query;
  console.log("SlAlias", SlAlias);
  const conn = req.session.conn;
  if (!SlAlias) {
    return res.json({ error: "SlAlias is required" });
  }

  // Query to get data from tbSubLedgerMaster
  const querySubLedger = `
        SELECT SLName, GLID, SLID 
        FROM dbo.tbSubLedgerMaster 
        WHERE SlAlias = ?`;

  sql.query(
    conn,
    querySubLedger,
    [SlAlias],
    (errSubLedger, subLedgerResult) => {
      if (errSubLedger || subLedgerResult.length === 0) {
        return res.json({ error: "Sub Ledger not found" });
      }

      const { SLName, GLID, SLID } = subLedgerResult[0];

      // Query to get GLName from tbLedgerMaster
      const queryLedger = `
            SELECT GLName 
            FROM dbo.tbLedgerMaster 
            WHERE GLID = ?`;

      sql.query(conn, queryLedger, [GLID], (errLedger, ledgerResult) => {
        if (errLedger || ledgerResult.length === 0) {
          return res.json({ error: "Ledger not found" });
        }

        const GLName = ledgerResult[0].GLName;
        console.log("glame", GLName);

        // Query to calculate balance from tbJournalDetails
        const queryJournalDetails = `
                SELECT DrAmount, CrAmount 
                FROM dbo.tbJournalDetails 
                WHERE SLID = ?`;

        sql.query(
          conn,
          queryJournalDetails,
          [SLID],
          (errJournal, journalResult) => {
            if (errJournal) {
              return res.json({ error: "Error querying journal details" });
            }

            let balance = 0;
            journalResult.forEach((row) => {
              const drAmount = row.DrAmount || 0;
              const crAmount = row.CrAmount || 0;
              balance += crAmount - drAmount;
            });
            console.log("balance", balance);
            // Respond with all required details
            res.json({
              SLName,
              GLName,
              Balance: balance,
            });
          }
        );
      });
    }
  );
});

