// Helper function to format date values
function formatRowDates(row) {
  const formattedRow = { ...row };
  for (const key in row) {
    if (row[key] instanceof Date) {
      formattedRow[key] = row[key].toISOString().slice(0, 10); // Convert Date to YYYY-MM-DD format
    }
  }
  return formattedRow;
}

// Helper function to generate HTML table
function generateTable(rows) {
  if (rows.length === 0) {
    return `<p>No results found.</p>`;
  }

  // Extract column names from the first row
  const columnNames = Object.keys(rows[0]);

  // Create table header
  let table = `<table>`;
  table += `<thead><tr>`;
  columnNames.forEach((col) => {
    table += `<th>${col}</th>`;
  });
  table += `</tr></thead>`;

  // Create table body
  table += `<tbody>`;
  rows.forEach((row) => {
    const formattedRow = formatRowDates(row); // Format date values
    table += `<tr>`;
    columnNames.forEach((col) => {
      table += `<td>${formattedRow[col] !== null ? formattedRow[col] : ""
        }</td>`;
    });
    table += `</tr>`;
  });
  table += `</tbody></table>`;

  return table;
}

// Endpoint to execute SQL query
app.post("/execute-query", (req, res) => {
  const userQuery = req.body.query;
  const conn = req.session.conn;

  sql.query(conn, userQuery, (err, rows) => {
    if (err) {
      res.status(500).send(`<p style="color: red;">Error: ${err.message}</p>`);
      return;
    }

    const resultsTable = generateTable(rows);
    res.send(resultsTable);
  });
});

app.get("/get-tables", (req, res) => {
  const conn = req.session.conn;
  const dbName = req.session.dbName;

  if (!conn || !dbName) {
    console.error("Connection or database name is missing");
    return res
      .status(400)
      .json({ error: "Connection or database name is missing" });
  }

  const query = `
      SELECT TABLE_NAME 
      FROM INFORMATION_SCHEMA.TABLES 
      WHERE TABLE_TYPE = 'BASE TABLE' AND TABLE_CATALOG = ?;
  `;



  sql.query(conn, query, [dbName], (err, rows) => {
    if (err) {
      console.error("Error fetching tables:", err);
      return res.status(500).json({ error: "Error retrieving tables" });
    }
    res.json(rows);
  });
});

app.get("/get-columns", (req, res) => {
  const conn = req.session.conn;
  const tableName = req.query.table;

  if (!tableName) {
    return res.status(400).send("Table name is required");
  }

  const query = `
      SELECT COLUMN_NAME 
      FROM INFORMATION_SCHEMA.COLUMNS 
      WHERE TABLE_NAME = '${tableName}';
  `;

  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.error("Error fetching columns:", err);
      return res.status(500).send("Error retrieving columns");
    }
    res.json(rows);
  });
});

app.post("/generate-share-transaction-no", (req, res) => {
  const query = `
      SELECT MAX(TransactionNo) AS MaxTransactionNo 
      FROM tbShareTransactionMaster;
  `;
  const conn = req.session.conn;

  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.error("Error querying the database:", err);
      return res.status(500).json({ error: "Database query failed" });
    }

    let newTransactionNo = "ST000001"; // Default value if no records exist
    if (rows && rows[0]?.MaxTransactionNo) {
      const maxTransactionNo = rows[0].MaxTransactionNo;
      const numericPart = parseInt(maxTransactionNo.slice(2)) + 1; // Increment numeric part
      newTransactionNo = `ST${numericPart.toString().padStart(6, "0")}`; // Format to 8 characters
    }

    console.log("Generated TransactionNo:", newTransactionNo);
    res.json({ transactionNo: newTransactionNo });
  });
});

