app.post("/insert-share-transaction-data", async (req, res) => {
  const {
    STransactionNo,
    STransactionDate,
    GLName,
    STransactionType,
    shareAccountAlias,
    STransferAlias,
    STotalShare,
    Remarks,
    STCreatedBy,
  } = req.body;
  const conn = req.session.conn;
  const createdDateTime = new Date().toISOString();

  try {
    const queryAsync = util.promisify(sql.query).bind(sql);

    // Fetch GLID
    const glidQuery = `SELECT GLID FROM tbLedgerMaster WHERE GLName = ?`;
    const glidResult = await queryAsync(conn, glidQuery, [GLName]);
    if (!glidResult.length) throw new Error("GLID not found");
    const GLID = glidResult[0].GLID;

    // Fetch SLID
    const slidQuery = `SELECT SLID FROM tbSubLedgerMaster WHERE SlAlias = ?`;
    const slidResult = await queryAsync(conn, slidQuery, [shareAccountAlias]);
    if (!slidResult.length) throw new Error("SLID not found");
    const SLID = slidResult[0].SLID;

    const createdQuery = `SELECT UserID FROM tbUserMaster WHERE UserName = ?`;
    const createdResult = await queryAsync(connectionString, createdQuery, [
      STCreatedBy,
    ]);
    if (!createdResult.length) throw new Error("Created query not found");
    const createuserID = createdResult[0].UserID;

    // Fetch SLID for the transfer alias if provided
    let transSLID = null;
    if (STransferAlias) {
      const translidQuery = `SELECT SLID FROM tbSubLedgerMaster WHERE SlAlias = ?`;
      const translidResult = await queryAsync(conn, translidQuery, [
        STransferAlias,
      ]);
      if (translidResult.length) {
        transSLID = translidResult[0].SLID;
      }
    }

    // Fetch last ShareIDTo
    const fetchLastShareNoQuery = `SELECT ISNULL(MAX(ShareIDTo), 0) AS LastShareIDTo FROM tbShareTransactionMaster`;
    const lastShareResult = await queryAsync(conn, fetchLastShareNoQuery);
    const lastShareNoTo = lastShareResult[0]?.LastShareIDTo || 0;

    const shareNoFrom = lastShareNoTo + 1;
    const shareNoTo = shareNoFrom + parseInt(STotalShare) - 1;

    // Insert into Master Table
    const insertMasterQuery = `
      INSERT INTO tbShareTransactionMaster
      (TransactionNo, TransactionType, GLID, SLID, GLIDTransferTo, SLIDTransferTo, TransactionDate, TotalShare, ShareIDFrom, ShareIDTo, CreatedBy, CreatedDateTime, Remarks)
      OUTPUT Inserted.ShareTransactionID
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `;

    const GLIDTransferTo = STransactionType === "Transfer" ? GLID : null; // Assign GLID if Transfer, otherwise null

    const masterParams = [
      STransactionNo,
      STransactionType,
      GLID,
      SLID,
      GLIDTransferTo,
      transSLID,
      STransactionDate,
      STotalShare,
      shareNoFrom,
      shareNoTo,
      createuserID,
      createdDateTime,
      Remarks,
    ];
    const masterResult = await queryAsync(
      conn,
      insertMasterQuery,
      masterParams
    );

    const shareTransactionID = masterResult[0].ShareTransactionID;

    // Prepare details for batch insert
    const detailsParams = [];
    for (let i = shareNoFrom; i <= shareNoTo; i++) {
      detailsParams.push([shareTransactionID, i, i]); // ShareID is the same as SNo
    }

    // Insert in batches
    const batchSize = 1000;
    for (let i = 0; i < detailsParams.length; i += batchSize) {
      const batch = detailsParams.slice(i, i + batchSize);
      const placeholders = batch.map(() => "(?, ?, ?, 0)").join(", ");
      const insertDetailsQuery = `INSERT INTO tbShareTransactionDetails (ShareTransactionID, Sno, ShareID, Sold) VALUES ${placeholders}`;
      const flatParams = batch.flat();
      await queryAsync(conn, insertDetailsQuery, flatParams);
    }

    res
      .status(200)
      .send({
        success: true,
        message: "Data inserted into both tables successfully.",
      });
  } catch (err) {
    console.error("Error:", err.message);
    res.status(500).send({ success: false, message: err.message });
  }
});
