app.post("/search-transactions", (req, res) => {
  const { transactionNo, accountNo, dateFrom, dateTo, transactionType } =
    req.body;
  const conn = req.session.conn;

  let query = `
    SELECT 
    stm.TransactionNo,
    stm.TransactionDate,
    stm.TransactionType,
    stm.SLID,
    stm4.SlAlias AS AccountAlias,       
    stm5.SlAlias AS AccountAlias1,    
    stm.GLID,
    stm0.GLName AS AccountType,          
    slm.SLName AS AccountName1,         
    stm.TotalShare,
    stm.ShareIDFrom,
    stm.ShareIDTo,
    stm.SLIDTransferTo,
    slm2.SLName AS AccountName2,         -- Account name from tbSubLedgerMaster (second alias)
    stm.CreatedBy,
    um.UserName AS CreatedUser,          -- Created user from SAJILODB.dbo.tbUserMaster
    stm.CreatedDateTime
FROM tbShareTransactionMaster stm
    LEFT JOIN tbSubLedgerMaster stm4 ON stm.SLID = stm4.SLID               -- Join to get AccountAlias from tbSubLedgerMaster
    LEFT JOIN tbSubLedgerMaster stm5 ON stm.SLIDTransferTo = stm5.SLID                  -- Join to get AccountAlias1 from tbLedgerMaster
    LEFT JOIN tbLedgerMaster stm0 ON stm.GLID = stm0.GLID                   -- Join to get AccountType from tbLedgerMaster
    LEFT JOIN tbSubLedgerMaster slm ON stm.SLID = slm.SLID                  -- Join to get AccountName1 from tbSubLedgerMaster
    LEFT JOIN tbSubLedgerMaster slm2 ON stm.SLIDTransferTo = slm2.SLID      -- Join to get AccountName2 from tbSubLedgerMaster
    LEFT JOIN SAJILODB.dbo.tbUserMaster um ON stm.CreatedBy = um.UserID      -- Cross-database join for CreatedBy
WHERE 1=1


  `;

  const params = [];

  if (transactionNo) {
    query += " AND stm.TransactionNo = ?";
    params.push(transactionNo);
  }

  if (accountNo) {
    query += `
          AND stm.SLID IN (
              SELECT SLID FROM tbSubLedgerMaster WHERE SlAlias = ?
          )
      `;
    params.push(accountNo);
  }

  if (dateFrom && dateTo) {
    query += " AND stm.TransactionDate BETWEEN ? AND ?";
    params.push(dateFrom, dateTo);
  }

  if (transactionType) {
    query += " AND stm.TransactionType = ?";
    params.push(transactionType);
  }

  sql.query(conn, query, params, (err, results) => {
    if (err) {
      console.error("Error executing query:", err);
      return res.status(500).send("Error retrieving transactions");
    }

    res.json(results);
  });
});
