//Route To add a new Ledger Group
app.post("/add-ledger-group", (req, res) => {
  const { groupName, groupalias, altalias, remarks, parentGroup, grpCategory } =
    req.body;
  const conn = req.session.conn;
  if (!parentGroup) {
    return res
      .status(400)
      .send({ message: "Parent group is required.", success: false });
  }

  const fetchParentQuery = `
      SELECT LgrGrpID, IEAL 
      FROM tbLedgerGroup 
      WHERE GrpName = ?;
  `;

  sql.query(conn, fetchParentQuery, [parentGroup], (err, parentResults) => {
    if (err) {
      console.error("Error fetching parent group:", err);
      return res
        .status(500)
        .send({ message: "Internal server error. Try an", success: false });
    }

    if (!parentResults || parentResults.length === 0) {
      return res
        .status(400)
        .send({ message: "Parent group not found.", success: false });
    }

    const { LgrGrpID: parentMGrpID, IEAL: parentIEAL } = parentResults[0];

    // Ensure no null values are passed to the database
    const finalGroupName = groupName || "";
    const finalGroupAlias = groupalias || "";
    const finalAltAlias = altalias || "";
    const finalRemarks = remarks || "";
    const finalGrpCategory = grpCategory || ""; // Default to empty string if null or undefined

    if (!finalGroupName || !finalGroupAlias || !parentMGrpID || !parentIEAL) {
      console.error("Missing required parameters:", {
        groupName: finalGroupName,
        groupalias: finalGroupAlias,
        parentMGrpID,
        parentIEAL,
      });
      return res
        .status(400)
        .send({ message: "Missing required parameters.", success: false });
    }

    const insertQuery = `
          INSERT INTO tbLedgerGroup (GrpName, GrpAlias, AltAlias, MGrpID, Remarks, IEAL, GrpCategory)
          VALUES (?, ?, ?, ?, ?, ?, ?);
      `;

    const parameters = [
      finalGroupName,
      finalGroupAlias,
      finalAltAlias,
      parentMGrpID,
      finalRemarks,
      parentIEAL,
      finalGrpCategory, // Include GrpCategory in the query
    ];

    sql.query(conn, insertQuery, parameters, (insertErr, insertResults) => {
      if (insertErr) {
        console.error("Error inserting new ledger group:", insertErr);
        return res
          .status(500)
          .send({ message: "Failed to insert ledger group.", success: false });
      }

      res
        .status(200)
        .send({ message: "Ledger group added successfully.", success: true });
    });
  });
});

