// Route to delete ledger group from the database
app.post("/deleteLedgerGroup", (req, res) => {
  const { groupName } = req.body; // Group name to be deleted
  const conn = req.session.conn;

  // Check if the group name is provided
  if (!groupName) {
    return res
      .status(400)
      .send({ success: false, message: "Group Name is required" });
  }

  // Trim the group name to avoid hidden characters like spaces
  const groupNameTrimmed = groupName.trim();

  // Ensure we have a connection
  if (!conn) {
    return res
      .status(500)
      .send({ success: false, message: "Database connection not found" });
  }

  // Step 1: Check for any dependencies on the selected group
  const dependencyQuery = `
    SELECT 1
    FROM dbo.tbLedgerGroup
    WHERE MGrpID = (SELECT LgrGrpID FROM dbo.tbLedgerGroup WHERE GrpName = ?)
  `;

  // First check if there are any groups referencing the selected group
  sql.query(conn, dependencyQuery, [groupNameTrimmed], (err, result) => {
    if (err) {
      console.error(
        `Error checking dependencies for group "${groupNameTrimmed}":`,
        err
      );
      return res
        .status(500)
        .send({ success: false, message: "Error checking dependencies" });
    }

    if (result.length > 0) {
      // If a dependency is found, prevent deletion and return a message
      return res.status(400).send({
        success: false,
        message: `Cannot delete group "${groupNameTrimmed}" as it is being used by another group.`,
      });
    }

    // Step 2: If no dependencies, proceed with deletion
    const deleteQuery = `
      DELETE FROM dbo.tbLedgerGroup WHERE GrpName = ?
    `;

    // Execute the deletion query
    sql.query(conn, deleteQuery, [groupNameTrimmed], (err, result) => {
      if (err) {
        console.error(`Error deleting group "${groupNameTrimmed}":`, err);
        return res
          .status(500)
          .send({ success: false, message: "Error deleting group" });
      }

      // If no rows were affected, handle as an error
      if (result.affectedRows === 0) {
        console.log(`No group found for deletion: "${groupNameTrimmed}"`);
        return res.status(404).send({
          success: false,
          message: `Group "${groupNameTrimmed}" not found for deletion.`,
        });
      }

      // If the group was deleted successfully
      res.send({
        success: true,
        message: `Group "${groupNameTrimmed}" deleted successfully.`,
      });
    });
  });
});
