app.post("/edit-ledger-group", (req, res) => {
  const {
    groupName,
    groupalias,
    altalias,
    remarks,
    parentGroup,
    grpCategory,
    selectedLgrGrpID,
  } = req.body; // selectedLgrGrpID is passed from frontend
  const conn = req.session.conn;

  // Fetch the parent group details
  const fetchParentQuery = `
    SELECT LgrGrpID, IEAL 
    FROM tbLedgerGroup 
    WHERE GrpName = ?`;

  sql.query(conn, fetchParentQuery, [parentGroup], (err, parentResults) => {
    if (err) {
      console.error("Error fetching parent group:", err);
      return res
        .status(500)
        .send({
          message: "Internal server error. Try again later.",
          success: false,
        });
    }

    if (!parentResults || parentResults.length === 0) {
      return res
        .status(400)
        .send({ message: "Parent group not found.", success: false });
    }

    const { LgrGrpID: parentMGrpID, IEAL: parentIEAL } = parentResults[0];

    // Defaulting values to empty strings if they are undefined
    const finalGroupName = groupName || ""; // Make sure groupName is passed from the frontend
    const finalGroupAlias = groupalias || "";
    const finalAltAlias = altalias || "";
    const finalRemarks = remarks || "";
    const finalGrpCategory = grpCategory || "";

    // Check if required fields are missing
    if (!finalGroupName || !finalGroupAlias || !parentMGrpID || !parentIEAL) {
      console.error("Missing required parameters:", {
        groupName: finalGroupName,
        groupalias: finalGroupAlias,
        parentMGrpID,
        parentIEAL,
      });
      return res
        .status(400)
        .send({ message: "Missing required parameters.", success: false });
    }

    // The corrected UPDATE query
    const updateQuery = `
      UPDATE tbLedgerGroup 
      SET 
        GrpName = ?,   -- Update GrpName
        GrpAlias = ?,  -- Update GrpAlias
        AltAlias = ?,  -- Update AltAlias
        MGrpID = ?,    -- Update Parent MGrpID
        Remarks = ?,   -- Update Remarks
        IEAL = ?,      -- Update IEAL
        GrpCategory = ? -- Update GrpCategory
      WHERE LgrGrpID = ?`; // Use LgrGrpID in WHERE clause to target the specific group

    const parameters = [
      finalGroupName, // Set the new Group Name
      finalGroupAlias, // Update Group Alias
      finalAltAlias, // Update Alternate Alias
      parentMGrpID, // Set the Parent MGrpID
      finalRemarks, // Update Remarks
      parentIEAL, // Update IEAL (presumably for tracking or category)
      finalGrpCategory, // Update Group Category
      selectedLgrGrpID, // Use the LgrGrpID of the selected group to identify the record
    ];

    // Execute the update query
    sql.query(conn, updateQuery, parameters, (updateErr, updateResults) => {
      if (updateErr) {
        console.error("Error updating ledger group:", updateErr);
        return res
          .status(500)
          .send({ message: "Failed to update ledger group.", success: false });
      }

      res
        .status(200)
        .send({ message: "Ledger group updated successfully.", success: true });
    });
  });
});
// Route to add a new Ledger subgroup
app.post("/addLedgerSubGroup", (req, res) => {
  const {
    subgroup,
    subgroupalias,
    altalias,
    depriciation,
    LedgerGroup2,
    remark,
  } = req.body;

  const conn = req.session.conn;
  if (!conn) {
    return res.status(500).send("Database connection string is missing.");
  }

  const checkGroupQuery = `
      SELECT LgrGrpID, IEAL 
      FROM tbLedgerGroup 
      WHERE GrpName = ?
  `;

  const insertSubGroupQuery = `
      INSERT INTO tbLedgerSubGroup (
          SubGrpName, 
          SubGrpAlias, 
          AltAlias, 
          DepreciationPercent, 
          LgrGrpID, 
          IEAL, 
          Remarks
      ) VALUES (?, ?, ?, ?, ?, ?, ?)
  `;

  sql.open(conn, (err, conn) => {
    if (err) {
      console.error("Connection Error:", err);
      return res.status(500).send("Database connection failed.");
    }

    console.log("Checking Group for:", LedgerGroup2);
    conn.query(checkGroupQuery, [LedgerGroup2], (err, groupResult) => {
      if (err) {
        console.error("Group Query Error:", err);
        return res.status(500).send("Error querying tbLedgerGroup.");
      }

      if (groupResult.length === 0) {
        console.log("Group not found for:", LedgerGroup2);
        return res.status(400).send("Group not found.");
      }

      const { LgrGrpID, IEAL } = groupResult[0];
      console.log("Group Found:", { LgrGrpID, IEAL });

      conn.query(
        insertSubGroupQuery,
        [
          subgroup,
          subgroupalias,
          altalias,
          depriciation || 0, // Default value for depreciation
          LgrGrpID,
          IEAL,
          remark,
        ],
        (err) => {
          if (err) {
            console.error("Insert Error:", err);
            return res.status(500).send({
              success: false,
              message: "Error inserting into tbLedgerSubGroup.",
              error: err.message,
            });
          }

          res
            .status(200)
            .send({
              success: true,
              message: "Ledger Sub Group added successfully.",
            });
        }
      );
    });
  });
});
