app.post("/search-interest-method", (req, res) => {
  const { ISMethod, ISLedger, ISEffectiveDateFrom, ISEffectiveDateTo } =
    req.body;
  const conn = req.session.conn; // Assuming session contains the connection string

  let query = `
      SELECT 
          stm.GLID,
          stm0.GLName AS AccountType,
          stm.MethodID,
          stm1.InterestRate AS IntRate,
          stm.EffectiveDate,
          stm.InterestMethod,
          stm.TaxRate,
          stm.CreatedBy,
          um.UserName AS Creator,
          stm.CreatedDateTime,
          stm.LastSavedBy,
          um1.UserName AS Modifier,
          stm.LastSavedDateTime
      FROM tbInterestCalculationMethods stm
      LEFT JOIN tbLedgerMaster stm0 ON stm.GLID = stm0.GLID
      LEFT JOIN tbInterestCalculationMethodsDetails stm1 ON stm.MethodID = stm1.MethodID  
      LEFT JOIN SAJILODB.dbo.tbUserMaster um ON stm.CreatedBy = um.UserID 
      LEFT JOIN SAJILODB.dbo.tbUserMaster um1 ON stm.LastSavedBy = um1.UserID 
      WHERE 1=1
  `;
  const params = [];

  if (ISMethod) {
    query += " AND stm.InterestMethod = ?";
    params.push(ISMethod);
  }

  if (ISLedger) {
    query += `
          AND stm.GLID IN (
              SELECT GLID FROM tbLedgerMaster WHERE GLName = ?
          )
      `;
    params.push(ISLedger);
  }

  if (ISEffectiveDateFrom && ISEffectiveDateTo) {
    query += " AND stm.EffectiveDate BETWEEN ? AND ?";
    params.push(ISEffectiveDateFrom, ISEffectiveDateTo);
  }

  sql.query(conn, query, params, (err, results) => {
    if (err) {
      console.error("Database query error:", err);
      return res.status(500).json({ error: "Failed to fetch data." });
    }
    // Return an empty array if no results are found
    res.json(results);
  });
});

