app.post("/process-checked-values", (req, res) => {
  const { checkedValues, startDate, endDate } = req.body;
  const conn = req.session.conn;

  if (!checkedValues || checkedValues.length === 0) {
    return res.status(400).send({ message: "No values provided" });
  }

  // Prepare query dynamically based on the checkedValues
  const query = `
      SELECT 
          lm.GLName, 
          lm.GLAlias, 
          lm.GLID,
          COUNT(slm.GLID) AS SubLedgerCount,
          SUM(CASE WHEN slm.Gender = 'Male' THEN 1 ELSE 0 END) AS MaleCount,
          SUM(CASE WHEN slm.Gender = 'Female' THEN 1 ELSE 0 END) AS FemaleCount,
          SUM(CASE WHEN slm.Gender = 'Other' THEN 1 ELSE 0 END) AS OtherCount
      FROM tbLedgerMaster lm
      LEFT JOIN tbSubLedgerMaster slm 
          ON lm.GLID = slm.GLID 
          AND slm.CreatedDateTime BETWEEN ? AND ? 
          AND (slm.Closed != 1 OR slm.Closed IS NULL)
      WHERE lm.Category = 'AT' 
          AND (lm.SavingorLoan = 'Saving' OR lm.SavingorLoan = 'Loan')
          AND (${checkedValues
      .map(() => `(lm.GLName = ? AND lm.GLAlias = ?)`)
      .join(" OR ")})
      GROUP BY lm.GLName, lm.GLAlias, lm.GLID
      HAVING COUNT(slm.GLID) > 0;
  `;

  // Prepare the parameters for the query
  const params = [
    startDate,
    endDate,
    ...checkedValues.flatMap(({ GLName, GLAlias }) => [GLName, GLAlias]),
  ];

  sql.query(conn, query, params, (err, results) => {
    if (err) {
      console.error("Database query failed:", err);
      return res
        .status(500)
        .send({ message: "Database query failed", error: err });
    }

    res.send(results);
  });
});

