app.post("/get-account-analysis-values", (req, res) => {
  const conn = req.session.conn;
  const { startDate, endDate, page = 1, pageSize = 1000 } = req.body;
  const offset = (page - 1) * pageSize;

  const query = `
      SELECT 
          tbSubLedgerMaster.SLName,
          tbSubLedgerMaster.Phone1,
          tbSubLedgerMaster.Mobile,
          tbSubLedgerMaster.SlAlias,
          tbLedgerMaster.GLName,
          tbSubLedgerMaster.GraceMonths
      FROM 
          tbSubLedgerMaster
      JOIN 
          tbLedgerMaster ON tbSubLedgerMaster.GLID = tbLedgerMaster.GLID
      WHERE 
          tbSubLedgerMaster.[Closed] != 1
          AND tbLedgerMaster.Category = 'AT'
          AND tbLedgerMaster.SavingorLoan IN ('Saving', 'loan')
      ORDER BY tbSubLedgerMaster.GLID ASC, tbSubLedgerMaster.SLName ASC
      OFFSET ? ROWS FETCH NEXT ? ROWS ONLY;
  `;

  sql.query(conn, query, [offset, pageSize], (err, results) => {
    if (err) {
      console.error("Error executing query:", err);
      res.status(500).json({ error: "Database query error" });
      return;
    }
    console.log("y", results);
    res.json(results);
  });
});

app.post("/process-second-checked-values", (req, res) => {
  const conn = req.session.conn;
  const { startDate, endDate, selectedGLNames = [] } = req.body;

  // Base query
  let query = `
      SELECT  
      tbLedgerMaster.GLName,
          tbSubLedgerMaster.SLName,
          tbSubLedgerMaster.SlAlias,
          tbSubLedgerMaster.Phone1 AS Phone,
          tbSubLedgerMaster.Mobile,
          tbSubLedgerMaster.MobileAlert
      FROM 
          tbSubLedgerMaster
      JOIN 
          tbLedgerMaster ON tbSubLedgerMaster.GLID = tbLedgerMaster.GLID
      WHERE 
          tbSubLedgerMaster.Closed != 1
          AND tbLedgerMaster.Category = 'AT'
          AND tbLedgerMaster.SavingorLoan IN ('Saving', 'loan')`;

  const params = [];

  // Add filtering for selected GLNames from checkboxes
  if (selectedGLNames.length > 0) {
    const placeholders = selectedGLNames.map(() => "?").join(",");
    query += ` AND tbLedgerMaster.GLName IN (${placeholders})`;
    params.push(...selectedGLNames);
  }

  // Add date range condition if provided
  if (startDate && endDate) {
    query += ` AND tbSubLedgerMaster.CreatedDateTime BETWEEN ? AND ?`;
    params.push(startDate, endDate);
  }

  // Order the results
  query += ` ORDER BY tbSubLedgerMaster.GLID ASC, tbSubLedgerMaster.SLName ASC;`;

  // Log the query and parameters for debugging
  console.log("Final Query:", query);
  console.log("Params:", params);

  // Execute the query
  sql.query(conn, query, params, (err, results) => {
    if (err) {
      console.error("Error executing query:", err);
      res.status(500).json({ error: "Database query error" });
      return;
    }

    // Log the results for debugging
    console.log("Query Results:", results);

    // Send the results to the frontend
    res.json(results);
  });
});

app.get("/fetch-savingloanandBank-data", (req, res) => {
  const conn = req.session.conn;
  const query = `
        SELECT 
    lm.GLName,
    lm.GLAlias,
    lm.SavingorLoan,
    COUNT(DISTINCT sl.SLID) AS GLID_Count, -- Counts rows in tbSubLedgerMaster only
    SUM(CASE WHEN jd.SLID IS NOT NULL THEN jd.CrAmount ELSE 0 END) - 
    SUM(CASE WHEN jd.SLID IS NOT NULL THEN jd.DrAmount ELSE 0 END) AS Net_Amount
FROM 
    tbLedgerMaster lm
INNER JOIN 
    tbSubLedgerMaster sl ON lm.GLID = sl.GLID
LEFT JOIN 
    tbJournalDetails jd ON sl.SLID = jd.SLID
WHERE 
    lm.Category IN ('AT')
    AND lm.SavingorLoan IN ('Saving', 'Loan')
    AND (sl.Closed IS NULL OR sl.Closed = 0)
GROUP BY 
    lm.GLName, lm.GLAlias, lm.SavingorLoan
ORDER BY 
    lm.GLName;


      `;

  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.error("Error executing query:", err);
      return res.status(500).send("Error fetching data");
    }
    res.json(rows);
  });
});

