app.post("/checked-loan-values", async (req, res) => {
  const { checkedLoanValues } = req.body; // Extract checkedLoanValues properly
  console.log("Checked Loan Values:", checkedLoanValues);

  if (!Array.isArray(checkedLoanValues)) {
    return res.status(400).send({ message: "Invalid input format" });
  }

  const conn = req.session.conn;

  const query = `
    SELECT 
        lm.GLName,
        lm.GLAlias,
        lm.SavingorLoan,
        COUNT(DISTINCT sl.SLID) AS GLID_Count,
        SUM(CASE WHEN jd.SLID IS NOT NULL THEN jd.CrAmount ELSE 0 END) - 
        SUM(CASE WHEN jd.SLID IS NOT NULL THEN jd.DrAmount ELSE 0 END) AS Net_Amount
    FROM 
        tbLedgerMaster lm
    INNER JOIN 
        tbSubLedgerMaster sl ON lm.GLID = sl.GLID
    LEFT JOIN 
        tbJournalDetails jd ON sl.SLID = jd.SLID
    WHERE 
        lm.Category IN ('AT')
        AND lm.SavingorLoan IN ('Loan')
        AND (sl.Closed IS NULL OR sl.Closed = 0)
        AND (${checkedLoanValues
      .map(() => `(lm.GLName = ? AND lm.GLAlias = ?)`)
      .join(" OR ")})
    GROUP BY 
        lm.GLName, lm.GLAlias, lm.SavingorLoan
    ORDER BY 
        lm.GLName;
  `;

  const queryParams = checkedLoanValues.flatMap(({ GLName, GLAlias }) => [
    GLName,
    GLAlias,
  ]);

  sql.query(conn, query, queryParams, (err, results) => {
    if (err) {
      console.error("Database query failed:", err);
      return res
        .status(500)
        .send({ message: "Database query failed", error: err });
    }

    res.json(results);
  });
});

