app.get("/fetchTotalAmountsForDE_BRS", (req, res) => {
  const { bankBookName, fromDate, toDate } = req.query;

  if (!bankBookName || !fromDate || !toDate) {
    return res.status(400).send("Missing parameters");
  }

  const conn = req.session.conn;

  // Step 1: Get GLID and GLAlias
  const getGLIDQuery = `
    SELECT GLID, GLAlias 
    FROM dbo.tbLedgerMaster 
    WHERE GLName = ?`;

  sql.query(conn, getGLIDQuery, [bankBookName], (err, result) => {
    if (err) return res.status(500).send("Error fetching GLID");

    if (result.length === 0) return res.status(404).send("Bank Book not found");

    const { GLID, GLAlias } = result[0];

    // Step 2: Fetch data from dbo.tbJournal including UDVNo
    const journalQuery = `
      SELECT 
        JournalID,
        VoucherNo,
        JV_Miti,
        DrAmount,
        CrAmount,
        ChequeNo,
        ChequeDate,
        UDVNo
      FROM dbo.tbJournal
      WHERE GLID = ?
        AND JV_Miti BETWEEN ? AND ?`;

    const params = [GLID, fromDate, toDate];

    sql.query(conn, journalQuery, params, (err, journalRows) => {
      if (err) return res.status(500).send("Error fetching journal data");

      if (journalRows.length === 0) {
        return res.json({ totalDrAmount: 0, totalCrAmount: 0, addSubRows: [], lessSubRows: [] });
      }

      // Step 3: Fetch MenuNames for all UDVNo values
      const udvNos = [...new Set(journalRows.map(row => row.UDVNo).filter(Boolean))];

      const udvQuery = `
        SELECT UDVNo, MenuName 
        FROM dbo.tbUserDefinedVoucher
        WHERE UDVNo IN (${udvNos.map(() => '?').join(',')})`;

      sql.query(conn, udvQuery, udvNos, (err, udvRows) => {
        if (err) return res.status(500).send("Error fetching UDV mappings");

        // Create a mapping from UDVNo => MenuName
        const udvMap = {};
        udvRows.forEach(row => {
          udvMap[row.UDVNo] = row.MenuName;
        });

        // Step 4: Process journal rows
        let totalDrAmount = 0;
        let totalCrAmount = 0;
        let addSubRows = [];
        let lessSubRows = [];

        journalRows.forEach(row => {
          const {
            JournalID,
            VoucherNo,
            JV_Miti,
            DrAmount,
            CrAmount,
            ChequeNo,
            ChequeDate,
            UDVNo
          } = row;

          const commonData = {
            journalID: JournalID,
            chequeno: ChequeNo,
            chequedate: ChequeDate,
            voucherno: VoucherNo,
            jv_miti: JV_Miti,
            glalias: GLAlias,
            type: udvMap[UDVNo] || UDVNo // fallback if mapping not found
          };

          if (CrAmount && CrAmount > 0) {
            totalCrAmount += CrAmount;
            addSubRows.push({
              ...commonData,
              amount: CrAmount.toFixed(2),
              label: `${bankBookName}(ID: ${JournalID})`
            });
          }

          if (DrAmount && DrAmount > 0) {
            totalDrAmount += DrAmount;
            lessSubRows.push({
              ...commonData,
              amount: DrAmount.toFixed(2),
              label: `${bankBookName} (ID: ${JournalID})`
            });
          }
        });

        res.json({
          totalDrAmount,
          totalCrAmount,
          addSubRows,
          lessSubRows
        });

        console.log("UDV Mapping:", udvMap);
        console.log("TotalDrAmt:", totalDrAmount);
        console.log("TotalCrAmtee:", totalCrAmount);
      });
    });
  });
});





// Endpoint to fetch totals for a GLID
app.get('/api/gl-totals/:glid', (req, res) => {
  const GLID = req.params.glid;
  const conn = req.session.conn;

  if (!conn) {
    return res.status(500).send("Database connection not found in session.");
  }

  const query = `
    SELECT DrAmount, CrAmount 
    FROM dbo.tbJournalDetails 
    WHERE GLID = @GLID AND (DrAmount IS NOT NULL OR CrAmount IS NOT NULL)
  `;

  // Prepare and execute the query
  const request = new sql.Request(conn);
  request.input('GLID', sql.Int, GLID); // Use appropriate type for GLID

  request.query(query, (err, result) => {
    if (err) {
      console.error("SQL error fetching amounts:", err);
      return res.status(500).send("Error fetching amounts for the selected GLID");
    }

    const rows = result.recordset || [];

    // Calculate the total DrAmount and CrAmount
    const totalDrAmount = rows.reduce((sum, row) => sum + (row.DrAmount || 0), 0);
    const totalCrAmount = rows.reduce((sum, row) => sum + (row.CrAmount || 0), 0);

    // Send the totals as a response
    res.json({ totalDrAmount, totalCrAmount });

    console.log("TotalDrAmt:", totalDrAmount);
    console.log("TotalCrAmt:", totalCrAmount);
  });
});


app.post("/process-savingTNA-checked-values", (req, res) => {
  const conn = req.session.conn;
  const selectedGLNames = req.body.selectedSavingGLNames;
  console.log("mesh", selectedGLNames);

  if (!selectedGLNames || selectedGLNames.length === 0) {
    return res.status(400).json({ error: "No GLNames received" });
  }

  // Format GLNames for SQL query
  const formattedGLNames = selectedGLNames.map((name) => `'${name}'`).join(",");
  const limitSavingC = req.body.limitSavingC || 10;
  const query = `
     SELECT TOP ${limitSavingC} 
          slm.SLName,
          slm.SlAlias,
          lm.GLName,
          COALESCE(ABS(SUM(jd.CrAmount) - SUM(jd.DrAmount)), 0) AS Balance
      FROM 
          tbSubLedgerMaster slm
      INNER JOIN 
          tbLedgerMaster lm ON lm.GLID = slm.GLID
      INNER JOIN 
          tbJournalDetails jd ON jd.SLID = slm.SLID
      WHERE 
          lm.GLName IN (${formattedGLNames}) 
          AND lm.SavingorLoan = 'Saving'
      GROUP BY 
          slm.SLName, slm.SlAlias, lm.GLName
      ORDER BY 
          Balance DESC;
  `;

  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.error("Error querying the database:", err);
      res.status(500).json({ error: "Database error" });
    } else {
      res.json(rows); // Send rows as JSON
    }
  });
});

