// Search Route
app.post("/search-mobile-alert", (req, res) => {
  const {
    ASAccountType,
    ASAccountNo,
    SSDFASCheckbox,
    EDFASCheckbox,
    ASServiceStartDateFrom,
    ASServiceStartDateTo,
    ASExpiryDateFrom,
    ASExpiryDateTo,
  } = req.body;

  console.log('checkedboxs', SSDFASCheckbox, EDFASCheckbox);

  const conn = req.session.conn;

  // Base Query
  let query = `
     SELECT 
       m.SLID, 
       s.SLName AS AccountName, 
       s.SLAlias AS AccountNo, 
       l.GLName AS AccountType, 
       m.EffectiveDate, 
       m.RenewDate, 
       m.ExpiryDate,
       m.CreatedBy,
       um.UserName AS Creator,
       m.CreatedDateTime, 
       m.LastSavedBy,
       um1.UserName AS Modifier,
       m.LastSavedDateTime
     FROM tbLedgerMaster l
     JOIN tbSubLedgerMaster s ON l.GLID = s.GLID
     JOIN tbMobileAlertSetting m ON s.SLID = m.SLID
     LEFT JOIN SAJILODB.dbo.tbUserMaster um ON m.CreatedBy = um.UserID 
     LEFT JOIN SAJILODB.dbo.tbUserMaster um1 ON m.LastSavedBy = um1.UserID 
     WHERE 1=1
  `;

  const params = [];

  // Account Type condition
  if (ASAccountType) {
    query += " AND l.GLName = ?";
    params.push(ASAccountType);
  }

  // Account No. condition
  if (ASAccountNo) {
    query += " AND s.SLAlias = ?";
    params.push(ASAccountNo);
  }

  // Date Filters with Checkbox Checks
  if (SSDFASCheckbox === "on" && ASServiceStartDateFrom && ASServiceStartDateTo) {
    query += " AND m.EffectiveDate BETWEEN ? AND ?";
    params.push(ASServiceStartDateFrom, ASServiceStartDateTo);
  }

  if (EDFASCheckbox === "on" && ASExpiryDateFrom && ASExpiryDateTo) {
    query += " AND m.ExpiryDate BETWEEN ? AND ?";
    params.push(ASExpiryDateFrom, ASExpiryDateTo);
  }

  // Execute SQL Query
  sql.query(conn, query, params, (err, rows) => {
    if (err) {
      console.error("Database Query Error:", err);
      return res.status(500).json({ error: "Database error" });
    }
    res.json(rows);
  });
});


app.post("/search-account-locked-unlocked", (req, res) => {
  const { ALAcType, ALAcStatus, AlAcNo, page = 1 } = req.body;
  const conn = req.session.conn;

  const limit = 8000; // Show 8000 results per page
  const offset = (page - 1) * limit; // Calculate offset

  let query = `
      SELECT 
          S.GLID,
          S.SlAlias,
          S.SLName,
          S.Phone1,
          S.Locked,
          L.GLName
      FROM tbSubLedgerMaster S
      LEFT JOIN tbLedgerMaster L ON S.GLID = L.GLID
      WHERE S.SLType <> 'S' 
      AND S.AccountOpenDate IS NOT NULL 
      AND S.GLID IS NOT NULL
  `;

  const params = [];

  if (ALAcType) {
    query += ` AND L.GLName = ?`;
    params.push(ALAcType);
  }

  if (ALAcStatus === "Locked") {
    query += " AND S.Locked = 1";
  } else if (ALAcStatus === "Unlocked") {
    query += " AND (S.Locked = 0 OR S.Locked IS NULL)";
  }

  if (AlAcNo) {
    query += " AND S.SlAlias = ?";
    params.push(AlAcNo);
  }

  // Add LIMIT and OFFSET for pagination
  query += ` ORDER BY S.GLID OFFSET ? ROWS FETCH NEXT ? ROWS ONLY`;
  params.push(offset, limit);

  sql.query(conn, query, params, (err, rows) => {
    if (err) {
      console.error("SQL Error:", err);
      return res.status(500).json({ error: "Database query failed" });
    }

    // Get total record count for pagination
    const countQuery = `SELECT COUNT(*) AS total FROM tbSubLedgerMaster S WHERE S.SLType <> 'S' 
                          AND S.AccountOpenDate IS NOT NULL 
                          AND S.GLID IS NOT NULL`;

    sql.query(conn, countQuery, [], (err, countResult) => {
      if (err) {
        console.error("SQL Error:", err);
        return res.status(500).json({ error: "Failed to fetch total records" });
      }

      const totalRecords = countResult[0].total;
      const totalPages = Math.ceil(totalRecords / limit);
      console.log("Total records", rows);
      res.json({
        results: rows,
        totalRecords,
        totalPages,
        currentPage: page,
      });
    });
  });
});

