app.post("/search-account-mapped-unmapped", (req, res) => {
  const {
    RAMAccType,
    RAMAccountStatus,
    RAMAccountNo,
    RAMAccountName,
    RAMRoute,
    RAMMemberID,
    page = 1,
  } = req.body;
  const conn = req.session.conn;

  const limit = 8000; // Show 8000 results per page
  const offset = (page - 1) * limit; // Calculate offset

  let query = `
      SELECT 
          S.GLID,
          S.SlAlias,
          S.SLName,
          S.Phone1,
          S.Locked,
          S.RouteID,
          R.Route,
          M.MemberID,
          M.MemberName,
          M.MemberAlias,
          L.GLName
      FROM tbSubLedgerMaster S
      LEFT JOIN tbLedgerMaster L ON S.GLID = L.GLID
      LEFT JOIN tbRouteMaster R ON S.RouteID = R.RouteID
      LEFT JOIN tbMemberMaster M ON S.MemberID = M.MemberID
      WHERE S.SLType <> 'S' 
      AND S.AccountOpenDate IS NOT NULL 
      AND S.GLID IS NOT NULL
  `;

  const params = [];

  if (RAMAccType) {
    query += ` AND L.GLName = ?`;
    params.push(RAMAccType);
  }

  if (RAMAccountStatus === "mapped") {
    query += " AND S.RouteID IS NOT NULL";
  } else if (RAMAccountStatus === "unmapped") {
    query += " AND (S.RouteID IS NULL)";
  }

  if (RAMAccountNo) {
    query += " AND S.SlAlias = ?";
    params.push(RAMAccountNo);
  }

  if (RAMAccountName) {
    query += " AND S.SLName = ?";
    params.push(RAMAccountName);
  }

  if (RAMRoute) {
    query += " AND R.Route = ?";
    params.push(RAMRoute);
  }

  if (RAMMemberID) {
    query += " AND M.MemberAlias = ?";
    params.push(RAMMemberID);
  }

  // Add LIMIT and OFFSET for pagination
  query += ` ORDER BY S.GLID OFFSET ? ROWS FETCH NEXT ? ROWS ONLY`;
  params.push(offset, limit);

  sql.query(conn, query, params, (err, rows) => {
    if (err) {
      console.error("SQL Error:", err);
      return res.status(500).json({ error: "Database query failed" });
    }

    // Get total record count for pagination
    const countQuery = `SELECT COUNT(*) AS total FROM tbSubLedgerMaster S WHERE S.SLType <> 'S' 
                          AND S.AccountOpenDate IS NOT NULL 
                          AND S.GLID IS NOT NULL`;

    sql.query(conn, countQuery, [], (err, countResult) => {
      if (err) {
        console.error("SQL Error:", err);
        return res.status(500).json({ error: "Failed to fetch total records" });
      }

      const totalRecords = countResult[0].total;
      const totalPages = Math.ceil(totalRecords / limit);
      console.log("Total records", rows);
      res.json({
        results: rows,
        totalRecords,
        totalPages,
        currentPage: page,
      });
    });
  });
});

