app.post("/copy-doc-class", (req, res) => {
  const {
    name,
    alias,
    phone1,
    phone2,
    address1,
    address2,
    faxNo,
    email,
    panNo,
    income,
    remarks,
  } = req.body;
  const conn = req.session.conn;

  // SQL query to insert data into dbo.tbDocClassMaster
  const query = `
        INSERT INTO dbo.tbDocClassMaster (DocClassName, DocClassAlias,  Phone1, Phone2, Address1, Address2, Fax, Email, Pan, IncomeTaxNo, LastSavedDateTime, Remarks)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, GETDATE(), ?)
    `;

  // Execute the SQL query
  sql.query(
    conn,
    query,
    [
      name,
      alias,
      phone1,
      phone2,
      address1,
      address2,
      faxNo,
      email,
      panNo,
      income,
      remarks,
    ],
    (err, result) => {
      if (err) {
        console.error("SQL error:", err);
        return res
          .status(500)
          .send({ message: "Error adding data.", success: false });
      }
      res
        .status(200)
        .send({ message: "Data added successfully!", success: true });
    }
  );
});
