app.post("/update-resaved-accounts", async (req, res) => {
  const { accounts, RSACreatedBy } = req.body;
  console.log(accounts, RSACreatedBy);
  const conn = req.session.conn;

  if (!accounts || accounts.length === 0) {
    return res
      .status(400)
      .json({ message: "No accounts selected", success: false });
  }

  try {
    // Query to get UserID from UserName
    const miniquery = `SELECT UserID FROM tbUserMaster WHERE UserName = ?`;
    sql.query(connectionString, miniquery, [RSACreatedBy], (err, result) => {
      if (err) {
        console.error("Error querying UserID:", err);
        return res
          .status(500)
          .json({ message: "Database query failed", success: false });
      }

      // Check if UserID is found
      if (!result.length) {
        return res
          .status(404)
          .json({ message: "User not found", success: false });
      }

      const createuserID = result[0].UserID;

      // Parameterized Query for security
      const query = `
              UPDATE tbSubLedgerMaster 
              SET LastSavedBy = ?, LastSavedDateTime = GETDATE() 
              WHERE SlAlias IN (${accounts.map(() => "?").join(",")})
          `;
      console.log(query);

      sql.query(conn, query, [createuserID, ...accounts], (err, result) => {
        if (err) {
          console.error("Database update error:", err);
          return res.status(500).json({ error: "Database update failed" });
        }

        res
          .status(200)
          .json({ success: true, message: "Accounts updated successfully!" });
      });
    });
  } catch (error) {
    console.error("Unexpected error:", error);
    res
      .status(500)
      .json({ message: "An unexpected error occurred", success: false });
  }
});

app.post("/display-dayslog-results", (req, res) => {
  const conn = req.session.conn;
  const query = `
SELECT
  COALESCE(ld1.M_Miti, CONVERT(VARCHAR, d.ClosedOpenedDate, 23)) AS ClosedOpenedMiti, 
  COALESCE(ld2.M_Miti, CONVERT(VARCHAR, d.CloseOpenDatetime, 120)) AS CloseOpenMiti,  -- Display CloseOpenDatetime with time
  d.CloseOpenUserID,
  d.CloseOpenType,
  u.UserName,
  d.CloseOpenDatetime  -- Display the full CloseOpenDatetime with time
FROM tbDayCloseLog d
LEFT JOIN SAJILODB.dbo.tbUserMaster u ON d.CloseOpenUserID = u.UserID
LEFT JOIN SAJILODB.dbo.tbLocalDate ld1 ON CONVERT(VARCHAR, d.ClosedOpenedDate, 23) = ld1.M_date
LEFT JOIN SAJILODB.dbo.tbLocalDate ld2 ON CONVERT(VARCHAR, CAST(d.CloseOpenDatetime AS DATETIME), 23) = ld2.M_date;  -- Match only the date portion
`;

  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.log(err);
      res.status(500).send("Error executing the query");
    } else {
      console.log(rows);
      res.json(rows);
    }
  });
});

const convertDateFormat = (dateString) => {
  const [year, month, day] = dateString.split("-");
  return `${day}/${month}/${year}`;
};

app.post("/display-show-status-logs", (req, res) => {
  const { SRAStartDate, SRAEndDate, DCCreatedBy } = req.body;
  const conn = req.session.conn;

  console.log("📥 Incoming Request Body:", req.body);

  if (!SRAStartDate || !SRAEndDate) {
    console.log("❌ Missing required dates.");
    return res.status(400).json({ error: "Both startDate and endDate are required" });
  }

  // Step 1: Get Date Setting
  const queryDT = `SELECT TOP 1 DateType FROM tbSystemSettings`;

  console.log("📡 Fetching DateType...");

  sql.query(conn, queryDT, (err, dtRes) => {
    if (err) {
      console.error("❌ Error fetching DateType:", err);
      return res.status(500).json({ error: "Failed to fetch date type" });
    }

    const DateType = dtRes[0].DateType;
    console.log("📌 System DateType:", DateType);

    const convertedStart = convertDateFormat(SRAStartDate);
    const convertedEnd = convertDateFormat(SRAEndDate);

    console.log("📅 Converted Dates (for LD only):", { convertedStart, convertedEnd });

    // Step 2: Get user ID
    const queryBy = `SELECT UserID FROM tbUserMaster WHERE UserName = ?`;

    console.log("📡 Fetching UserID for:", DCCreatedBy);

    sql.query(connectionString, queryBy, [DCCreatedBy], (err, userResult) => {
      if (err) {
        console.error("❌ Error querying UserID:", err);
        return res.status(400).json({ error: "Error querying UserID" });
      }

      const createUserID = userResult[0].UserID;
      console.log("👤 Found UserID:", createUserID);

      // Function to execute final query
      const runMainQuery = (startDate, endDate) => {
        console.log("🚀 Running final query with parameters:", {
          startDate,
          endDate,
          createUserID
        });

        const finalQuery = `
          SELECT 
            d.CloseOpenType, 
            d.ClosedOpenedDate,
            ld.M_Miti,
            ld.M_date
          FROM tbDayCloseLog d
          LEFT JOIN SAJILODB.dbo.tbLocalDate ld 
            ON CONVERT(VARCHAR, d.ClosedOpenedDate, 23) = ld.M_date
          WHERE d.ClosedOpenedDate BETWEEN ? AND ?
            AND d.CloseOpenUserID = ?
          ORDER BY d.ClosedOpenedDate ASC;
        `;

        sql.query(conn, finalQuery, [startDate, endDate, createUserID], (err2, rows) => {
          if (err2) {
            console.error("❌ Final SQL Error:", err2);
            return res.status(500).json({ error: "Final query failed" });
          }

          console.log("📦 Final Query Result Count:", rows.length);

          let formattedResults = rows.map(row => {
            let finalDate = DateType === "LD" ? row.M_Miti : row.ClosedOpenedDate;

            console.log("🧾 Formatting Row:", {
              rawClosedOpenedDate: row.ClosedOpenedDate,
              M_Miti: row.M_Miti,
              M_date: row.M_date,
              selectedFinalDate: finalDate
            });

            return {
              CloseOpenType: row.CloseOpenType,
              Date: finalDate,
              UserID: createUserID
            };
          });

          console.log("📤 Sending Final Formatted Output:", formattedResults);
          res.json(formattedResults);
        });
      };

      // If Datetype is AD → Use raw dates directly
      if (DateType !== "LD") {
        console.log("🟢 Using raw AD dates:", {
          start: SRAStartDate,
          end: SRAEndDate
        });
        return runMainQuery(SRAStartDate, SRAEndDate);
      }

      // If Datetype is LD → Convert first
      console.log("🔄 DateType is LD → Fetching corresponding AD dates...");

      const dateQuery = `SELECT M_date FROM tbLocalDate WHERE M_Miti = ?`;

      sql.query(connectionString, dateQuery, [convertedStart], (errS, startRes) => {
        if (errS || !startRes.length) {
          console.error("❌ Failed to convert Start Date:", errS);
          return res.status(500).json({ error: "Failed to convert start date" });
        }

        const finalStart = new Date(startRes[0].M_date);
        console.log("⏳ Converted Start → AD:", finalStart);

        sql.query(connectionString, dateQuery, [convertedEnd], (errE, endRes) => {
          if (errE || !endRes.length) {
            console.error("❌ Failed to convert End Date:", errE);
            return res.status(500).json({ error: "Failed to convert end date" });
          }

          const finalEnd = new Date(endRes[0].M_date);
          console.log("⏳ Converted End → AD:", finalEnd);

          console.log("📌 LD Mode → Using Converted Range:", {
            start: finalStart,
            end: finalEnd
          });

          runMainQuery(finalStart, finalEnd);
        });
      });
    });
  });
});




