app.get("/fetchSubGroups", (req, res) => {
  const ledgerGroup = req.query.ledgerGroup; // Retrieve the Ledger Group from the request query
  console.log(ledgerGroup);
  if (!ledgerGroup) {
    return res.status(400).send("Ledger Group is required");
  }

  // Step 1: Fetch the LgrGrpID for the selected Ledger Group from tbLedgerGroup
  const query1 = `
      SELECT LgrGrpID 
      FROM dbo.tbLedgerGroup 
      WHERE GrpName = ?
  `;
  const conn = req.session.conn; // Get the database connection from the session

  sql.query(conn, query1, [ledgerGroup], (err, rows) => {
    if (err) {
      console.error("Error fetching LgrGrpID:", err);
      return res.status(500).send("Error fetching LgrGrpID");
    }

    // If no matching Ledger Group found, return a message
    if (!rows || rows.length === 0) {
      return res.json({ message: "No matching Ledger Group found" });
    }

    // Step 2: Retrieve the LgrGrpID from the result
    const LgrGrpID = rows[0].LgrGrpID;

    // Step 3: Fetch sub-groups from the tbLedgerSubGroup table based on LgrGrpID
    const query2 = `
          SELECT SubGrpName
          FROM dbo.tbLedgerSubGroup
          WHERE LgrGrpID = ?
      `;

    sql.query(conn, query2, [LgrGrpID], (err, subGroupRows) => {
      if (err) {
        console.error("Error fetching Sub Groups:", err);
        return res.status(500).send("Error fetching Sub Groups");
      }

      // Step 4: Return the Sub Groups if found
      if (subGroupRows && subGroupRows.length > 0) {
        res.json({ subGroups: subGroupRows });
        console.log("Sub Groups found", subGroupRows);
      } else {
        res.json({ message: "No Sub Groups found for this Ledger Group" });
      }
    });
  });
});

