app.post("/delete-ledgermas-class", (req, res) => {
  const { name } = req.body; // Receive the document class name from the frontend
  const conn = req.session.conn; // Get the database connection from the session

  // Step 1: Find the GLID corresponding to the LedgerName
  const queryGLID = `
    SELECT GLID
    FROM dbo.tbLedgerMaster
    WHERE GLName = ?
  `;

  sql.query(conn, queryGLID, [name], (err, result) => {
    if (err) {
      console.error("Error retrieving GLID:", err);
      return res.status(500).send("Error retrieving GLID.");
    }

    if (result.length === 0) {
      // If no matching LedgermasterName is found
      return res.status(404).send("Ledger Master  not found.");
    }

    const glID = result[0].GLID; // Get the GLID from the result

    // Step 2: Check if the GLID exists in tbJournalDetails
    const queryCheckJournal = `
      SELECT 1
      FROM dbo.tbJournalDetails
      WHERE GLID = ?
    `;

    sql.query(conn, queryCheckJournal, [glID], (err, journalResult) => {
      if (err) {
        console.error("Error checking GLID in tbJournalDetails:", err);
        return res.status(500).send("Error checking GLID in tbJournalDetails.");
      }

      if (journalResult.length > 0) {
        // If the GLID is found in tbJournalDetails, do not allow deletion
        return res
          .status(400)
          .send(
            "Cannot delete Ledger Group because it is used in tbJournalDetails."
          );
      }

      // Step 3: If GLID is not found in tbJournalDetails, proceed to delete the selected Ledger Group
      const queryDeleteLedgerGroup = `
        DELETE FROM dbo.tbLedgerMaster
        WHERE GLID = ?
      `;

      sql.query(conn, queryDeleteLedgerGroup, [glID], (err, deleteResult) => {
        if (err) {
          console.error("SQL error deleting Ledger Group:", err);
          return res.status(500).send("Error deleting Ledger Group.");
        }

        res.send("Ledger group  deleted successfully!");
      });
    });
  });
});
