app.post("/update-subledger", (req, res) => {
  const conn = req.session.conn;
  const {
    subLedgerID,
    subLedgerName,
    subLedgerAlias,
    subLedgerAltAlias,
    postingLedger,
    address1,
    address2,
    phone1,
    phone2,
    fax,
    email,
    pan,
    remarks,
  } = req.body;

  console.log("Received SubledgerID: " + subLedgerID);
  console.log("Received PostingLedger: " + postingLedger);

  // Step 1: Query to get GLID from tbLedgerMaster based on PostingLedger (ledger name)
  const queryPostingLedger = `SELECT GLID FROM tbLedgerMaster WHERE GLName = ?`;

  // Step 2: Update query for the tbSubLedgerMaster table (now setting GLID)
  const updateQuery = `
      UPDATE tbSubLedgerMaster
      SET SLName = ?, SlAlias = ?, AltAlias = ?, GLID = ?, Address1 = ?, Address2 = ?, Phone1 = ?, Phone2 = ?, 
          Fax = ?, Email = ?, Pan = ?, Remarks = ?
      WHERE SLID = ?
  `;

  // Connect to the database
  sql.open(conn, (err, conn) => {
    if (err) {
      console.error("Error connecting to the database:", err);
      return res.status(500).send("Database connection error");
    }

    // Step 3: Query the tbLedgerMaster to get GLID based on PostingLedger
    conn.query(
      queryPostingLedger,
      [postingLedger],
      (err, postingLedgerResult) => {
        if (err) {
          console.error("Error querying Posting Ledger:", err);
          return res.status(500).send("Error querying Posting Ledger");
        }

        if (postingLedgerResult.length === 0) {
          // No matching ledger found for the given PostingLedger
          return res.status(400).send("Ledger not found");
        }

        // Step 4: Fetch the GLID for the posting ledger
        const glid = postingLedgerResult[0]?.GLID || null;

        // Step 5: Update the SubLedgerMaster table with the new data
        conn.query(
          updateQuery,
          [
            subLedgerName,
            subLedgerAlias, // Corrected field for SlAlias
            subLedgerAltAlias,
            glid, // Now we use GLID here
            address1,
            address2,
            phone1,
            phone2,
            fax,
            email,
            pan,
            remarks,
            subLedgerID, // The unique SLID used in the WHERE clause
          ],
          (err, result) => {
            if (err) {
              console.error("Error updating tbSubLedgerMaster:", err);
              return res.status(500).send("Error updating SubLedger");
            }

            // If the update is successful
            res
              .status(220)
              .send({
                success: true,
                message: "SubLedger updated successfully!",
              });
            console.log("SubLedger updated successfully");
          }
        );
      }
    );
  });
});
