app.post("/delete-subledgermas-class", (req, res) => {
  const { name } = req.body; // Receive the document class name from the frontend
  const conn = req.session.conn; // Get the database connection from the session

  // Step 1: Find the GLID corresponding to the LedgerName
  const querySLID = `
    SELECT SLID
    FROM dbo.tbSubLedgerMaster
    WHERE SLName = ?
  `;

  sql.query(conn, querySLID, [name], (err, result) => {
    if (err) {
      console.error("Error retrieving SLID:", err);
      return res.status(500).send("Error retrieving SLID.");
    }

    if (result.length === 0) {
      // If no matching LedgermasterName is found
      return res.status(404).send("Sub-Ledger Master  not found.");
    }

    const slID = result[0].SLID; // Get the GLID from the result

    // Step 2: Check if the GLID exists in tbJournalDetails
    const queryCheckJournal = `
      SELECT 1
      FROM dbo.tbJournalDetails
      WHERE SLID = ?
    `;

    sql.query(conn, queryCheckJournal, [slID], (err, journalResult) => {
      if (err) {
        console.error("Error checking SLID in tbJournalDetails:", err);
        return res.status(500).send("Error checking SLID in tbJournalDetails.");
      }

      if (journalResult.length > 0) {
        // If the GLID is found in tbJournalDetails, do not allow deletion
        return res
          .status(400)
          .send(
            "Cannot delete Sub-Ledger Group because it is used in tbJournalDetails."
          );
      }

      // Step 3: If GLID is not found in tbJournalDetails, proceed to delete the selected Ledger Group
      const queryDeleteLedgerGroup = `
        DELETE FROM dbo.tbSubLedgerMaster
        WHERE SLID = ?
      `;

      sql.query(conn, queryDeleteLedgerGroup, [slID], (err, deleteResult) => {
        if (err) {
          console.error("SQL error deleting Sub-Ledger Group:", err);
          return res.status(500).send("Error deleting Sub-Ledger Group.");
        }

        res.send("Sub-Ledger group  deleted successfully!");
      });
    });
  });
});
