app.post("/checkDeletionPermission", (req, res) => {
  const { shareIssueName } = req.body; // Get the share issue name from the request body
  const conn = req.session.conn; // Retrieve the database connection string from the session

  if (!shareIssueName) {
    return res
      .status(400)
      .send({ success: false, message: "Share issue name is required" });
  }

  // SQL query to check if the shareIssueName exists in tbShareTransactionMaster (GLID column)
  const query = `SELECT COUNT(*) AS count FROM dbo.tbShareTransactionMaster WHERE GLID = ?`;

  sql.query(conn, query, [shareIssueName], (err, rows) => {
    if (err) {
      console.error("Error checking deletion permission:", err);
      return res
        .status(500)
        .send({
          success: false,
          message: "Error checking deletion permission",
        });
    }

    // If the count is greater than 0, it means the shareIssueName exists in the tbShareTransactionMaster table
    if (rows[0].count > 0) {
      return res
        .status(403)
        .send({
          success: false,
          message: "Deletion is not allowed for this share issue due to Existence  in tbShareTransactionMaster",
        });
    }

    // If count is 0, deletion is allowed
    res.send({ success: true, message: "Deletion allowed" });
  });
});
