app.post("/update-AccInterest", (req, res) => {
  const { GLID, EditAccTypeIntsetName, EditISDeductTax, EditAccTypeIntsetTaxRate, EditISMethod, ISIgnoreAc, EditAccTypeIntSetremarks, formattedDate, username } = req.body;

  const conn = req.session.conn;  // Get the database connection from the session
  // Ensure  is a valid number
  let taxRate = parseFloat(EditAccTypeIntsetTaxRate.replace(/,/g, '').trim());
  console.log("Received taxrate: ", taxRate);
  console.log(typeof taxRate);

  if (isNaN(taxRate)) {
    return res.status(400).send({
      success: false,
      message: "Invalid  taxRate value",
    });
  }
  // Logging the received data for debugging
  console.log("Received data for update:", req.body);  // Log the received data

  // Step 1: Retrieve the corresponding newGLID from dbo.tbLedgerMaster based on EditAccTypeIntsetName
  const getGLIDQuery = `SELECT GLID FROM dbo.tbLedgerMaster WHERE GLName = ?`;

  sql.query(conn, getGLIDQuery, [EditAccTypeIntsetName], (err, result) => {
    if (err) {
      console.error("Error retrieving newGLID:", err);
      return res.status(500).send("Error retrieving newGLID.");
    }

    // Check if a corresponding GLID was found
    if (result.length > 0) {
      const newGLID = result[0].GLID;  // Retrieve the newGLID from the query result
      console.log("The new GLID is:", newGLID);
      const TAXRATE = taxRate;
      console.log("newtaxreate", typeof TAXRATE);
      // Step 2: Set Taxable column based on the boolean value of EditISDeductTax
      const taxableValue = EditISDeductTax ? 1 : 0;
      const ignoreacmon = ISIgnoreAc ? 1 : 0;

      // Step 3: Build the update query (now properly updating the GLID)
      const updateQuery = ` 
              UPDATE dbo.tbInterestCalculationMethods
              SET 
                  Remarks = ?,
                  LastSavedDateTime = GETDATE(), 
                  Taxable = ?,
                  IgnoreAcOpenedMonth = ?, 
                  TaxRate = ?, 
                  InterestMethod = ?, 
                  GLID = ?  -- Update the GLID with the new value
              WHERE GLID = ? AND EffectiveDate = ?`
        ;

      // Step 4: Execute the query
      sql.query(conn, updateQuery, [EditAccTypeIntSetremarks, taxableValue, ignoreacmon,
        TAXRATE, EditISMethod, newGLID, GLID, formattedDate], (err, result) => {
          if (err) {
            console.error("Error executing the update query:", err);
            return res.status(500).send("Error executing the query.");
          }

          // Simply respond with a success message after the query is executed
          return res.json({ success: true, message: "Interest Type updated successfully!" });
        });
    } else {
      console.log("No matching newGLID found for the given EditAccTypeIntsetName.");
      return res.json({ success: false, message: "No matching GLID found for the given EditAccTypeIntsetName." });
    }
  });
});
