app.post("/updateAccTypePenaltyMas", (req, res) => {
  const { selectedpenaltytoEdit, EditPeanltyRemarks, username, formattedDate, EditPeanltyAcc } = req.body; // Retrieve the selected penalty, remarks, formatted date, and new GLID
  console.log("Selected Penalty to Edit:", selectedpenaltytoEdit);
  console.log("Updated Remarks:", EditPeanltyRemarks);
  console.log("Formatted Date:", formattedDate);
  console.log("New GLID from Frontend:", EditPeanltyAcc);

  // Step 1: Check if the necessary data is provided
  if (!selectedpenaltytoEdit || !EditPeanltyRemarks || !EditPeanltyAcc) {
    return res.status(400).send("Selected penalty, remarks, and GLID are required.");
  }

  const conn = req.session.conn; // Get the database connection from the session

  // Step 2: Retrieve the GLID for the selectedpenaltytoEdit (this step is similar to the previous step)
  const queryGLIDSelected = `
    SELECT GLID
    FROM dbo.tbLedgerMaster
    WHERE GLName = ?
  `;

  sql.query(conn, queryGLIDSelected, [selectedpenaltytoEdit], (err, result) => {
    if (err) {
      console.error("Error retrieving GLID for selected penalty:", err);
      return res.status(500).send("Error retrieving GLID for selected penalty.");
    }

    if (result.length === 0) {
      console.log(`No GLID found for Selected Penalty: ${selectedpenaltytoEdit}`);
      return res.status(404).send("No GLID found for the selected penalty.");
    }

    const glIDSelected = result[0].GLID;
    console.log(`Retrieved GLID for selected penalty: ${glIDSelected}`);

    // Step 3: Retrieve the GLID for EditPeanltyAcc from the frontend
    const queryGLIDAcc = `
      SELECT GLID
      FROM dbo.tbLedgerMaster
      WHERE GLName = ?
    `;

    sql.query(conn, queryGLIDAcc, [EditPeanltyAcc], (err, accResult) => {
      if (err) {
        console.error("Error retrieving GLID for EditPeanltyAcc:", err);
        return res.status(500).send("Error retrieving GLID for EditPeanltyAcc.");
      }

      if (accResult.length === 0) {
        console.log(`No GLID found for Account: ${EditPeanltyAcc}`);
        return res.status(404).send("No GLID found for the given account.");
      }

      const glIDNew = accResult[0].GLID;
      console.log(`Retrieved GLID for EditPeanltyAcc: ${glIDNew}`);

      // Step 4: Retrieve the MethodID using the GLID for the selected penalty and formattedDate
      const queryMethodID = `
        SELECT MethodID
        FROM dbo.tbPenaltyCalculationMethods
        WHERE GLID = ? AND EffectiveDate = ?
      `;

      sql.query(conn, queryMethodID, [glIDSelected, formattedDate], (err, methodResult) => {
        if (err) {
          console.error("Error retrieving MethodID:", err);
          return res.status(500).send("Error retrieving MethodID.");
        }

        if (methodResult.length === 0) {
          console.log(`No MethodID found for GLID: ${glIDSelected} and EffectiveDate: ${formattedDate}`);
          return res.status(404).send("No MethodID found for the given GLID and EffectiveDate.");
        }

        const methodID = methodResult[0].MethodID;
        console.log(`Retrieved MethodID: ${methodID}`);
        // Step 4: Retrieve the UserID for the provided username from SAJILODB using the second connection
        const queryGetUserID = `SELECT UserID
      FROM dbo.tbUserMaster
      WHERE UserName = ?`;

        // Execute the query to get the UserID
        sql.query(connectionString, queryGetUserID, [username], (err, userResult) => {
          if (err) {
            console.error("Error retrieving UserID:", err);
            return res.status(500).send("Error retrieving UserID.");
          }

          if (userResult.length > 0) {
            const userID = userResult[0].UserID;  // Get the UserID
            console.log(`Retrieved UserID for username: ${username}`, userID);
            // Step 5: Update the GLID, Remark, and LastSaveDateTime in tbPenaltyCalculationMethods
            const queryUpdate = `
          UPDATE dbo.tbPenaltyCalculationMethods
          SET GLID = ?, Remarks = ?,LastSavedBy = ?, LastSavedDateTime = GETDATE()
          WHERE MethodID = ?
        `;

            sql.query(conn, queryUpdate, [glIDNew, EditPeanltyRemarks, userID, methodID], (updateErr, updateResult) => {
              if (updateErr) {
                console.error("Error updating the penalty calculation method:", updateErr);
                return res.status(500).send("Error updating the penalty calculation method.");
              }

              console.log(`Updated GLID, Remark, and LastSaveDateTime for MethodID: ${methodID}`);
              res.json({ success: true, message: "Penalty calculation method updated successfully." });
            });
          }
        });
      });
    });
  });
});
app.post("/updateCheckboxData", async (req, res) => {
  const { updatedData, selectedpenaltytoEdit, formattedDate } = req.body;
  console.log("ka ho muji", updatedData, selectedpenaltytoEdit, formattedDate);

  if (!Array.isArray(updatedData) || updatedData.length === 0) {
    return res.status(400).send("No data provided to update.");
  }

  const conn = req.session.conn;

  try {
    for (const data of updatedData) {
      const { index, serialNo, perDayChecked } = data;

      // Step 1: Retrieve the GLID for the given selectedpenaltytoEdit
      const queryGLID = `
        SELECT GLID
        FROM dbo.tbLedgerMaster
        WHERE GLName = ?
      `;

      // Await the result of the GLID query
      const glIDResult = await new Promise((resolve, reject) => {
        sql.query(conn, queryGLID, [selectedpenaltytoEdit], (err, result) => {
          if (err) {
            reject("Error retrieving GLID: " + err);
          }
          resolve(result);
        });
      });

      // Log the raw result to debug the issue
      console.log('GLID query raw result:', glIDResult);

      // Check if the result is an array and has at least one element
      if (!Array.isArray(glIDResult) || glIDResult.length === 0) {
        console.log(`No GLID found for Selected Row item: ${selectedpenaltytoEdit}`);
        continue; // Skip to the next iteration if no GLID is found
      }

      const glID = glIDResult[0].GLID;
      console.log(`Retrieved GLID: ${glID}`);

      // Step 2: Retrieve the MethodID using the GLID
      const queryMethodID = `
        SELECT MethodID
        FROM dbo.tbPenaltyCalculationMethods
        WHERE GLID=? AND EffectiveDate=?
      `;

      // Await the result of the MethodID query
      const methodResult = await new Promise((resolve, reject) => {
        sql.query(conn, queryMethodID, [glID, formattedDate], (err, result) => {
          if (err) {
            reject("Error retrieving MethodID: " + err);
          }
          resolve(result);
        });
      });

      // Log the method result for debugging
      console.log('MethodID query raw result:', methodResult);

      // Check if the result is an array and has at least one element
      if (!Array.isArray(methodResult) || methodResult.length === 0) {
        console.log(`No MethodID found for Selected Row item: ${selectedpenaltytoEdit}`);
        continue; // Skip to the next iteration if no MethodID is found
      }

      const methodID = methodResult[0].MethodID;
      console.log(`Retrieved MethodID: ${methodID}`);

      // Step 3: Update the PerDay value for the given MethodID
      const queryUpdate = `
        UPDATE dbo.tbPenaltyCalculationMethodsDetails
        SET PerDay = ?
        WHERE MethodID = ? AND Sno = ?
      `;

      // Await the result of the update query
      await new Promise((resolve, reject) => {
        sql.query(conn, queryUpdate, [perDayChecked, methodID, serialNo], (err, result) => {
          if (err) {
            reject("Error updating PerDay value: " + err);
          }
          resolve(result);
        });
      });
      console.log(`Updated PerDay value for MethodID: ${methodID}for sno:${serialNo} to: ${perDayChecked}`);
    }

    // After all updates are processed, respond with a success message
    res.json({ success: true, message: 'Checkbox data updated successfully' });

  } catch (err) {
    console.error("Error processing the update:", err);
    res.status(500).send("Error processing the update.");
  }
});
app.get("/fetchListsForPenaltyCopy", (req, res) => {
  // Define query to fetch both GLName and GLAlias
  const query = `SELECT GLName, GLAlias FROM dbo.tbLedgerMaster WHERE Schedule = 'Monthly' AND Duration IS NOT NULL`;

  // Get the database connection from the session
  const conn = req.session.conn;

  // Validate the database connection
  if (!conn) {
    console.error("Database connection is not available in the session.");
    return res.status(500).json({ error: "Database connection not found" });
  }

  // Execute the SQL query
  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.error("SQL error:", err);
      return res.status(500).json({
        error: "Error fetching GLNames and GLAlias",
        details: err.message,
      });
    }

    // Check if any rows are returned
    if (rows && rows.length > 0) {
      // Respond with the data under the key 'PenaltyList'
      return res.json({ PenaltyList: rows });
    }

    // If no rows are found, return a 404 response
    return res.status(404).json({ message: "No PenaltyNames found" });
  });
});
