app.post("/updateAccTypeRebateMas", (req, res) => {
  const { selectedrebatetoEdit, EditRebateRemarks, username, formattedDate, EditRebateAcc } = req.body; // Retrieve the selected penalty, remarks, formatted date, and new GLID
  console.log("Selected Penalty to Edit:", selectedrebatetoEdit);
  console.log("Updated Remarks:", EditRebateRemarks);
  console.log("Formatted Date:", formattedDate);
  console.log("New GLID from Frontend:", EditRebateAcc);

  // Step 1: Check if the necessary data is provided
  if (!selectedrebatetoEdit || !EditRebateRemarks || !EditRebateAcc) {
    return res.status(400).send("Selected penalty, remarks, and GLID are required.");
  }

  const conn = req.session.conn; // Get the database connection from the session

  // Step 2: Retrieve the GLID for the selectedrebatetoEdit (this step is similar to the previous step)
  const queryGLIDSelected = `
    SELECT GLID
    FROM dbo.tbLedgerMaster
    WHERE GLName = ?
  `;

  sql.query(conn, queryGLIDSelected, [selectedrebatetoEdit], (err, result) => {
    if (err) {
      console.error("Error retrieving GLID for selected Rebate:", err);
      return res.status(500).send("Error retrieving GLID for selected Rebate.");
    }

    if (result.length === 0) {
      console.log(`No GLID found for Selected Rebate: ${selectedrebatetoEdit}`);
      return res.status(404).send("No GLID found for the selected rebate.");
    }

    const glIDSelected = result[0].GLID;
    console.log(`Retrieved GLID for selected rebate: ${glIDSelected}`);

    // Step 3: Retrieve the GLID for EditRebateAcc from the frontend
    const queryGLIDAcc = `
      SELECT GLID
      FROM dbo.tbLedgerMaster
      WHERE GLName = ?
    `;

    sql.query(conn, queryGLIDAcc, [EditRebateAcc], (err, accResult) => {
      if (err) {
        console.error("Error retrieving GLID for EditRebateAcc:", err);
        return res.status(500).send("Error retrieving GLID for EditRebateAcc.");
      }

      if (accResult.length === 0) {
        console.log(`No GLID found for Account: ${EditRebateAcc}`);
        return res.status(404).send("No GLID found for the given account.");
      }

      const glIDNew = accResult[0].GLID;
      console.log(`Retrieved GLID for EditRebateAcc: ${glIDNew}`);

      // Step 4: Retrieve the MethodID using the GLID for the selected reabate and formattedDate
      const queryMethodID = `
        SELECT MethodID
        FROM dbo.tbRebateCalculationMethods
        WHERE GLID = ? AND EffectiveDate = ?
      `;

      sql.query(conn, queryMethodID, [glIDSelected, formattedDate], (err, methodResult) => {
        if (err) {
          console.error("Error retrieving MethodID:", err);
          return res.status(500).send("Error retrieving MethodID.");
        }

        if (methodResult.length === 0) {
          console.log(`No MethodID found for GLID: ${glIDSelected} and EffectiveDate: ${formattedDate}`);
          return res.status(404).send("No MethodID found for the given GLID and EffectiveDate.");
        }

        const methodID = methodResult[0].MethodID;
        console.log(`Retrieved MethodID: ${methodID}`);
        // Step 4: Retrieve the UserID for the provided username from SAJILODB using the second connection
        const queryGetUserID = `SELECT UserID
      FROM dbo.tbUserMaster
      WHERE UserName = ?`;

        // Execute the query to get the UserID
        sql.query(connectionString, queryGetUserID, [username], (err, userResult) => {
          if (err) {
            console.error("Error retrieving UserID:", err);
            return res.status(500).send("Error retrieving UserID.");
          }

          if (userResult.length > 0) {
            const userID = userResult[0].UserID;  // Get the UserID
            console.log(`Retrieved UserID for username: ${username}`, userID);
            // Step 5: Update the GLID, Remark, and LastSaveDateTime in tbPenaltyCalculationMethods
            const queryUpdate = `
          UPDATE dbo.tbRebateCalculationMethods
          SET GLID = ?, Remarks = ?,LastSavedBy = ?, LastSavedDateTime = GETDATE()
          WHERE MethodID = ?
        `;

            sql.query(conn, queryUpdate, [glIDNew, EditRebateRemarks, userID, methodID], (updateErr, updateResult) => {
              if (updateErr) {
                console.error("Error updating the rebate calculation method:", updateErr);
                return res.status(500).send("Error updating the rebate calculation method.");
              }

              console.log(`Updated GLID, Remark, and LastSaveDateTime for MethodID: ${methodID}`);
              res.json({ success: true, message: "Rebate calculation method updated successfully." });
            });
          }
        });
      });
    });
  });
});
