app.post("/delete-Chequeiss-mas-class", (req, res) => {
  const { From, To, effectiveDate } = req.body;  // Get From ,To and effectiveDate from the frontend
  const conn = req.session.conn;  // Get the database connection from the session
  console.log('Received from frontend:', From, To, effectiveDate);  // Debug log to check received data

  // Step 1: Find the ChequeIssueID corresponding to the From and To value send from frotnend
  const queryCIID = `
 SELECT ChequeIssueID
 FROM dbo.tbChequeIssueMaster
 WHERE ChequeNoFrom = ? AND ChequeNoTo = ?
`;

  sql.query(conn, queryCIID, [From, To], (err, result) => {
    if (err) {
      console.error("Error retrieving chequeissueID:", err);
      return res.status(500).send("Error retrieving chequeissueID.");
    }

    if (result.length === 0) {
      return res.status(404).send("Account Name not found.");
    }

    const ciID = result[0].ChequeIssueID;  // Get the chequeissueID from the result
    console.log(`Retrieved ChequeIssueID: ${ciID}`);


    // Step 2: Check if ChequeIssueID exists in dbo.tbChequeIssueDetails
    const queryCheckCIID = `
         SELECT 1
         FROM dbo.tbChequeIssueDetails
         WHERE ChequeIssueID = ?
       `;

    sql.query(conn, queryCheckCIID, [ciID], (err, checkMethodResult) => {
      if (err) {
        console.error("Error checking ChequeIssueID in tbChequeIssueDetails:", err);
        return res.status(500).send("Error checking ChequeIssueID.");
      }

      if (checkMethodResult.length > 0) {
        // ChequeIssueID found, proceed to delete from dbo.tbChequeIssueDetails
        const queryDeleteDetails = `
                 DELETE FROM dbo.tbChequeIssueDetails
                 WHERE ChequeIssueID = ?
               `;

        sql.query(conn, queryDeleteDetails, [ciID], (err, deleteDetailsResult) => {
          if (err) {
            console.error("SQL error deleting from tbChequeIssueDetails:", err);
            return res.status(500).send("Error deleting from tbChequeIssueDetails.");
          }

          console.log("Deleted from dbo.tbChequeIssueDetails");

          // Step 4: Now delete from dbo.tbChequeIssueMaster using ChequeIssueID 
          const queryDeleteMethod = `
                     DELETE FROM dbo.tbChequeIssueMaster
                     WHERE ChequeIssueID = ? 
                   `;

          sql.query(conn, queryDeleteMethod, [ciID], (err, deleteMethodResult) => {
            if (err) {
              console.error("SQL error deleting from tbChequeIssueMaster:", err);
              return res.status(500).send("Error deleting from tbChequeIssueMaster.");
            }

            res.send("Cheque Issue  group deleted successfully!");
          });
        });
      } else {
        // If ChequeIssueID not found in tbChequeIssueDetails, skip deletion step 3 and proceed to Step 4
        console.log(`ChequeIssueID ${ciID} not found in tbChequeIssueDetails, skipping deletion.`);

        // Step 4: Delete from dbo.tbChequeIssueMaster using ChequeIssueID 
        const queryDeleteMethod = `
                 DELETE FROM dbo.tbChequeIssueMaster
                 WHERE ChequeIssueID = ? 
               `;

        sql.query(conn, queryDeleteMethod, [ciID], (err, deleteMethodResult) => {
          if (err) {
            console.error("SQL error deleting from tbChequeIssueMaster:", err);
            return res.status(500).send("Error deleting from tbChequeIssueMaster.");
          }

          res.send("Cheque Issue  group deleted successfully!");
        });
      }
    });
  });
});
