// Route to check if the Account Number exists in the Cheque Issue Master table
app.post("/checkChequeIssueDuplicate", (req, res) => {
  const { CopyChequeIssuemasAccountNumber } = req.body; // Retrieve Account Number from the request
  const conn = req.session.conn;  // Get the database connection from the session
  console.log("Received no to check:", CopyChequeIssuemasAccountNumber)

  // Step 1: Fetch the SLID based on the Account Number (from tbSubLedgerMaster)
  const query = `
      SELECT SLID
      FROM dbo.tbSubLedgerMaster
      WHERE SlAlias = ?
  `;

  sql.query(conn, query, [CopyChequeIssuemasAccountNumber], (err, rows) => {
    if (err) {
      console.error("Error fetching SLID:", err);
      return res.status(500).send("Error fetching SLID");
    }

    // If no matching row is found for the given Account Number
    if (!rows || rows.length === 0) {
      return res.status(400).send("No matching SLID found for this Account Number.");
    }

    const SLID = rows[0].SLID;

    // Step 2: Check if the SLID exists in the tbChequeIssueMaster table
    const checkQuery = `
          SELECT COUNT(*) AS count
          FROM dbo.tbChequeIssueMaster
          WHERE SLID = ?
      `;

    sql.query(conn, checkQuery, [SLID], (err, result) => {
      if (err) {
        console.error("Error checking SLID in tbChequeIssueMaster:", err);
        return res.status(500).send("Error checking SLID");
      }

      // If SLID is found in the tbChequeIssueMaster table, it's a duplicate
      if (result[0].count > 0) {
        return res.json({ error: "Cannot insert duplicate data. Please Check the Account No" });
      }

      // If no duplicate found, send success response
      res.json({ success: true });
    });
  });
});
