app.post("/copyChequeIssueMas", (req, res) => {
  const { CopyChequeIssuemasTotal, selectedShareIssuetoCopy, CopyChequeIssueRemarks, username, formattedDate } = req.body;
  const conn = req.session.conn;  // Get the database connection from the session

  // Validate the incoming request data
  if (!CopyChequeIssuemasTotal || !selectedShareIssuetoCopy || !CopyChequeIssueRemarks || !username || !formattedDate) {
    return res.status(400).send("Missing required fields in the request.");
  }

  // Execute the query to get the UserID
  const queryGetUserID = `SELECT UserID FROM dbo.Users WHERE UserName = ?`;
  sql.query(conn, queryGetUserID, [username], (err, userResult) => {
    if (err) {
      console.error("Error retrieving UserID:", err);
      return res.status(500).send("Error retrieving UserID.");
    }

    if (userResult.length > 0) {
      const userID = userResult[0].UserID;  // Get the UserID
      console.log(`Retrieved UserID for username: ${username}`, userID);

      // Step 3: Proceed with the form submission (e.g., insert data into dbo.tbChequeIssueMaster)
      const insertQuery = `
        INSERT INTO dbo.tbChequeIssueMaster (TotalCheques, SelectedShareName, Remarks, UserName, IssueDate)
        VALUES (?, ?, ?, ?, ?)
      `;

      // Execute the query to insert data into the database
      sql.query(conn, insertQuery, [CopyChequeIssuemasTotal, selectedShareIssuetoCopy, CopyChequeIssueRemarks, username, formattedDate], (err, result) => {
        if (err) {
          console.error("Error inserting data:", err);
          return res.status(500).send("Error inserting data");
        }

        // Respond with success message
        res.json({ message: "Cheque issue inserted successfully!" });
      });
    } else {
      // If no user found, send an error response
      console.error("User not found for username:", username);
      return res.status(404).send("User not found.");
    }
  });
});

app.post("/delete-Mobilealert-mas-class", (req, res) => {
  const { accountNumber, name, effectiveDate } = req.body;  // Get name and effectiveDate from the frontend
  const conn = req.session.conn;  // Get the database connection from the session

  // Log to check received data
  console.log('Received from frontend:', accountNumber, name, effectiveDate);

  if (!name || !effectiveDate) {
    return res.status(400).send("Name and effectiveDate are required.");
  }

  // Step 1: Find the SLID corresponding to the name sent from the frontend
  const querySLID = `
    SELECT SLID
    FROM dbo.tbSubLedgerMaster
    WHERE SlAlias = ?
  `;

  sql.query(conn, querySLID, [accountNumber], (err, result) => {
    if (err) {
      console.error("Error retrieving SLID:", err);
      return res.status(500).send("Error retrieving SLID.");
    }

    if (result.length === 0) {
      return res.status(404).send("SLID not found.");
    }

    const slID = result[0].SLID;  // Get the SLID from the result
    console.log(`Retrieved SLID: ${slID}`);

    // Step 2: Delete from dbo.tbMobileAlertSetting using SLID and effectiveDate
    const queryDeleteMethod = `
      DELETE FROM dbo.tbMobileAlertSetting
      WHERE SLID = ? AND EffectiveDate = ?
    `;

    sql.query(conn, queryDeleteMethod, [slID, effectiveDate], (err, deleteMethodResult) => {
      if (err) {
        console.error("SQL error deleting from tbMobileAlertSetting:", err);
        return res.status(500).send("Error deleting from tbMobileAlertSetting.");
      }

      if (deleteMethodResult.affectedRows === 0) {
        return res.status(404).send("No matching records found to delete.");
      }

      res.send("Mobile Alert group deleted successfully!");
    });
  });
});
