app.post("/copyMobileAlertMas", (req, res) => {
  const {
    CopyMobileAlertAccountNumber,
    CopyMobileAlertSSDate,
    CopyMobileAlertRenewDate,
    CopyMobileAlertExpiryDate,
    CopyMobileAlertCBonWD,
    CopyMobileAlertAmtonWD,
    CopyMobileAlertCBonD,
    CopyMobileAlertAmtonD,
    CopyMobileAlertRemarks,
    username
  } = req.body;

  const conn = req.session.conn;  // Get the database connection from the session

  // Step 1: Validate the incoming request data
  if (!CopyMobileAlertAccountNumber) {
    return res.status(400).send("Missing required fields in the request.");
  }

  // Step 2: Retrieve SLID for the CopyMobileAlertAccountNumber
  const queryGetSLID = `
    SELECT SLID
    FROM dbo.tbSubLedgerMaster
    WHERE SlAlias = ?
  `;

  sql.query(conn, queryGetSLID, [CopyMobileAlertAccountNumber], (err, result) => {
    if (err) {
      console.error("Error retrieving SLID for selected ACC.NO:", err);
      return res.status(500).send({ error: "Error retrieving SLID for selected ACC.NO." });
    }

    if (result.length === 0) {
      console.log(`No SLID found for Selected ACC.NO: ${CopyMobileAlertAccountNumber}`);
      return res.status(404).send({ error: "No SLID found for the selected ACC.NO." });
    }

    const retSLID = result[0].SLID;
    console.log(`Retrieved SLID for selected ACC.NO: ${retSLID}`);

    // Step 3: Execute the query to get the UserID
    const queryGetUserID = `SELECT UserID FROM dbo.tbUserMaster WHERE UserName = ?`;
    sql.query(connectionString, queryGetUserID, [username], (err, userResult) => {
      if (err) {
        console.error("Error retrieving UserID:", err);
        return res.status(500).send("Error retrieving UserID.");
      }

      if (userResult.length > 0) {
        const userID = userResult[0].UserID;  // Get the UserID
        console.log(`Retrieved UserID for username: ${username}`, userID);

        // Step 4: Process form submission (insert data into dbo.tbMobileAlertSetting)
        const CopyMobileAlertCBonWdBit = CopyMobileAlertCBonWD ? 1 : 0;
        const CopyMobileAlertCBonDBit = CopyMobileAlertCBonD ? 1 : 0;

        const insertQuery = `
          INSERT INTO dbo.tbMobileAlertSetting 
          (SLID, EffectiveDate, AlertonWithdraw, AlertonWithdrawAmount, 
          AlertonDeposit, AlertonDepositAmount, CreatedBy, CreatedDateTime, Remarks, RenewDate, ExpiryDate)
          VALUES (?, ?, ?, ?, ?, ?, ?, GetDate(), ?, ?, ?)
        `;

        // Execute the query to insert data into the database
        sql.query(conn, insertQuery, [
          retSLID,
          CopyMobileAlertSSDate,
          CopyMobileAlertCBonWdBit,
          CopyMobileAlertAmtonWD,
          CopyMobileAlertCBonDBit,
          CopyMobileAlertAmtonD,
          userID,
          CopyMobileAlertRemarks,
          CopyMobileAlertRenewDate,
          CopyMobileAlertExpiryDate
        ], (err, result) => {
          if (err) {
            console.error("Error inserting data:", err);
            return res.status(500).send("Error inserting data");
          }

          // Respond with success message
          res.json({ message: "Mobile Alert inserted successfully!" });
        });
      } else {
        // If no user found, send an error response
        console.error("User not found for username:", username);
        return res.status(404).send("User not found.");
      }
    });
  });
});
app.post("/delete-ShareTransaction-mas-class", (req, res) => {
  const { ShareTransno, effectiveDate } = req.body;  // Get From ,To and effectiveDate from the frontend
  const conn = req.session.conn;  // Get the database connection from the session
  console.log('Received from frontend:', ShareTransno, effectiveDate);  // Debug log to check received data

  // Step 1: Find the ShareTransactionID corresponding to the ShareTransno value send from frotnend
  const querySTID = `
 SELECT ShareTransactionID
 FROM dbo.tbShareTransactionMaster
 WHERE TransactionNo = ? AND TransactionDate = ?
`;

  sql.query(conn, querySTID, [ShareTransno, effectiveDate], (err, result) => {
    if (err) {
      console.error("Error retrieving ShareTransactionID:", err);
      return res.status(500).send("Error retrieving ShareTransactionID.");
    }

    if (result.length === 0) {
      return res.status(404).send("Account Name not found.");
    }

    const stID = result[0].ShareTransactionID;  // Get the ShareTransactionID from the result
    console.log(`Retrieved ShareTransactionID: ${stID}`);


    // Step 2: Check if ShareTransactionID exists in dbo.tbShareTransactionDetails
    const queryCheckSTID = `
         SELECT 1
         FROM dbo.tbShareTransactionDetails
         WHERE ShareTransactionID = ?
       `;

    sql.query(conn, queryCheckSTID, [stID], (err, checkMethodResult) => {
      if (err) {
        console.error("Error checking ShareTransactionID in tbShareTransactionDetails:", err);
        return res.status(500).send("Error checking ShareTransactionID.");
      }

      if (checkMethodResult.length > 0) {
        // ShareTransactionID found, proceed to delete from dbo.tbShareTransactionDetails
        const queryDeleteDetails = `
                 DELETE FROM dbo.tbShareTransactionDetails
                 WHERE ShareTransactionID = ?
               `;

        sql.query(conn, queryDeleteDetails, [stID], (err, deleteDetailsResult) => {
          if (err) {
            console.error("SQL error deleting from tbShareTransactionDetails:", err);
            return res.status(500).send("Error deleting from tbShareTransactionDetails.");
          }

          console.log("Deleted from dbo.tbShareTransactionDetails");

          // Step 4: Now delete from dbo.tbShareTransactionMaster using ShareTransactionID 
          const queryDeleteMethod = `
                     DELETE FROM dbo.tbShareTransactionMaster
                     WHERE ShareTransactionID = ? 
                   `;

          sql.query(conn, queryDeleteMethod, [stID], (err, deleteMethodResult) => {
            if (err) {
              console.error("SQL error deleting from tbShareTransactionMaster:", err);
              return res.status(500).send("Error deleting from tbShareTransactionMaster.");
            }

            res.send("Share Issue  group deleted successfully!");
          });
        });
      } else {
        // If ShareTransactionID not found in tbShareTransactionDetails, skip deletion step 3 and proceed to Step 4
        console.log(`ShareTransactionID ${stID} not found in tbShareTransactionDetails, skipping deletion.`);

        // Step 4: Delete from dbo.tbShareTransactionMaster using ShareTransactionID 
        const queryDeleteMethod = `
                 DELETE FROM dbo.tbShareTransactionMaster
                 WHERE ShareTransactionID = ? 
               `;

        sql.query(conn, queryDeleteMethod, [stID], (err, deleteMethodResult) => {
          if (err) {
            console.error("SQL error deleting from tbShareTransactionMaster:", err);
            return res.status(500).send("Error deleting from tbShareTransactionMaster.");
          }

          res.send("Share Issue  group deleted successfully!");
        });
      }
    });
  });
});
