app.post("/updateShareTransMas", (req, res) => {
  const {
    EditShareTransMasSelectedNumber,
    EditShareTransMasAccNumber,
    EditShareTransMasTransftoAccnumber,
    EditShareTransMasTransType,
    EditShareTransMasRemarks,
    stformattedDate,
    EditShareTransMasTotalShare,
    EditShareTransMasSharestartFrom,
    EditShareTransMasShareEndTo,
    username
  } = req.body;

  const conn = req.session.conn; // Get the database connection from the session

  // Step 1: Check if the necessary data is provided
  if (!EditShareTransMasSelectedNumber || !stformattedDate) {
    return res.status(400).send("Selected share issue and date are required.");
  }

  // Step 2: Retrieve ShareTransaction ID for using the EditShareTransMasSelectedNumber
  const queryGetSTID = `
    SELECT ShareTransactionID
    FROM dbo.tbShareTransactionMaster
    WHERE TransactionNo = ?
  `;

  sql.query(conn, queryGetSTID, [EditShareTransMasSelectedNumber], (err, result) => {
    if (err) {
      console.error("Error retrieving ShareTransaction ID for selected ACC.NO:", err);
      return res.status(500).send({ error: "Error retrieving ShareTransaction ID for selected ACC.NO." });
    }

    if (result.length === 0) {
      console.log(`No ShareTransaction ID found for Selected ACC.NO: ${EditShareTransMasSelectedNumber}`);
      return res.status(404).send({ error: "No ShareTransaction ID found for the selected ACC.NO." });
    }

    const retSTID = result[0].ShareTransactionID;
    console.log(`Retrieved ShareTransactionID for selected ACC.NO: ${retSTID}`);

    // Step 3: Retrieve the UserID for the provided username
    const queryGetUserID = `
      SELECT UserID
      FROM dbo.tbUserMaster
      WHERE UserName = ?
    `;

    sql.query(connectionString, queryGetUserID, [username], (err, userResult) => {
      if (err) {
        console.error("Error retrieving UserID:", err);
        return res.status(500).send({ error: "Error retrieving UserID." });
      }

      if (userResult.length > 0) {
        const userID = userResult[0].UserID; // Get the UserID
        console.log(`Retrieved UserID for username: ${username}`, userID);

        // Step 4: Retrieve the another SLID for the provided EditShareTransMasAccNumber
        const queryGetSLID = `
          SELECT SLID
          FROM dbo.tbSubLedgerMaster
          WHERE SlAlias = ?
        `;

        sql.query(conn, queryGetSLID, [EditShareTransMasAccNumber], (err, result) => {
          if (err) {
            console.error("Error retrieving SLID for selected ACC.NO:", err);
            return res.status(500).send({ error: "Error retrieving SLID for selected ACC.NO." });
          }

          if (result.length === 0) {
            console.log(`No SLID found for Selected ACC.NO: ${EditShareTransMasAccNumber}`);
            return res.status(404).send({ error: "No SLID found for the selected ACC.NO." });
          }

          const oneSLID = result[0].SLID;
          console.log(`Retrieved SLID for selected ACC.NO: ${oneSLID}`);

          // Step 5: Retrieve the SLID for the provided EditShareTransMasTransftoAccnumber
          const queryGetSLIDtt = `
            SELECT SLID
            FROM dbo.tbSubLedgerMaster
            WHERE SlAlias = ?
          `;

          sql.query(conn, queryGetSLIDtt, [EditShareTransMasTransftoAccnumber], (err, result) => {
            if (err) {
              console.error("Error retrieving SLID for selected ACC.NO:", err);
              return res.status(500).send({ error: "Error retrieving SLID for selected ACC.NO." });
            }

            if (result.length === 0) {
              console.log(`No SLID found for Selected ACC.NO: ${EditShareTransMasAccNumber}`);
              return res.status(404).send({ error: "No SLID found for the selected ACC.NO." });
            }

            const twoSLID = result[0].SLID;
            console.log(`Retrieved SLID for selected ACC.NO: ${twoSLID}`);

            // Step 5: Updating the tables with received items
            const queryUpdate = `
              UPDATE dbo.tbShareTransactionMaster
              SET 
                TransactionType = ?, 
                SLID = ?, 
                SLIDTransferTo = ?,
                TransactionDate = ?, 
                TotalShare = ?, 
                ShareIDFrom = ?, 
                ShareIDTo = ?,
                LastSavedBy = ?,
                LastSavedDateTime = GETDATE(), 
                Remarks = ?
              WHERE 
                ShareTransactionID = ?
            `;

            sql.query(conn, queryUpdate, [
              EditShareTransMasTransType,
              oneSLID,
              twoSLID,
              stformattedDate,
              EditShareTransMasTotalShare,
              EditShareTransMasSharestartFrom,
              EditShareTransMasShareEndTo,
              userID,
              EditShareTransMasRemarks,
              retSTID
            ], (updateErr, updateResult) => {
              if (updateErr) {
                console.error("Error updating the Share TrasMas Alert:", updateErr);
                return res.status(500).send({ error: "Error updating the Share TrasMas." });
              }

              console.log(`Updated items for Share TrasMas: ${EditShareTransMasSelectedNumber}`);
              res.json({ success: true, message: "Share TrasMas updated successfully." });
            });
          });
        });
      } else {
        return res.status(404).send({ error: "User not found." });
      }
    });
  });
});

