app.post("/updateCollectionChequeMas", (req, res) => {
  const {
    EditCollectionChequeMasSelectedTransNumber,
    EditCollectionChequeMasTransNumber,
    tdformattedDate,
    EditCollectionChequeMasDraweeBank,
    EditCollectionChequeMasBankBranch,
    EditCollectionChequeMasChequeno,
    cdformattedDate,
    EditCollectionChequeMasAmount,
    EditCollectionChequeMasDocClass,
    EditCollectionChequeMasAccountId,
    EditCollectionChequeMasAccountName,
    EditCollectionChequeMasSrcofFund,
    EditCollectionChequeMasCollectedCB,
    EditCollectionChequeMasAccPostedCB,
    colldformattedDate,
    EditCollectionChequeMasRemarks,
    EditCollectionChequeMasUsername,
    EditCollectionChequeMasAccType
  } = req.body;

  const conn = req.session.conn; // Get the database connection from the session

  // Step 1: Check if the necessary data is provided
  if (!EditCollectionChequeMasSelectedTransNumber || !EditCollectionChequeMasTransNumber) {
    return res.status(400).send("Selected share issue and date are required.");
  }

  // Step 2: Retrieve CollectionChequeID for using the EditCollectionChequeMasSelectedTransNumber
  const queryGetCCID = `
    SELECT CollectionChequeID
    FROM dbo.tbCollectionChequeMaster
    WHERE TransactionNo = ?
  `;

  sql.query(conn, queryGetCCID, [EditCollectionChequeMasSelectedTransNumber], (err, result) => {
    if (err) {
      console.error("Error retrieving CollectionChequeID  for selected Trans.NO:", err);
      return res.status(500).send({ error: "Error retrieving CollectionChequeID for selected Trans.NO" });
    }

    if (result.length === 0) {
      console.log(`No CollectionChequeID  found for Selected Trans.NO: ${EditCollectionChequeMasSelectedTransNumber}`);
      return res.status(404).send({ error: "No CollectionChequeID  found for the selected Trans.NO." });
    }

    const retCCID = result[0].CollectionChequeID;
    console.log(`Retrieved CollectionChequeID for selected Trans.NO: ${retCCID}`);

    // Step 3: Retrieve the UserID for the provided username
    const queryGetUserID = `
      SELECT UserID
      FROM dbo.tbUserMaster
      WHERE UserName = ?
    `;

    sql.query(connectionString, queryGetUserID, [EditCollectionChequeMasUsername], (err, userResult) => {
      if (err) {
        console.error("Error retrieving UserID:", err);
        return res.status(500).send({ error: "Error retrieving UserID." });
      }

      if (userResult.length > 0) {
        const userID = userResult[0].UserID; // Get the UserID
        console.log(`Retrieved UserID for username: ${EditCollectionChequeMasUsername}`, userID);

        // Step 4: Retrieve the  GLID for the provided EditCollectionChequeMasDraweeBank
        const queryGetDBGLID = `
          SELECT GLID
          FROM dbo.tbLedgerMaster
          WHERE GLName = ?
        `;

        sql.query(conn, queryGetDBGLID, [EditCollectionChequeMasDraweeBank], (err, result) => {
          if (err) {
            console.error("Error retrieving GLID for selected DraweeBank:", err);
            return res.status(500).send({ error: "Error retrieving GLID for selected DraweeBank." });
          }

          if (result.length === 0) {
            console.log(`No GLID found for Selected DraweeBank: ${EditCollectionChequeMasDraweeBank}`);
            return res.status(404).send({ error: "No GLID found for the selected DraweeBank." });
          }

          const DBGLID = result[0].GLID;
          console.log(`Retrieved GLID for selected DraweeBank: ${DBGLID}`);


          //Step 5 : Retrive the DocClassID for the provided EditCollectionChequeMasDocClass
          const queryGetDocClassID = `
          SELECT DocClassID 
          FROM tbDocClassMaster
          WHERE DocClassName = ?
          `;
          sql.query(conn, queryGetDocClassID, [EditCollectionChequeMasDocClass], (err, result) => {
            if (err) {
              console.error("Error retrieving DocClassID for selected DraweeBank:", err);
              return res.status(500).send({ error: "Error retrieving DocClassID for selected ACC.NO." });
            }

            if (result.length === 0) {
              console.log(`No DocClassID found for Selected DraweeBank: ${EditCollectionChequeMasDocClass}`);
              return res.status(404).send({ error: "No DocClassID found for the selected DraweeBank." });
            }

            const docClassID = result[0].DocClassID;
            console.log(`Retrieved DocClassID for selected DraweeBank: ${docClassID}`);

            // Step 6: Retrieve the SLID for the provided EditCollectionChequeMasAccountId
            const queryGetSLID = `
            SELECT SLID
            FROM dbo.tbSubLedgerMaster
            WHERE SlAlias = ?
          `;

            sql.query(conn, queryGetSLID, [EditCollectionChequeMasAccountId], (err, result) => {
              if (err) {
                console.error("Error retrieving SLID for selected DraweeBank:", err);
                return res.status(500).send({ error: "Error retrieving SLID for selected DraweeBank" });
              }

              if (result.length === 0) {
                console.log(`No SLID found for Selected ACC.NO: ${EditCollectionChequeMasAccountId}`);
                return res.status(404).send({ error: "No SLID found for the selected DraweeBank" });
              }

              const ccSLID = result[0].SLID;
              console.log(`Retrieved SLID for selected DraweeBank: ${ccSLID}`);

              // Step 7: Retrive  the GLID for the provided EditCollectionChequeMasAccType
              const queryGetATGLID = `
            SELECT GLID
            FROM dbo.tbLedgerMaster
            WHERE GLName = ?
          `;
              sql.query(conn, queryGetATGLID, [EditCollectionChequeMasAccType], (err, result) => {
                if (err) {
                  console.error("Error retrieving GLID for selected AccountType:", err);
                  return res.status(500).send({ error: "Error retrieving GLID for selected AccountType." });
                }

                if (result.length === 0) {
                  console.log(`No GLID found for Selected AccountType: ${EditCollectionChequeMasAccType}`);
                  return res.status(404).send({ error: "No GLID found for the selected AccountType." });
                }

                const ATGLID = result[0].GLID;
                console.log(`Retrieved GLID for selected AccountType: ${ATGLID}`);


                //Step 8: finiding the boolean value 
                const collectedCb = EditCollectionChequeMasCollectedCB ? 1 : 0;
                const accountpostedCb = EditCollectionChequeMasAccPostedCB ? 1 : 0;




                // Step 9: Updating the tables with received items
                const queryUpdate = `
              UPDATE dbo.tbCollectionChequeMaster
              SET 
                TransactionNo = ?, 
                GLID = ?,
                SLID = ?, 
                GLIDDraweeBank = ?,
                ChequeNo = ?,
                ChequeDate = ?, 
                DraweeBankBranch = ?,
                FundSource = ?,
                TransactionDate = ?,
                Collected = ?,
                Posted = ?,
                CollectedDate = ?,
                Amount = ?, 
                LastSavedBy = ?, 
                LastSavedDateTime = GETDATE(),                
                Remarks = ?,
                DocClassID = ?
              WHERE 
                CollectionChequeID = ?
            `;

                sql.query(conn, queryUpdate, [
                  EditCollectionChequeMasTransNumber,
                  ATGLID,
                  ccSLID,
                  DBGLID,
                  EditCollectionChequeMasChequeno,
                  cdformattedDate,
                  EditCollectionChequeMasBankBranch,
                  EditCollectionChequeMasSrcofFund,
                  tdformattedDate,
                  collectedCb,
                  accountpostedCb,
                  colldformattedDate,
                  EditCollectionChequeMasAmount,
                  userID,
                  EditCollectionChequeMasRemarks,
                  docClassID,
                  retCCID
                ], (updateErr, updateResult) => {
                  if (updateErr) {
                    console.error("Error updating the Collection Cheque Alert:", updateErr);
                    return res.status(500).send({ error: "Error updating the Collection Cheque." });
                  }

                  console.log(`Updated items for Collection Cheque : ${EditCollectionChequeMasSelectedTransNumber}`);
                  res.json({ success: true, message: "Collection Cheque updated successfully." });
                });
              });
            });
          });
        });
      } else {
        return res.status(404).send({ error: "User not found." });
      }
    });
  });
});
