app.post("/copyCollectionChequeMasCheckingField", (req, res) => {
  const { transactionNo } = req.body;

  if (!transactionNo) {
    return res.status(400).json({ error: "Transaction number is required." });
  }

  const conn = req.session.conn; // Use the session connection (or replace with your connection string)

  const checkQuery = `
    SELECT TransactionNo
    FROM dbo.tbCollectionChequeMaster
    WHERE TransactionNo = ?
  `;

  sql.query(conn, checkQuery, [transactionNo], (err, result) => {
    if (err) {
      console.error("Database error while checking TransactionNo:", err);
      return res.status(500).json({ error: "Internal server error." });
    }

    if (result.length > 0) {
      // ✅ Duplicate found
      return res.json({ duplicate: true });
    } else {
      // ✅ Not a duplicate
      console.log("TransactionNo is unique. You can proceed further.");
      return res.json({ duplicate: false });
    }
  });
});
