app.post("/delete-acctypemas-class", (req, res) => {
  const { name } = req.body;


  const conn = req.session.conn;
  console.log('Received from frontend:', name);

  // Step 1: Find the GLID corresponding to the AccountName
  const queryGLID = `
    SELECT GLID
    FROM dbo.tbLedgerMaster
    WHERE GLName = ?
  `;

  sql.query(conn, queryGLID, [name], (err, result) => {
    if (err) {
      console.error("Error retrieving GLID:", err);
      return res.status(500).send("Error retrieving GLID.");
    }

    if (result.length === 0) {
      return res.status(404).send("Account Name not found.");
    }

    const glID = result[0].GLID;
    console.log(`Retrieved GLID: ${glID}`);

    // Step 2: Check if the GLID exists in dbo.tbJournalDetails
    const queryCheckJournalDetails = `
        SELECT 1
        FROM dbo.tbJournalDetails
        WHERE GLID = ?
      `;

    sql.query(conn, queryCheckJournalDetails, [glID], (err, journalResult) => {
      if (err) {
        console.error("Error checking tbJournalDetails:", err);
        return res.status(500).send("Error checking tbJournalDetails.");
      }

      if (journalResult.length > 0) {
        // If the GLID is found in tbJournalDetails, cancel deletion
        return res.status(400).send("The selected data may be used in tbJournalDetails, deletion is canceled.");
      }

      // Step 3: Proceed to delete from dbo.tbLedgerMaster
      const queryDeleteLedger = `
            DELETE FROM dbo.tbLedgerMaster
            WHERE GLID = ?
          `;

      sql.query(conn, queryDeleteLedger, [glID], (err, deleteLedgerResult) => {
        if (err) {
          console.error("SQL error deleting from tbLedgerMaster:", err);
          return res.status(500).send("Error deleting from tbLedgerMaster.");
        }

        if (deleteLedgerResult.affectedRows === 0) {
          return res.status(404).send("No record found to delete.");
        }

        res.send("Account Type group deleted successfully!");
      });
    });
  });
});
