app.post("/fetchacctypemasMoreDetailsForCopy", (req, res) => {
  const { CopyAccTypeMasSelectedName } = req.body;
  const conn = req.session.conn;
  console.log('Received from frontend:', CopyAccTypeMasSelectedName);

  // Step 1: Find the GLID corresponding to the AccountName
  const queryGLID = `
    SELECT GLID
    FROM dbo.tbLedgerMaster
    WHERE GLName = ?
  `;

  sql.query(conn, queryGLID, [CopyAccTypeMasSelectedName], (err, result) => {
    if (err) {
      console.error("Error retrieving GLID:", err);
      return res.status(500).send("Error retrieving GLID.");
    }

    if (result.length === 0) {
      return res.status(404).send("Account Name not found.");
    }

    const glID = result[0].GLID;
    console.log(`Retrieved GLID: ${glID}`);

    // Step 2: Get the value of GLIDInterestTransfer using the GLID
    const queryGLIDInterestTransfer = `
        SELECT GLIDInterestTransfer
        FROM dbo.tbLedgerMaster
        WHERE GLID = ?
      `;

    sql.query(conn, queryGLIDInterestTransfer, [glID], (err, interestResult) => {
      if (err) {
        console.error("Error retrieving GLIDInterestTransfer:", err);
        return res.status(500).send("Error retrieving GLIDInterestTransfer.");
      }

      if (interestResult.length === 0) {
        return res.status(404).send("GLIDInterestTransfer not found.");
      }

      const glIDInterestTransfer = interestResult[0].GLIDInterestTransfer;
      console.log(`Retrieved GLIDInterestTransfer: ${glIDInterestTransfer}`);

      // Step 3: Check if the GLIDInterestTransfer exists in the GLID column
      const queryCheckInterestTransfer = `
            SELECT GLName
            FROM dbo.tbLedgerMaster
            WHERE GLID = ?
          `;

      sql.query(conn, queryCheckInterestTransfer, [glIDInterestTransfer], (err, transferResult) => {
        if (err) {
          console.error("Error checking GLIDInterestTransfer in GLID column:", err);
          return res.status(500).send("Error checking GLIDInterestTransfer in GLID column.");
        }

        if (transferResult.length === 0) {
          return res.status(404).send("No matching GLID found for GLIDInterestTransfer.");
        }

        const matchingGLName = transferResult[0].GLName;
        console.log(`Matching GLName for GLIDInterestTransfer: ${matchingGLName}`);

        // Step 4: Return the matching GLName for the GLIDInterestTransfer
        res.send({ GLName: matchingGLName });
      });
    });
  });
});
