app.get("/fetchAdditionalDateFiscalYear", (req, res) => {
  let baseDbName = req.query.orgName;
  if (!baseDbName) {
    return res.status(400).send({
      success: false,
      message: "dbName is required"
    });
  }

  // Ensure the database name ends with '_DB'
  const databaseName = baseDbName.endsWith('_DB') ? baseDbName : `${baseDbName}_DB`;
  console.log('Received name of database for fiscal year', databaseName);



  const connectionString = createConnectionStringForDatePopu(databaseName);

  const query = `
    SELECT TransactionStartDate, StartDate, EndDate
    FROM dbo.tbFiscalYearMaster
    WHERE CurrentFiscal = 1
  `;

  sql.query(connectionString, query, (err, rows) => {
    if (err) {
      console.error("Error fetching fiscal dates:", err);
      return res.status(500).send({
        success: false,
        message: "Error fetching fiscal dates"
      });
    }

    if (rows && rows.length > 0) {
      const data = rows[0];

      const formatDate = (d) => d ? new Date(d).toISOString().slice(0, 10) : '';

      res.json({
        success: true,
        transactionStartDate: formatDate(data.TransactionStartDate),
        fiscalYearStart: formatDate(data.StartDate),
        fiscalYearEnd: formatDate(data.EndDate)
      });
    } else {
      res.status(404).send({
        success: false,
        message: "No current fiscal year found"
      });
    }
  });
});


app.post('/checkIfInUse', (req, res) => {
  const { orgName, orgID, orgAlias } = req.body;
  console.log("Received user selected database:", orgName);
  console.log("Received user selected alias of database:", orgAlias);
  console.log("Received id of stored database:", orgID);

  const conn = req.session.conn;
  if (!conn) {
    console.error("Database connection not found in session");
    return res.status(500).send({ success: false, message: "Database connection not found" });
  }

  const query = `
    SELECT OrgID
    FROM dbo.tbOrgMaster
    WHERE OrgName = ? AND OrgAlias = ?
  `;

  sql.query(connectionString, query, [orgName, orgAlias], (err, result) => {
    if (err) {
      console.error('Error fetching OrgID from database:', err);
      return res.status(500).json({
        success: false,
        message: 'Error occurred while checking organization status.'
      });
    }

    // If result contains data (organization exists in DB)
    if (result.length > 0) {
      const dbOrgID = result[0].OrgID;
      console.log("OrgID fetched from database:", dbOrgID);

      // If the OrgID matches, it means it's in use and can't be deleted
      if (Number(orgID) === Number(dbOrgID)) {
        return res.status(400).json({
          success: false,
          message: 'This organization is currently in use and cannot be deleted.'
        });
      }

      // If OrgIDs don't match, the organization is not in use and deletion can proceed
      return res.status(200).json({
        success: true,
        message: 'Organization is not in use. Proceed with deletion.',
        SorgID: dbOrgID  // Return the OrgID to the frontend for further deletion process
      });
    } else {
      // If no matching organization is found in the database
      return res.status(404).json({
        success: false,
        message: 'Organization not found in the database.'
      });
    }
  });
});

