// Function to sanitize the organization name (to avoid SQL injection or invalid characters)
const sanitizeOrgName = (orgName) => {
  return orgName.replace(/[^a-zA-Z0-9_]/g, ''); // Just an example, adjust as needed
};
app.post("/deleteOrganization", async (req, res) => {
  const { recordToDeletee, orgID } = req.body;
  const conn = req.session.conn;
  const recordToDeleteFull = recordToDeletee.endsWith('_DB') ? recordToDeletee : `${recordToDeletee}_DB`;

  if (!recordToDeletee) {
    return res.status(400).send({ success: false, message: "Organization name is required" });
  }

  try {
    const pool = await sqlq.connect(connectionStringForDB); // standardize this
    await pool.request().input("OrgID", sqlq.Int, orgID).query(`DELETE FROM dbo.tbVoucherRights WHERE OrgID = @OrgID`);
    await pool.request().input("OrgID", sqlq.Int, orgID).query(`DELETE FROM dbo.tbReportHitCount WHERE LoginID = @OrgID`);
    await pool.request().input("OrgID", sqlq.Int, orgID).query(`DELETE FROM dbo.tbUserLog WHERE OrgID = @OrgID`);
    await pool.request().input("OrgID", sqlq.Int, orgID).query(`DELETE FROM dbo.tbOrgMaster WHERE OrgID = @OrgID`);

    const masterPool = await sqlq.connect(config); // config to master DB
    const result = await masterPool.request()
      .input("dbName", sqlq.NVarChar, recordToDeleteFull)
      .query("SELECT database_id FROM sys.databases WHERE name = @dbName");

    if (result.recordset.length === 0) {
      return res.status(404).send({ success: false, message: `Database "${recordToDeleteFull}" does not exist.` });
    }

    const forceDrop = `
      ALTER DATABASE [${recordToDeleteFull}] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
      DROP DATABASE [${recordToDeleteFull}];
    `;
    await masterPool.request().batch(forceDrop);

    res.send({ success: true, message: `Organization and database "${recordToDeleteFull}" deleted.` });
    console.log("database has been deleted from backend successfully");
  } catch (err) {
    console.error("Error during deletion:", err);
    res.status(500).send({ success: false, message: "Deletion failed", error: err.message });
  }
});
