app.post("/editdatabase", (req, res) => {
  const {
    DatabaseName,
    DatabaseAlias,
    updatedDatabaseName,
    updatedDatabaseAlias,
    Drive,
    Address1,
    Address2,
    Email,
    Fax,
    Phone1,
    Phone2,
    Pan,
    TransStartDate,
    FiscalStartYear,
    FiscalEnd,
    Remarks,
    Active,
    username
  } = req.body;
  console.log('Retrived init db name', DatabaseName);
  console.log("Retrived updated db is ", updatedDatabaseName);
  const conn = req.session.conn;

  const dbFullnametoedit = updatedDatabaseAlias.endsWith('_DB') ? updatedDatabaseAlias : `${updatedDatabaseAlias}_DB`;
  const connectionStringFordate = createConnectionStringForDatePopu(dbFullnametoedit);

  if (!updatedDatabaseName || !DatabaseName) {
    return res.status(400).json({ error: "Database name is required." });
  }

  const queryGetUserID = `
    SELECT UserID
    FROM dbo.tbUserMaster
    WHERE UserName = ?
  `;

  sql.query(connectionString, queryGetUserID, [username], (err, userResult) => {
    if (err) {
      console.error("Error retrieving UserID:", err);
      return res.status(500).json({ error: "Error retrieving UserID." });
    }

    if (userResult.length === 0) {
      return res.status(404).json({ error: "User not found." });
    }

    const userID = userResult[0].UserID;
    const active = Active ? 1 : 0;

    const queryUpdateOrg = `
      UPDATE dbo.tbOrgMaster
      SET 
        OrgName = ?, 
        OrgAlias = ?,
        Address1 = ?, 
        Address2 = ?,              
        Phone1 = ?,
        Phone2 = ?,
        Fax = ?,
        Email = ?,
        Pan = ?,
        Status = ?,
        DBName = ?,
        Drive = ?,
        LastSavedBy = ?, 
        LastSavedDateTime = GETDATE(),                
        Remarks = ?
      WHERE 
        OrgName = ?
    `;

    const queryUpdateFiscal = `
      UPDATE dbo.tbFiscalYearMaster
      SET 
        TransactionStartDate = ?, 
        StartDate = ?, 
        EndDate = ?,
        LastSavedBy = ?, 
        LastSavedDateTime = GETDATE()
      WHERE 
        CurrentFiscal = 1
    `;

    const updateOrgPromise = new Promise((resolve, reject) => {
      sql.query(connectionString, queryUpdateOrg, [
        updatedDatabaseName,
        updatedDatabaseAlias,
        sqlSafe(Address1),
        sqlSafe(Address2),
        sqlSafe(Phone1),
        sqlSafe(Phone2),
        sqlSafe(Fax),
        sqlSafe(Email),
        sqlSafe(Pan),
        active,
        dbFullnametoedit,
        Drive,
        userID,
        sqlSafe(Remarks),
        DatabaseName
      ], (err, result) => {
        if (err) {
          console.error("Error updating OrgMaster:", err);
          return reject("Failed to update OrgMaster.");
        }
        resolve("OrgMaster updated");
      });
    });

    const updateFiscalPromise = new Promise((resolve, reject) => {
      sql.query(connectionStringFordate, queryUpdateFiscal, [
        sqlSafe(TransStartDate),
        sqlSafe(FiscalStartYear),
        sqlSafe(FiscalEnd),
        userID
      ], (err, result) => {
        if (err) {
          console.error("Error updating FiscalYearMaster:", err);
          return reject("Failed to update FiscalYearMaster.");
        }
        resolve("FiscalYearMaster updated");
      });
    });

    Promise.all([updateOrgPromise, updateFiscalPromise])
      .then((results) => {
        console.log(results);
        res.json({ success: true, message: "Organization Master updated successfully." });
      })
      .catch((error) => {
        console.error("Update error:", error);
        res.status(500).json({ error: error });
      });
  });
});














