app.get('/get-users-log', (req, res) => {

  const mainquery = `
WITH LastLoginID AS (
    SELECT TOP 1 LoginID
    FROM tbUserLog
    ORDER BY LoginID DESC
)
SELECT 
    ul.UserID,
    ul.OrgID,
    om.OrgName,
    um.UserName,
    ul.ComputerName,
    ul.WinUserName,
    -- Convert M_Miti from dd/mm/yyyy to yyyy-mm-dd format
    CONCAT(CONVERT(varchar, TRY_CONVERT(date, ld.M_Miti, 103), 23), ' ', FORMAT(ul.LoginDateTime, 'HH:mm:ss')) AS LoginMiti,
    CASE 
        WHEN ul.LoginID = (SELECT LoginID FROM LastLoginID) THEN 'CurrentLogin'
        ELSE CONCAT(CONVERT(varchar, TRY_CONVERT(date, ld2.M_Miti, 103), 23), ' ', FORMAT(ul.LogoutDateTime, 'HH:mm:ss'))
    END AS LogoutMiti
FROM tbUserLog ul
LEFT JOIN tbUserMaster um ON ul.UserID = um.UserID
LEFT JOIN tbOrgMaster om ON ul.OrgID = om.OrgID
LEFT JOIN tbLocalDate ld ON CONVERT(DATE, ul.LoginDateTime) = ld.M_date
LEFT JOIN tbLocalDate ld2 ON CONVERT(DATE, ul.LogoutDateTime) = ld2.M_date;

  `;

  sql.query(connectionString, mainquery, (err, results) => {
    if (err) {
      console.error("SQL Error:", err);
      return res.status(500).json({ error: "Database query failed" });
    }
    res.json(results);
  });
});

app.get('/get-users-hit-report', (req, res) => {

  const mainquery = `
  WITH LastCountID AS (
    SELECT TOP 1 CountID
    FROM tbReportHitCount
    ORDER BY CountID DESC
)
  SELECT 
    rh.ReportName, 
    ul.ComputerName, 
    ul.WinUserName, 
    um.UserName,
    -- Convert M_Miti from dd/mm/yyyy to yyyy-mm-dd format
    CONCAT(CONVERT(varchar, TRY_CONVERT(date, ld.M_Miti, 103), 23), ' ', FORMAT(rh.HitTime, 'HH:mm:ss')) AS LoginMiti,
    CASE 
        WHEN rh.CountID = (SELECT CountID FROM LastCountID) THEN 'CurrentLogin'
        ELSE 
            CONCAT(
                CONVERT(varchar, TRY_CONVERT(date, ld2.M_Miti, 103), 23), ' ', 
                FORMAT(rh.CloseTime, 'HH:mm:ss')
            )
    END AS LogoutMiti
FROM 
    tbReportHitCount rh
LEFT JOIN 
    tbUserLog ul ON rh.LoginID = ul.LoginID
LEFT JOIN 
    tbUserMaster um ON ul.UserID = um.UserID
LEFT JOIN 
    tbLocalDate ld ON CONVERT(DATE, rh.HitTime) = ld.M_date
LEFT JOIN 
    tbLocalDate ld2 ON CONVERT(DATE, rh.CloseTime) = ld2.M_date;
`;

  sql.query(connectionString, mainquery, (err, results) => {
    if (err) {
      console.error("SQL Error:", err);
      return res.status(500).json({ error: "Database query failed" });
    }
    res.json(results);
  });
});


