app.post('/search-fiscal-year', (req, res) => {
  const { FYMCurrentAll, FYMYearStartsFrom, FYMEndAt } = req.body;
  const conn = req.session.conn;

  const systemQuery = `SELECT TOP 1 DateType FROM tbSystemSettings`;

  sql.query(conn, systemQuery, (err, rows) => {
    if (err) {
      return res.status(500).json({ error: "Failed to read system settings" });
    }

    const dateType = rows[0]?.DateType;
    console.log("DateType:", dateType);

    let query;
    let params = [];

    // 🔹 1️⃣ If LD → use JOIN query (M_Miti)
    if (dateType === "LD") {
      query = `
        SELECT 
          ld1.M_Miti AS StartMiti,
          ld2.M_Miti AS EndMiti,
          fy.Remarks,
          fy.CurrentFiscal,
          fy.YearID
        FROM tbFiscalYearMaster fy
        LEFT JOIN SAJILODB.dbo.tbLocalDate ld1 ON fy.StartDate = ld1.M_date
        LEFT JOIN SAJILODB.dbo.tbLocalDate ld2 ON fy.EndDate = ld2.M_date
        WHERE 1=1
      `;
    }
    // 🔹 2️⃣ If NOT LD → use RAW AD query
    else {
      query = `
        SELECT 
          fy.StartDate AS StartMiti,
          fy.EndDate AS EndMiti,
          fy.Remarks,
          fy.CurrentFiscal,
          fy.YearID
        FROM tbFiscalYearMaster fy
        WHERE 1=1
      `;
    }

    // 🔹 filter current fiscal
    if (FYMCurrentAll === "current") {
      query += " AND fy.CurrentFiscal = 1";
    }

    // 🔹 filter date range
    if (FYMYearStartsFrom && FYMEndAt) {
      query += " AND fy.StartDate >= ? AND fy.EndDate <= ?";
      params.push(FYMYearStartsFrom, FYMEndAt);
    }

    // Run final query
    sql.query(conn, query, params, (err3, results) => {
      if (err3) {
        return res.status(500).json({ error: "Query failed", details: err3 });
      }

      // 🔹 Format AD dates before sending
      // 🔹 Format returned dates (for AD mode)
      results = results.map(row => {
        if (row.StartMiti instanceof Date) {
          row.StartMiti = row.StartMiti.toISOString().split("T")[0];
        }
        if (row.EndMiti instanceof Date) {
          row.EndMiti = row.EndMiti.toISOString().split("T")[0];
        }
        return row;
      });

      res.json(results);
      console.log(results);
    });
  });
});




