app.post("/update-action-right", (req, res) => {
  // Destructure the data from the request body
  const { RightID, Action, IsChecked } = req.body;

  // Map Action to the correct column name in the database
  let actionColumn = '';
  switch (Action) {
    case 'New':
      actionColumn = 'NewAction'; // Replace with your actual column name for "New" action
      break;
    case 'Edit':
      actionColumn = 'EditAction'; // Replace with your actual column name for "Edit" action
      break;
    case 'Delete':
      actionColumn = 'DeleteAction'; // Replace with your actual column name for "Delete" action
      break;
    case 'Root':
      actionColumn = 'IsRoot'; // Replace with your actual column name for "Root" action
      break;
    default:
      return res.status(400).json({ success: false, message: 'Invalid action' });
  }

  // SQL query to update the action for the given RightID
  const query = `
      UPDATE tbRightMaster
      SET ${actionColumn} = ?
      WHERE RightId = ?
  `;

  // Execute the SQL query to update the action
  sql.query(connectionString, query, [IsChecked ? 1 : 0, RightID], (err, result) => {
    if (err) {
      console.error("SQL Error:", err);
      return res.status(500).json({ success: false, message: 'Database error while updating action' });
    }

    // Now, check for the ParentRightID to find if the RightID has a parent
    const parentQuery = `
          SELECT ParentRightID FROM tbRightMaster WHERE RightId = ?
      `;

    sql.query(connectionString, parentQuery, [RightID], (err, rows) => {
      if (err) {
        console.error("SQL Error:", err);
        return res.status(500).json({ success: false, message: 'Error fetching ParentRightID' });
      }

      let parentRightID = null;
      if (rows.length > 0 && rows[0].ParentRightID) {
        parentRightID = rows[0].ParentRightID;
      }

      // Respond with the ParentRightID if it exists, and the success status
      res.json({
        success: true,
        message: 'Action updated successfully',
        ParentRightID: parentRightID
      });
    });
  });
});


