app.post('/getVoucherApproved', (req, res) => {
  const { startDateVA, endDateVA, voucherNameVA, VAActionType, page = 1 } = req.body;

  const conn = req.session.conn;

  const limit = 8000; // Show 8000 results per page
  const offset = (page - 1) * limit; // Calculate offset

  let query = `
    SELECT
      J.VoucherNo,
      J.CreatedDate,
      J.UDVNo,
      J.ApprovedUserID,
      J.CreatedUserID,
      UM.UserName,
      U.MenuName,
      ISNULL(SUM(D.DrAmount), 0) AS TotalDrAmount,
      ISNULL(SUM(D.CrAmount), 0) AS TotalCrAmount
    FROM tbJournalMaster J
    LEFT JOIN tbUserDefinedVoucher U ON J.UDVNo = U.UDVNo
    LEFT JOIN SAJILODB.dbo.tbUserMaster UM ON J.CreatedUserID = UM.UserID
    LEFT JOIN tbJournalDetails D ON J.JournalID = D.JournalID
    WHERE J.JV_Date BETWEEN ? AND ?
  `;

  const params = [startDateVA, endDateVA];

  // Only add filter for voucherNameVA if it's not "All"
  if (voucherNameVA && voucherNameVA !== "All") {
    query += ` AND U.MenuName = ?`; // Fixed column name
    params.push(voucherNameVA);
  }

  // Handle VAActionType filter
  if (VAActionType === "Approved") {
    query += " AND J.ApprovedUserID IS NOT NULL"; // Fixed column name
  } else if (VAActionType === "Unapproved") {
    query += " AND (J.ApprovedUserID IS NULL)";
  }

  query += ` 
  GROUP BY J.VoucherNo, J.CreatedDate, J.UDVNo, J.ApprovedUserID, J.CreatedUserID, UM.UserName, U.MenuName
`;

  // Count total rows for pagination
  let countQuery = `
    SELECT COUNT(*) AS totalRows FROM (
      SELECT J.VoucherNo FROM tbJournalMaster J
      LEFT JOIN tbUserDefinedVoucher U ON J.UDVNo = U.UDVNo
      WHERE J.JV_Date BETWEEN ? AND ?
    ) AS CountTable
  `;

  sql.query(conn, countQuery, [startDateVA, endDateVA], (countErr, countResult) => {
    if (countErr) {
      console.error("SQL Count Error:", countErr);
      return res.status(500).json({ error: "Failed to count rows" });
    }

    const totalRows = countResult[0].totalRows;
    const totalPages = Math.ceil(totalRows / limit);

    // Add pagination
    query += ` ORDER BY J.VoucherNo OFFSET ? ROWS FETCH NEXT ? ROWS ONLY`;
    params.push(offset, limit);

    sql.query(conn, query, params, (err, results) => {
      if (err) {
        console.error("SQL Error:", err);
        return res.status(500).json({ error: "Database query failed" });
      }
      console.log('all', results);
      // Calculate the combined amount
      results.forEach(result => {
        result.TotalAmount = result.TotalDrAmount + result.TotalCrAmount; // Sum of both amounts
      });

      res.json({
        currentPage: page,
        totalPages,
        results,
      });
    });
  });
});


app.post("/update-approved-status", (req, res) => {
  const { slAlias, locked } = req.body;
  console.log("Received locked value:", locked);

  const conn = req.session.conn;

  // If locked is empty, update ApprovedUserID and ApprovedDate to NULL
  if (!locked) {
    const nullQuery = `
      UPDATE tbJournalMaster
      SET ApprovedUserID = NULL, ApprovedDate = NULL
      WHERE VoucherNo = ?
    `;

    sql.query(conn, nullQuery, [slAlias], (err, updateResult) => {
      if (err) {
        console.error("Error updating ApprovedUserID to NULL:", err);
        return res.status(500).json({ success: false, error: "Database error while updating to NULL" });
      }

      console.log(`VoucherNo ${slAlias} reset successfully.`);
      return res.json({ success: true, message: "ApprovedUserID and ApprovedDate set to NULL" });
    });

    return;
  }

  // If locked is not empty, fetch UserID from tbUserMaster
  const minquery = `SELECT UserID FROM tbUserMaster WHERE UserName = ?`;

  sql.query(connectionString, minquery, [locked], (err, userResult) => {
    if (err) {
      console.error("Error fetching UserID:", err);
      return res.status(500).json({ success: false, error: "Database error while fetching UserID" });
    }

    // Check if any user was found
    if (!userResult || userResult.length === 0) {
      return res.status(400).json({ success: false, error: "User not found" });
    }

    const UserID = userResult[0].UserID;

    // Update query when locked has a value
    const query = `
      UPDATE tbJournalMaster
      SET ApprovedUserID = ?, ApprovedDate = GETDATE()
      WHERE VoucherNo = ?
    `;

    sql.query(conn, query, [UserID, slAlias], (err, updateResult) => {
      if (err) {
        console.error("Error updating ApprovedUserID:", err);
        return res.status(500).json({ success: false, error: "Database error while updating status" });
      }

      res.json({ success: true });
    });
  });
});


