app.post('/getVoucherPostNUPost', (req, res) => {
  const { startDateVPNUP, endDateVPNUP, voucherNameVPNUP, VPNUPActionType, VPNUPledgergrp, VPNUPAccountID, page = 1 } = req.body;

  const conn = req.session.conn;

  const limit = 8000; // Show 8000 results per page
  const offset = (page - 1) * limit; // Calculate offset

  let query = `
    SELECT
      J.VoucherNo,
      J.CreatedDate,
      J.UDVNo,
      J.PostUserID,
      J.CreatedUserID,
      UM.UserName,
      U.MenuName,
      ISNULL(SUM(D.DrAmount), 0) AS TotalDrAmount,
      ISNULL(SUM(D.CrAmount), 0) AS TotalCrAmount
    FROM tbJournalMaster J
    LEFT JOIN tbUserDefinedVoucher U ON J.UDVNo = U.UDVNo
    LEFT JOIN SAJILODB.dbo.tbUserMaster UM ON J.CreatedUserID = UM.UserID
    LEFT JOIN tbJournalDetails D ON J.JournalID = D.JournalID
    LEFT JOIN tbSubledgerMaster S ON S.SLID = D.SLID
    LEFT JOIN tbLedgerMaster L ON L.GLID = D.GLID
    WHERE J.JV_Date BETWEEN ? AND ?
  `;

  const params = [startDateVPNUP, endDateVPNUP];

  // Filter by voucher name
  if (voucherNameVPNUP && voucherNameVPNUP !== "All") {
    query += ` AND U.MenuName = ?`;
    params.push(voucherNameVPNUP);
  }

  // Filter by Action Type
  if (VPNUPActionType === "Posted") {
    query += " AND J.PostUserID IS NOT NULL";
  } else if (VPNUPActionType === "Unposted") {
    query += " AND (J.PostUserID IS NULL)";
  }

  // Filter by VPNUPAccountID (Compare SlAlias from tbSubledgerMaster → SLID in tbJournalDetails → JournalID in tbJournalMaster)
  if (VPNUPAccountID) {
    query += `
      AND EXISTS (
        SELECT 1 FROM tbJournalDetails D2
        JOIN tbSubledgerMaster S2 ON S2.SLID = D2.SLID
        WHERE S2.SlAlias = ? AND D2.JournalID = J.JournalID
      )
    `;
    params.push(VPNUPAccountID);
  }

  // Filter by VPNUPledgergrp (Compare GLName from tbLedgerMaster → GLID in tbJournalDetails → JournalID in tbJournalMaster)
  if (VPNUPledgergrp) {
    query += `
      AND EXISTS (
        SELECT 1 FROM tbJournalDetails D3
        JOIN tbLedgerMaster L2 ON L2.GLID = D3.GLID
        WHERE L2.GLName = ? AND D3.JournalID = J.JournalID
      )
    `;
    params.push(VPNUPledgergrp);
  }

  query += `
    GROUP BY J.VoucherNo, J.CreatedDate, J.UDVNo, J.PostUserID, J.CreatedUserID, UM.UserName, U.MenuName
  `;

  // Count total rows for pagination
  let countQuery = `
    SELECT COUNT(*) AS totalRows FROM (
      SELECT J.VoucherNo FROM tbJournalMaster J
      LEFT JOIN tbUserDefinedVoucher U ON J.UDVNo = U.UDVNo
      LEFT JOIN tbJournalDetails D ON J.JournalID = D.JournalID
      WHERE J.JV_Date BETWEEN ? AND ?
  `;

  if (VPNUPAccountID) {
    countQuery += `
      AND EXISTS (
        SELECT 1 FROM tbJournalDetails D2
        JOIN tbSubledgerMaster S2 ON S2.SLID = D2.SLID
        WHERE S2.SlAlias = ? AND D2.JournalID = J.JournalID
      )
    `;
  }

  if (VPNUPledgergrp) {
    countQuery += `
      AND EXISTS (
        SELECT 1 FROM tbJournalDetails D3
        JOIN tbLedgerMaster L2 ON L2.GLID = D3.GLID
        WHERE L2.GLName = ? AND D3.JournalID = J.JournalID
      )
    `;
  }

  countQuery += `) AS CountTable`;

  sql.query(conn, countQuery, params, (countErr, countResult) => {
    if (countErr) {
      console.error("SQL Count Error:", countErr);
      return res.status(500).json({ error: "Failed to count rows" });
    }

    const totalRows = countResult[0].totalRows;
    const totalPages = Math.ceil(totalRows / limit);

    // Add pagination
    query += ` ORDER BY J.VoucherNo OFFSET ? ROWS FETCH NEXT ? ROWS ONLY`;
    params.push(offset, limit);

    sql.query(conn, query, params, (err, results) => {
      if (err) {
        console.error("SQL Error:", err);
        return res.status(500).json({ error: "Database query failed" });
      }

      results.forEach(result => {
        result.TotalAmount = result.TotalDrAmount + result.TotalCrAmount;
      });

      res.json({
        currentPage: page,
        totalPages,
        results,
      });
    });
  });
});





