app.post('/api/save-shortcut', (req, res) => {
  const { action, description, group, controlKey, shortcutKey } = req.body;

  const getShortcutIdQuery = `SELECT ShortcutID FROM tbShortcutMaster WHERE ShortcutName = ?`;

  sql.query(connectionString, getShortcutIdQuery, [action], (err, rows) => {
    if (err) {
      console.error('Error fetching ShortcutID:', err);
      return res.status(500).json({ success: false, message: 'Error querying ShortcutMaster' });
    }

    if (!rows || rows.length === 0) {
      return res.status(404).json({ success: false, message: 'ShortcutName not found' });
    }

    const shortcutID = rows[0].ShortcutID;

    const insertQuery = `
          INSERT INTO tbShortcutDetails (ShortcutID, ShortcutCaption, ShortcutGroup, ControlKey, ShortcutKey)
          VALUES (?, ?, ?, ?, ?)
      `;

    const params = [shortcutID, description, group, controlKey, shortcutKey];

    sql.query(connectionString, insertQuery, params, (insertErr) => {
      if (insertErr) {
        console.error('Error inserting shortcut details:', insertErr);
        return res.status(500).json({ success: false, message: 'Insert failed' });
      }

      return res.json({ success: true });
    });
  });
});


app.get('/api/getJournalTotals', (req, res) => {
  const conn = req.session.conn;

  const glid = parseInt(req.query.glid, 10);
  const fromDate = req.query.formattedfromDate;
  const toDate = req.query.formattedtoDate;
  console.log("wwWFormdate", fromDate)
  console.log("wwtodate", toDate);
  if (isNaN(glid) || !fromDate || !toDate) {
    return res.status(400).json({ error: 'Invalid input. GLID, fromDate, and toDate are required.' });
  }

  const query = `
    SELECT 
      SUM(d.DrAmount) AS TotalDrAmount,
      SUM(d.CrAmount) AS TotalCrAmount
    FROM dbo.tbJournalDetails d
    WHERE d.JournalID IN (
      SELECT m.JournalID
      FROM dbo.tbJournalMaster m
      WHERE m.JournalID IN (
        SELECT JournalID
        FROM dbo.tbJournalDetails
        WHERE GLID = ?
      )
      AND ( m.JV_Miti) BETWEEN ? AND ?
    )
  `;

  sql.query(conn, query, [glid, fromDate, toDate], (err, result) => {
    if (err) {
      return res.status(500).json({ error: 'Database query error', details: err });
    }

    const totals = result && result.length > 0 ? result[0] : { TotalDrAmount: 0, TotalCrAmount: 0 };
    res.json(totals);
  });
});

