app.get("/get-ledger-sub-groups", (req, res) => {
  console.log("🚀 /get-ledger-sub-groups endpoint hit");

  if (!req.session.conn) {
    console.error("Missing database connection in session.");
    return res.status(500).json({ error: "Database connection not available" });
  }

  const conn = req.session.conn;
  let selectedIDs = req.query.id;

  if (!selectedIDs) {
    return res.status(400).json({ error: "No IDs provided" });
  }

  // Normalize to array and convert to numbers
  if (!Array.isArray(selectedIDs)) {
    selectedIDs = [selectedIDs];
  }

  selectedIDs = selectedIDs.map(id => parseInt(id)).filter(id => !isNaN(id));

  if (selectedIDs.length === 0) {
    return res.status(400).json({ error: "Invalid ID list" });
  }

  const placeholders = selectedIDs.map(() => '?').join(',');
  const query = `
      SELECT LgrGrpID, LgrSubGrpID,SubGrpName, SubGrpAlias
      FROM tbLedgerSubGroup
      WHERE LgrGrpID IN (${placeholders})
  `;

  sql.query(conn, query, selectedIDs, (err, rows) => {
    if (err) {
      console.error("Error fetching subgroups:", err);
      return res.status(500).json({ error: "Failed to fetch ledger subgroups" });
    }
    console.log("✅ Subgroups fetched:", rows);
    res.json(rows);
  });
});



