// Endpoint to validate environment before actual setup
app.get('/check-setup', async (req, res) => {
  const secondDb = req.query.secondDb?.trim();
  if (!secondDb) return res.status(400).json({ message: '❌ Missing secondDb name in request.' });

  try {
    const pool = await sqlq.connect(setupConfig);
    const result = await pool.request().query(`
      SELECT name FROM sys.databases WHERE name IN ('SAJILODB', '${secondDb}');
    `);
    await pool.close();

    const existing = result.recordset.map(r => r.name);
    if (existing.length > 0) {
      return res.status(400).json({
        message: 'You already have same name Database(s).Check your MSSQL server and try again.',
        existing,
      });
    }

    res.json({ message: '✅ All checks passed.', canProceed: true });
  } catch (err) {
    res.status(500).json({
      message: '❌ Cannot connect to MSSQL.',
      error: err.message,
    });
  }
});


