app.post('/api/save-nepali-calendar', (req, res) => {
  const { mapping } = req.body;

  if (!mapping || !Array.isArray(mapping) || mapping.length === 0) {
    return res.status(400).json({ success: false, message: 'Invalid data' });
  }

  const values = mapping
    .map(entry => `('${entry.bsDate}', '${entry.adDate}')`)
    .join(',');

  const query = `INSERT INTO tbLocalDate (M_Miti, M_date) VALUES ${values}`;

  sql.query(connectionString, query, (err) => {
    if (err) {
      console.error(err);
      return res.status(500).json({ success: false, message: 'Database insert error' });
    }
    res.status(200).json({ success: true, message: `Inserted ${mapping.length} rows.` });
  });
});


// ----------------------
// 2. DELETE
// ----------------------
app.delete('/api/delete-nepali-calendar', (req, res) => {
  const { bsYear } = req.body;
  if (!bsYear) return res.status(400).json({ success: false, message: 'Missing BS Year' });

  const pattern = `%/${bsYear}`;
  const deleteQuery = `DELETE FROM tbLocalDate WHERE M_Miti LIKE ?`;

  sql.query(connectionString, deleteQuery, [pattern], (err) => {
    if (err) {
      console.error(err);
      return res.status(500).json({ success: false, message: 'Database delete error' });
    }
    res.status(200).json({ success: true, message: `Deleted entries for BS Year ${bsYear}.` });
  });
});


