app.get('/api/get-nepali-calendar/:bsYear', (req, res) => {
  const bsYear = req.params.bsYear;
  if (!bsYear) return res.status(400).json({ success: false, message: 'Missing BS Year' });

  const query = `SELECT M_Miti, M_date FROM tbLocalDate WHERE M_Miti LIKE '%/${bsYear}'`;

  sql.query(connectionString, query, (err, rows) => {
    if (err) {
      console.error(err);
      return res.status(500).json({ success: false, message: 'Database read error' });
    }
    res.status(200).json({ success: true, mapping: rows });
  });
});


