app.put('/api/edit-nepali-calendar', (req, res) => {
  const { bsYear, mapping } = req.body;
  if (!bsYear || !Array.isArray(mapping) || !mapping.length) {
    return res.status(400).json({ success: false, message: 'Missing or invalid data' });
  }

  const deleteQuery = `DELETE FROM tbLocalDate WHERE M_Miti LIKE '%/${bsYear}'`;

  sql.query(connectionString, deleteQuery, (err) => {
    if (err) {
      console.error('Delete error:', err);
      return res.status(500).json({ success: false, message: 'Database delete error' });
    }

    const values = mapping
      .map(entry => `('${entry.bsDate}', '${entry.adDate}')`)
      .join(',');

    const insertQuery = `INSERT INTO tbLocalDate (M_Miti, M_date) VALUES ${values}`;

    sql.query(connectionString, insertQuery, (err2) => {
      if (err2) {
        console.error('Insert error:', err2);
        return res.status(500).json({ success: false, message: 'Database insert error' });
      }

      res.status(200).json({ success: true, message: `Updated ${mapping.length} entries for ${bsYear}.` });
    });
  });
});


