app.get('/api/get-nepali-date-info/:bsDate', (req, res) => {
  const bsDate = req.params.bsDate;
  const bsYear = bsDate.slice(-4);

  const getADQuery = `SELECT TOP 1 M_date FROM tbLocalDate WHERE M_Miti = ?`;
  sql.query(connectionString, getADQuery, [bsDate], (err, adRows) => {
    if (err) return res.status(500).json({ success: false, message: 'Database error', error: err });
    if (!adRows || adRows.length === 0) return res.status(404).json({ success: false, message: 'BS Date not found' });

    const adDate = adRows[0].M_date;

    const getAllQuery = `SELECT M_Miti FROM tbLocalDate WHERE M_Miti IS NOT NULL AND M_Miti LIKE ?`;
    const pattern = `%/${bsYear}`;
    sql.query(connectionString, getAllQuery, [pattern], (err2, rows) => {
      if (err2) return res.status(500).json({ success: false, message: 'Database error', error: err2 });

      const monthDayCounts = Array(12).fill(0);
      rows.forEach(row => {
        if (!row.M_Miti) return;
        const parts = row.M_Miti.split('/');
        if (parts.length < 2) return;
        const month = parseInt(parts[1], 10);
        if (!isNaN(month) && month >= 1 && month <= 12) {
          monthDayCounts[month - 1]++;
        }
      });

      res.status(200).json({ success: true, adDate, monthDayCounts });
    });
  });
});


// ----------------------
// 6. CHECK YEAR EXISTS
