app.get('/api/check-nepali-year/:bsDate', (req, res) => {
  const bsDate = req.params.bsDate;

  const query = `SELECT COUNT(*) as count FROM tbLocalDate WHERE M_Miti = ?`;

  sql.query(connectionString, query, [bsDate], (err, rows) => {
    if (err) return res.status(500).json({ success: false, message: 'Database error', error: err });

    const exists = rows[0].count > 0;
    res.status(200).json({ success: true, exists });
  });
});


// ----------------------
// 7. GET LAST DATE FOR NEW
// ----------------------
app.get('/api/get-last-ad-date/:bsYear', (req, res) => {
  const bsYear = parseInt(req.params.bsYear, 10);
  if (!bsYear || isNaN(bsYear)) {
    return res.status(400).json({ success: false, message: 'Invalid BS year' });
  }
  const prevYear = bsYear - 1;
  const pattern = `%/${prevYear}`;

  const query = `
    SELECT TOP 1 M_date
    FROM tbLocalDate
    WHERE M_Miti LIKE ?
    ORDER BY M_date DESC
  `;

  sql.query(connectionString, query, [pattern], (err, rows) => {
    if (err) {
      console.error('DB error:', err);
      return res.status(500).json({ success: false, message: 'Database error' });
    }
    if (!rows || rows.length === 0) {
      return res.status(404).json({ success: false, message: 'No data found for previous year' });
    }
    res.status(200).json({ success: true, lastDate: rows[0].M_date });
  });
});

//Journal voucher Backend
app.post("/search-journal-voucher", (req, res) => {
  const {
    JVDateFrom,
    JVDateTo,
    JVVoucherNO,
    JVEnteredBy,
    JVRemarks,
    JVShowEntryLog,
    JVLedger,
    JVSubLedger,
    JVSubAcType,
    JVDocClass,
    JVCollector,
    JVAmountOperator,
    JVAmount
  } = req.body;

  const JVDateFromm = JVDateFrom ? JVDateFrom.replace(/-/g, '/') : null;
  const JVDateToo = JVDateTo ? JVDateTo.replace(/-/g, '/') : null;

  const conn = req.session.conn;

  // Fetch DateType and DateFormat
  const systemSettingsQuery = "SELECT TOP 1 DateType, DateFormat FROM tbSystemSettings";
  sql.query(conn, systemSettingsQuery, (err, result) => {
    if (err) {
      console.error("Error fetching settings:", err);
      return res.status(500).json({ error: "Database error" });
    }

    const dateType = result[0]?.DateType?.trim();
    let dateFormat = result[0]?.DateFormat?.trim() || 'yyyy/MM/dd';

    if (!dateType) {
      return res.status(400).json({ error: "DateType not configured" });
    }

    // fix invalid uppercase
    dateFormat = dateFormat
      .replace(/YYYY/g, 'yyyy')
      .replace(/YY/g, 'yy')
      .replace(/DD/g, 'dd')
      .replace(/D/g, 'd');

    // detect separator in DateFormat
    let separator = '/';
    if (dateFormat.includes('-')) separator = '-';
    else if (dateFormat.includes('.')) separator = '.';

    console.log("Using DateType:", dateType);
    console.log("Corrected DateFormat:", dateFormat);
    console.log("Chosen Separator:", separator);

    let query = `
      SELECT 
        m.JournalID,
        m.VoucherNo,
        ISNULL(d.DetailsCount, 0) AS DetailsCount,
        ISNULL(d.TotalDrAmount, 0) AS TotalDrAmount,
        ISNULL(d.TotalCrAmount, 0) AS TotalCrAmount,
        m.Remarks,
        dc.DocClassName,
        cc.CollectorName,
    (
  SELECT TOP 1 lm.GLName
  FROM tbJournalDetails jd
  INNER JOIN tbLedgerMaster lm ON jd.GLID = lm.GLID
  WHERE jd.JournalID = m.JournalID
) AS GLName,
(
  SELECT TOP 1 lm.SavingorLoan
  FROM tbJournalDetails jd
  INNER JOIN tbLedgerMaster lm ON jd.GLID = lm.GLID
  WHERE jd.JournalID = m.JournalID
) AS SavingorLoan,


        uc.UserName AS Creator,
        up.UserName AS Poster,
        um.UserName AS Modifier,
        ua.UserName AS Approver,
    `;

    let joinClauses = `
      FROM tbJournalMaster m
      LEFT JOIN (
          SELECT 
              JournalID,
              COUNT(*) AS DetailsCount,
              SUM(DrAmount) AS TotalDrAmount,
              SUM(CrAmount) AS TotalCrAmount
          FROM tbJournalDetails
          GROUP BY JournalID
      ) d ON m.JournalID = d.JournalID
      LEFT JOIN SAJILODB.dbo.tbUserMaster um ON m.ModifiedUserID = um.UserID 
      LEFT JOIN SAJILODB.dbo.tbUserMaster uc ON m.CreatedUserID = uc.UserID 
      LEFT JOIN SAJILODB.dbo.tbUserMaster ua ON m.ApprovedUserID = ua.UserID 
      LEFT JOIN SAJILODB.dbo.tbUserMaster up ON m.PostUserID = up.UserID
      LEFT JOIN tbDocClassMaster dc ON m.DocClassID = dc.DocClassID
      LEFT JOIN tbCollectorMaster cc ON m.CollectorID = cc.CollectorID
     


    `;

    const params = [];
    let fromToFilter = `WHERE 1=1 AND m.UDVNo = 1`;

    if (dateType === 'LD') {
      joinClauses += `
        LEFT JOIN SAJILODB.dbo.tbLocalDate lApproved ON CONVERT(date, lApproved.M_Date) = CONVERT(date, m.ApprovedDate)
        LEFT JOIN SAJILODB.dbo.tbLocalDate lCreated ON CONVERT(date, lCreated.M_Date) = CONVERT(date, m.CreatedDate)
        LEFT JOIN SAJILODB.dbo.tbLocalDate lModified ON CONVERT(date, lModified.M_Date) = CONVERT(date, m.ModifiedDate)
        LEFT JOIN SAJILODB.dbo.tbLocalDate lPost ON CONVERT(date, lPost.M_Date) = CONVERT(date, m.PostDate)
       

      `;

      query += `
        REPLACE(m.JV_Miti, '/', '${separator}') AS JV_Miti,
        (REPLACE(lCreated.M_Miti, '/', '${separator}') + ' ' + CONVERT(varchar(8), m.CreatedDate, 108)) AS CreatedDate,
        REPLACE(lApproved.M_Miti, '/', '${separator}') AS ApprovedDate,
        REPLACE(lModified.M_Miti, '/', '${separator}') AS ModifiedDate,
        REPLACE(lPost.M_Miti, '/', '${separator}') AS PostDate,
        m.JV_Date
      `;

      if (JVDateFromm && JVDateToo) {
        fromToFilter += " AND m.JV_Miti BETWEEN ? AND ? ";
        params.push(JVDateFromm, JVDateToo);
      }

    } else if (dateType === 'AD') {
      query += `
        FORMAT(m.JV_Date, '${dateFormat}') AS JV_Miti,
        FORMAT(m.CreatedDate, '${dateFormat} HH:mm:ss') AS CreatedDate,
        FORMAT(m.ApprovedDate, '${dateFormat}') AS ApprovedDate,
        FORMAT(m.ModifiedDate, '${dateFormat}') AS ModifiedDate,
        FORMAT(m.PostDate, '${dateFormat}') AS PostDate
      `;

      if (JVDateFrom && JVDateTo) {
        fromToFilter += " AND m.JV_Date BETWEEN ? AND ? ";
        params.push(JVDateFrom, JVDateTo);
      }

    } else {
      joinClauses += `
        LEFT JOIN SAJILODB.dbo.tbLocalDate lJV ON CONVERT(date, lJV.M_Date) = CONVERT(date, m.JV_Date)
        LEFT JOIN SAJILODB.dbo.tbLocalDate lApproved ON CONVERT(date, lApproved.M_Date) = CONVERT(date, m.ApprovedDate)
        LEFT JOIN SAJILODB.dbo.tbLocalDate lCreated ON CONVERT(date, lCreated.M_Date) = CONVERT(date, m.CreatedDate)
        LEFT JOIN SAJILODB.dbo.tbLocalDate lModified ON CONVERT(date, lModified.M_Date) = CONVERT(date, m.ModifiedDate)
        LEFT JOIN SAJILODB.dbo.tbLocalDate lPost ON CONVERT(date, lPost.M_Date) = CONVERT(date, m.PostDate)
      `;

      query += `
        REPLACE(lJV.M_Miti, '/', '${separator}') AS JV_Miti,
        (REPLACE(lCreated.M_Miti, '/', '${separator}') + ' ' + CONVERT(varchar(8), m.CreatedDate, 108)) AS CreatedDate,
        REPLACE(lApproved.M_Miti, '/', '${separator}') AS ApprovedDate,
        REPLACE(lModified.M_Miti, '/', '${separator}') AS ModifiedDate,
        REPLACE(lPost.M_Miti, '/', '${separator}') AS PostDate
      `;

      if (JVDateFrom && JVDateTo) {
        fromToFilter += " AND m.JV_Date BETWEEN ? AND ? ";
        params.push(JVDateFrom, JVDateTo);
      }
    }

    if (JVVoucherNO) {
      fromToFilter += " AND m.VoucherNo = ? ";
      params.push(JVVoucherNO);
    }

    if (JVRemarks) {
      fromToFilter += " AND m.Remarks = ? ";
      params.push(JVRemarks);
    }

    if (JVDocClass) {
      fromToFilter += " AND dc.DocClassName = ? ";
      params.push(JVDocClass);
    }

    if (JVCollector) {
      fromToFilter += " AND cc.CollectorName = ? ";
      params.push(JVCollector);
    }

    if (JVEnteredBy) {
      fromToFilter += " AND uc.UserName = ? ";
      params.push(JVEnteredBy);
    }
    if (JVLedger) {
      fromToFilter += `
    AND EXISTS (
      SELECT 1
      FROM tbJournalDetails jd
      INNER JOIN tbLedgerMaster lm ON jd.GLID = lm.GLID
      WHERE jd.JournalID = m.JournalID
      AND lm.GLName = ?
    )
  `;
      params.push(JVLedger);
    }

    if (JVSubAcType) {
      fromToFilter += `
    AND EXISTS (
      SELECT 1
      FROM tbJournalDetails jd
      INNER JOIN tbLedgerMaster lm ON jd.GLID = lm.GLID
      WHERE jd.JournalID = m.JournalID
      AND lm.SavingorLoan = ?
    )
  `;
      params.push(JVSubAcType);
    }



    const allowedOperators = ['=', '<>', '<', '>', '<=', '>='];
    if (JVAmount && allowedOperators.includes(JVAmountOperator)) {
      fromToFilter += ` AND ISNULL(d.TotalDrAmount, 0) ${JVAmountOperator} ? `;
      params.push(JVAmount);
    }

    const finalQuery = query + joinClauses + fromToFilter;

    console.log("Final Query:", finalQuery);
    console.log("Params:", params);

    sql.query(conn, finalQuery, params, (err, rows) => {
      if (err) {
        console.error("Database Query Error:", err);
        return res.status(500).json({ error: "Database error" });
      }
      res.json(rows);
    });
  });
});

