app.post('/copy-selected-master', async (req, res) => {
  const { selectedGroups = [], selectedSubGroups = [], selectedLedgers = [] } = req.body;
  console.log('JJJJ', selectedGroups, selectedSubGroups, selectedLedgers)

  const sourceCon = req.session.connectionString;
  const targetCon = req.session.conn;
  console.log(sourceCon, targetCon)

  try {
    // COPY GROUPS
    for (const id of selectedGroups) {
      const result = await queryOneRow(sourceCon, `SELECT * FROM tbLedgerGroup WHERE LgrGrpID = ?`, [id]);
      if (result) {
        await insertIfNotExists(targetCon, 'tbLedgerGroup', result, 'LgrGrpID');
      }
    }

    // COPY SUBGROUPS
    for (const id of selectedSubGroups) {
      const result = await queryOneRow(sourceCon, `SELECT * FROM tbLedgerSubGroup WHERE LgrSubGrpID = ?`, [id]);
      if (result) {
        await insertIfNotExists(targetCon, 'tbLedgerSubGroup', result, 'LgrSubGrpID');
      }
    }

    // COPY LEDGERS
    for (const id of selectedLedgers) {
      const result = await queryOneRow(sourceCon, `SELECT * FROM tbLedgerMaster WHERE GLID = ?`, [id]);
      if (result) {
        await insertIfNotExists(targetCon, 'tbLedgerMaster', result, 'GLID');
      }
    }

    res.json({ message: '✅ Selected master data copied successfully.' });
  } catch (err) {
    console.error('❌ Error during master copy:', err);
    res.status(500).json({ message: '❌ Failed to copy master data.', error: err.message });
  }
});

// Helper to fetch one row
function queryOneRow(connStr, query, params) {
  return new Promise((resolve, reject) => {
    sql.query(connStr, query, params, (err, rows) => {
      if (err) return reject(err);
      resolve(rows[0] || null);
    });
  });
}

// Helper to insert if not exists
function insertIfNotExists(connStr, tableName, rowData, primaryKey) {
  return new Promise((resolve, reject) => {
    const checkQuery = `SELECT COUNT(*) AS count FROM ${tableName} WHERE ${primaryKey} = ?`;
    sql.query(connStr, checkQuery, [rowData[primaryKey]], (err, result) => {
      if (err) return reject(err);
      if (result[0].count > 0) return resolve(); // already exists

      const cols = Object.keys(rowData);
      const placeholders = cols.map(() => '?').join(',');
      const values = Object.values(rowData);

      const insertQuery = `
      SET IDENTITY_INSERT ${tableName} ON;
      INSERT INTO ${tableName} (${cols.join(',')}) VALUES (${placeholders})
       SET IDENTITY_INSERT ${tableName} OFF;
      `;
      sql.query(connStr, insertQuery, values, (insertErr) => {
        if (insertErr) return reject(insertErr);
        resolve();
      });
    });
  });
}

