app.post('/api/selectallpottablematuredacc', async (req, res) => {
  const conn = req.session.conn;
  const { glNames, formattedFrom, format } = req.body;
  console.log("Received GLNames and date from frontend:", glNames, formattedFrom);
  // Convert YYYY/MM/DD → DD/MM/YYYY
  let formattedDate = null;
  if (formattedFrom) {
    const [year, month, day] = formattedFrom.split('/');
    formattedDate = `${day}/${month}/${year}`;
  }

  console.log("Converted date:", formattedDate);
  if (!Array.isArray(glNames) || glNames.length === 0) {
    console.warn("No GLNames provided or empty array");
    return res.status(400).json({ error: 'No GLNames provided' });
  }


  try {
    const jvmitiQuery = `SELECT M_date FROM tbLocalDate WHERE M_Miti = ?`;
    sql.query(connectionString, jvmitiQuery, [formattedDate], (err, resultJV) => {
      if (err) {
        console.error(err);
        res
          .status(400)
          .send({ success: false, message: "Error querying JVMiti" });
      }
      const JVMITI_raw = resultJV[0].M_date;
      // Convert ISO date (2025-10-16T00:00:00.000Z) → 2025-10-16
      const JVMITI = new Date(JVMITI_raw).toISOString().split('T')[0];
      console.log('Found JV-Date vale', JVMITI)
      const glNameList = glNames.map(name => `'${name.replace(/'/g, "''")}'`).join(',');
      console.log("Formatted GLNameList for query:", glNameList);

      // Step 1: Find GLID for each GLName
      const glidQuery = `
      SELECT GLID, GLName
      FROM dbo.tbLedgerMaster
      WHERE GLName IN (${glNameList})
    `;
      console.log("GLID Query:", glidQuery);

      sql.query(conn, glidQuery, (err, glidRows) => {
        if (err) {
          console.error("Error in GLID query:", err);
          return res.status(500).json({ error: 'Failed to get GLIDs' });
        }

        console.log("GLID rows returned:", glidRows.length);
        if (glidRows.length === 0) {
          console.warn("No GLIDs found for given GLNames");
          return res.json([]);
        }

        const glidMap = {};
        glidRows.forEach(row => glidMap[row.GLID] = row.GLName);

        const glidList = glidRows.map(row => row.GLID).join(',');
        console.log("GLID List for Subledger query:", glidList);

        // Step 2: Get Subledger data using GLID
        const subledgerQuery = `
        SELECT 
          GLID, SLName, SLAlias, Phone1, Mobile, Address1, LoanAmount, InstallmentAmount
        FROM dbo.tbSubLedgerMaster
        WHERE GLID IN (${glidList}) AND MaturityDate <= '${JVMITI}'
      `;
        console.log("Subledger Query:", subledgerQuery);

        sql.query(conn, subledgerQuery, (err, subRows) => {
          if (err) {
            console.error("Error in Subledger query:", err);
            return res.status(500).json({ error: 'Failed to get Subledger data' });
          }

          console.log("Subledger rows returned:", subRows.length);
          if (subRows.length === 0) {
            console.warn("No Subledger data found for given GLIDs");
            return res.json([]);
          }

          const slNames = subRows.map(row => `'${row.SLName.replace(/'/g, "''")}'`).join(',');
          console.log("SLName List for Member query:", slNames);

          // Step 3: Join with MemberMaster using SLName = MemberName
          const memberQuery = `
          SELECT MemberName, MemberAlias
          FROM dbo.tbMemberMaster
          WHERE MemberName IN (${slNames})
        `;
          console.log("Member Query:", memberQuery);

          sql.query(conn, memberQuery, (err, memberRows) => {
            if (err) {
              console.error("Error in Member query:", err);
              return res.status(500).json({ error: 'Failed to get member aliases' });
            }

            console.log("Member rows returned:", memberRows.length);

            const memberMap = {};
            memberRows.forEach(row => {
              memberMap[row.MemberName] = row.MemberAlias;
            });

            // Step 4: Final Table Format
            const result = subRows.map((row, i) => ({
              sn: i + 1,
              accountType: glidMap[row.GLID] || '',
              accountNo: row.SLAlias || '',
              account: row.SLName || '',
              memberId: memberMap[row.SLName] || '',
              address: row.Address1 || '',
              contactNo: row.Phone1 || '',
              mobile: row.Mobile || '',
              checkbox: true,
              investmentDate: row.FirstInstallmentDate,
              maturityDate: row.MaturityDate,
              lastPaymentDate: '',
              installment: '',
              approvedLoan: row.LoanAmount || '',
              installmentAmount: row.InstallmentAmount || '',
              balancePrinciple: '',
              colAfterBalanceP: true,
              balanceInterest: '',
              colAfterBalanceI: true,
              day: ''
            }));

            console.log("Final result count:", result.length);
            return res.json(result);
          });
        });
      });
    });

  } catch (err) {
    console.error("Unexpected server error:", err);
    res.status(500).json({ error: 'Server Error' });
  }
});

