app.get('/api/nextJournalVoucher', (req, res) => {
  const conn = req.session.conn;
  const menuName = 'Journal Voucher';

  const udvQuery = `SELECT UDVNo FROM tbUserDefinedVoucher WHERE MenuName = ?`;
  sql.query(conn, udvQuery, [menuName], (err, udvRows) => {
    if (err) {
      console.error("SQL error fetching UDVNo:", err);
      return res.status(500).send({ message: "Error fetching UDVNo" });
    }
    if (!udvRows || udvRows.length === 0) {
      return res.status(404).send({ message: "No UDVNo found for MenuName " + menuName });
    }
    const udvNo = udvRows[0].UDVNo;
  

    const settingsQuery = `
      SELECT BodyLength, Prefix, Suffix, StartFrom, EndTo FROM tbAutoNumberSetting WHERE VoucherId = ?
    `;
    sql.query(conn, settingsQuery, [udvNo], (err, settingsRows) => {
      if (err) {
        console.error("SQL error fetching AutoNumber settings:", err);
        return res.status(500).send({ message: "Error fetching AutoNumber settings" });
      }
      if (!settingsRows || settingsRows.length === 0) {
        return res.status(404).send({ message: "No AutoNumber settings found for VoucherId " + udvNo });
      }

      const { BodyLength, Prefix, Suffix, StartFrom, EndTo } = settingsRows[0];

      const likePattern = `${Prefix}%${Suffix}`;
      const lastVoucherQuery = `
        SELECT TOP 1 VoucherNo FROM tbJournalMaster
        WHERE VoucherNo LIKE ?
        ORDER BY VoucherNo DESC
      `;
      sql.query(conn, lastVoucherQuery, [likePattern], (err, lastVoucherRows) => {
        if (err) {
          console.error("SQL error fetching last VoucherNumber:", err);
          return res.status(500).send({ message: "Error fetching last VoucherNumber" });
        }

        let nextNumber;
        if (!lastVoucherRows || lastVoucherRows.length === 0) {
          nextNumber = parseInt(StartFrom);
          if (nextNumber < 1) {
            nextNumber = 1;  // skip 0, start from 1
          }
        } else {
          const lastVoucher = lastVoucherRows[0].VoucherNo;
          const numericPart = lastVoucher.substring(Prefix.length, lastVoucher.length - Suffix.length);
          nextNumber = parseInt(numericPart) + 1;
        }

        if (EndTo && nextNumber > parseInt(EndTo)) {
          return res.status(400).send({ message: "Next voucher number exceeds EndTo limit" });
        }

        const numericLength = BodyLength - (Prefix.length + Suffix.length);
        if (numericLength <= 0) {
          return res.status(400).send({ message: "BodyLength too small for prefix and suffix" });
        }

        const numberStr = nextNumber.toString().padStart(numericLength, '0');
        const voucherNumber = `${Prefix}${numberStr}${Suffix}`;

        console.log('voucherNumber', voucherNumber);

        return res.json({ voucherNumber });
      });
    });
  });
});

