app.post("/fetchccapeditmemaccdetails", async (req, res) => {
  const conn = req.session.conn;

  if (!conn) {
    console.error("No database connection found in session");
    return res.status(500).send("Database connection error");
  }

  const { ccapeditmemMemberIdval } = req.body;
  console.log("MemberAlias param:", ccapeditmemMemberIdval, typeof ccapeditmemMemberIdval);

  try {
    // 1️⃣ Get MemberID
    const MemberIDquery = `
      SELECT MemberID
      FROM tbMemberMaster
      WHERE MemberAlias = ?
    `;
    const memberidrow = await runQuery(conn, MemberIDquery, [ccapeditmemMemberIdval]);

    if (!memberidrow || memberidrow.length === 0) {
      return res.json({ success: false, message: "Member ID not found" });
    }

    const MemID = memberidrow[0].MemberID;
    console.log("📌 Found MemberID:", MemID);

    // 2️⃣ Get subledger details
    const query = `
      SELECT 
        slm.SLID,
        slm.AccountOpenDate,
        slm.SLName,
        slm.SlAlias,
        slm.GLID,
        lm.GLName,
        dob_bs.M_Miti AS AccountOpenDate_NP
      FROM dbo.tbSubLedgerMaster slm 
      INNER JOIN dbo.tbLedgerMaster lm ON slm.GLID = lm.GLID
      LEFT JOIN SAJILODB.dbo.tbLocalDate dob_bs ON dob_bs.M_Date = slm.AccountOpenDate
      WHERE slm.MemberID = ?;
    `;
    const rows = await runQuery(conn, query, [MemID]);

    if (!rows || rows.length === 0) {
      return res.json({ success: true, transactions: [] });
    }

    // 3️⃣ Get balances for all SLIDs at once
    const slids = rows.map(r => r.SLID);
    let balances = {};

    if (slids.length > 0) {
      const balQuery = `
        SELECT SLID, 
               SUM(ISNULL(DrAmount,0)) AS TotalDr, 
               SUM(ISNULL(CrAmount,0)) AS TotalCr
        FROM dbo.tbJournalDetails
        WHERE SLID IN (${slids.map(() => '?').join(',')})
        GROUP BY SLID
      `;
      const balRows = await runQuery(conn, balQuery, slids);

      // map SLID -> formatted balance
      balRows.forEach(b => {
        const diff = (b.TotalDr || 0) - (b.TotalCr || 0);
        if (diff >= 0) {
          balances[b.SLID] = `${diff} Dr`;
        } else {
          balances[b.SLID] = `${Math.abs(diff)} Cr`;
        }
      });
    }

    // 4️⃣ Prepare transactions
    const transactions = rows.map((row, index) => ({
      SLName: row.SLName ?? "",
      SlAlias: row.SlAlias ?? "",
      GLName: row.GLName ?? "",
      AccountOpenDate: row.AccountOpenDate ?? "",
      AccountOpenDateNP: formatNepaliDateToYMD(row.AccountOpenDate_NP),
      Balance: balances[row.SLID] ?? "0 ",  // default DR if no journal entry
      SNo: index + 1
    }));

    return res.json({
      success: true,
      transactions
    });

  } catch (err) {
    console.error("❌ Error fetching /fetchccapeditmemaccdetails transactions:", err);
    return res.status(500).json({
      success: false,
      message: "Server error",
      error: err.message
    });
  }
});




// ------------------------
// Helper at the top of  backend
// ------------------------
function runQuery(conn, query, params = []) {
  return new Promise((resolve, reject) => {
    sql.query(conn, query, params, (err, rows) => {
      if (err) return reject(err);
      resolve(rows);
    });
  });
}

function formatQuery(query, params) {
  let formatted = query;
  params.forEach(param => {
    let value;
    if (typeof param === "string") {
      // Wrap strings in quotes
      value = `'${param}'`;
    } else if (param instanceof Date) {
      value = `'${param.toISOString().slice(0, 10)}'`;
    } else {
      value = param;
    }
    formatted = formatted.replace("?", value);
  });
  return formatted;
}

