app.get("/api/pearls/protectionANDExpenditureSection", async (req, res) => {
  const conn = req.session.conn;

  try {
    const today = new Date();
    const todayStr = today.toISOString().split('T')[0];

    // Set the filter date (example: 2025-07-15)
    const cutoffDate = '2025-07-15';

    // --- P SECTION QUERY ---
    const protectionQuery = `
      SELECT
        SUM(CASE 
              WHEN DATEDIFF(month, MaturityDate, '${todayStr}') > 12 AND Closed = 0 
              THEN LoanAmount ELSE 0 END) AS Over12Months,
        SUM(CASE 
              WHEN DATEDIFF(month, MaturityDate, '${todayStr}') BETWEEN 1 AND 12 AND Closed = 0 
              THEN LoanAmount ELSE 0 END) AS Between1And12Months,
        SUM(CASE 
              WHEN DATEDIFF(month, MaturityDate, '${todayStr}') > 0 AND Closed = 0 
              THEN LoanAmount ELSE 0 END) AS TotalDelinquent,
        SUM(LoanAmount) AS TotalLoan
      FROM tbSubLedgerMaster
      WHERE LoanAmount > 0
        AND MaturityDate <= '${cutoffDate}'
    `;

    sql.query(conn, protectionQuery, async (err, rows) => {
      if (err) {
        console.error(err);
        return res.status(500).json({ error: "Failed to fetch protection ratios" });
      }

      const row = rows[0];
      const totalAllowance = (row.TotalDelinquent || 0) * 0.10;

      // --- P RATIOS ---
      const P1 = row.Over12Months > 0 ? (totalAllowance / row.Over12Months) * 100 : 0;
      const P2 = row.Between1And12Months > 0 ? (totalAllowance / row.Between1And12Months) * 100 : 0;
      const P3 = row.TotalDelinquent > 0 ? (totalAllowance / row.TotalDelinquent) * 100 : 0;

      // --- E SECTION PREP: fetch total assets from Ledger ---
      const ledgerQuery = `
  SELECT 
    SUM(CASE WHEN g.IEAL = 'A' THEN (j.CrAmount - j.DrAmount) ELSE 0 END) AS TotalAssets
  FROM tbJournal j
  INNER JOIN tbLedgerMaster l ON j.GLID = l.GLID
  LEFT JOIN tbLedgerGroup g ON l.LgrGrpID = g.LgrGrpID
  WHERE j.JV_Date <= '${cutoffDate}'
`;


      sql.query(conn, ledgerQuery, (err2, ledgerRows) => {
        if (err2) {
          console.error(err2);
          return res.status(500).json({ error: "Failed to fetch ledger balances" });
        }

        const ledger = ledgerRows[0];
        const totalAssets = ledger.TotalAssets || 0;

        // --- E1: Net Loans / Total Assets ---
        const netLoan = (row.TotalLoan || 0) - ((row.Over12Months || 0) + (row.Between1And12Months || 0));
        const E1 = totalAssets > 0 ? (netLoan / totalAssets) * 100 : 0;

        res.json({
          P1, P2, P3,
          raw: { ...row, totalAllowance },
          E: { E1 } // we'll add E2–E9 later
        });
      });
    });

  } catch (err) {
    console.error(err);
    res.status(500).json({ error: "Failed to fetch ratios" });
  }
});

app.post("/api/getExpenditureSection", async (req, res) => {
  const conn = req.session.conn;
  const { filterDate } = req.body;  // e.g. "2025-07-15"

  if (!filterDate) {
    return res.json({ success: false, message: "Missing filterDate" });
  }

  try {
    // 1. Fetch all expenditure accounts
    const ledgersQuery = `
      SELECT LM.GLID, LM.GLName, LG.IEAL
      FROM tbLedgerMaster LM
      INNER JOIN tbLedgerGroup LG ON LM.LgrGrpID = LG.LgrGrpID
      WHERE LG.IEAL = 'E'
    `;

    const ledgersResult = await new Promise((resolve, reject) => {
      sql.query(conn, ledgersQuery, (err, rows) => {
        if (err) reject(err);
        else resolve(rows);
      });
    });

    if (!ledgersResult || ledgersResult.length === 0) {
      return res.json({ success: true, data: [], total: 0 });
    }

    // 2. Calculate amounts for each GLID
    const expenditureData = [];
    let grandTotal = 0;

    for (const ledger of ledgersResult) {
      const journalQuery = `
        SELECT 
          ISNULL(SUM(DrAmount), 0) AS TotalDr,
          ISNULL(SUM(CrAmount), 0) AS TotalCr
        FROM tbJournal
        WHERE GLID = ${ledger.GLID}
          AND JV_Date <= '${filterDate}'
      `;

      const journalResult = await new Promise((resolve, reject) => {
        sql.query(conn, journalQuery, (err, rows) => {
          if (err) reject(err);
          else resolve(rows[0]);
        });
      });

      const balance = journalResult.TotalDr - journalResult.TotalCr;

      expenditureData.push({
        GLID: ledger.GLID,
        GLName: ledger.GLName,
        Amount: balance
      });

      grandTotal += balance;
    }

    // 3. Respond back
    res.json({
      success: true,
      data: expenditureData,
      total: grandTotal
    });

  } catch (error) {
    console.error("Error fetching Expenditure section:", error);
    res.status(500).json({ success: false, message: "Server error" });
  }
});


