// 🕒 Helper for SQL datetime (Nepal Time: UTC+5:45)
function getSQLDateTime() {
  const now = new Date();

  // Convert to Nepal time by adjusting UTC offset (+5:45 = 345 minutes)
  const nepalOffset = 5 * 60 + 45; // minutes
  const utcOffset = now.getTimezoneOffset(); // difference between local and UTC in minutes
  now.setMinutes(now.getMinutes() + nepalOffset + utcOffset);

  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const hh = String(now.getHours()).padStart(2, '0');
  const mi = String(now.getMinutes()).padStart(2, '0');
  const ss = String(now.getSeconds()).padStart(2, '0');

  return `${yyyy}-${mm}-${dd} ${hh}:${mi}:${ss}`;
}


