app.post('/updateFiscalyr', (req, res) => {
  const conn = req.session.conn;
  const { fiscalmovstart, fiscalmovend, fisYearID, fiscalmovchecked } = req.body;

  console.log('Incoming:', fiscalmovstart, fiscalmovend, fisYearID, fiscalmovchecked);

  if (!fisYearID) {
    return res.status(400).send("Fiscal year ID is required");
  }

  // 1️⃣ First get DateType
  const systemSettingQuery = `SELECT TOP 1 DateType FROM tbSystemSettings`;

  sql.query(conn, systemSettingQuery, (err, rows) => {
    if (err) {
      console.log(err);
      return res.status(500).send("Error fetching system settings");
    }

    const dateType = rows[0]?.DateType;
    console.log("DateType:", dateType);

    let startDateEng;
    let endDateEng;

    // 2️⃣ If LD → convert to AD dates
    if (dateType === "LD") {
      console.log("LD detected → converting dates");

      const mitiStartFormatted = convertToNepaliFormat(fiscalmovstart);
      const mitiEndFormatted = convertToNepaliFormat(fiscalmovend);

      const engdateQuery = `
        SELECT M_date FROM tbLocalDate WHERE M_Miti = ?
        UNION ALL
        SELECT M_date FROM tbLocalDate WHERE M_Miti = ?
      `;

      sql.query(connectionString, engdateQuery, [mitiStartFormatted, mitiEndFormatted], (err3, rows3) => {
        if (err3 || rows3.length < 2) {
          console.error("❌ Error converting English dates:", err3);
          return res.status(400).json({ error: "Invalid or missing local dates" });
        }

        startDateEng = rows3[0].M_date;
        endDateEng = rows3[1].M_date;

        console.log("Converted dates:", startDateEng, endDateEng);

        updateFiscalYear(startDateEng, endDateEng);
      });

    } else {
      // 3️⃣ NOT LD → Use raw values directly
      console.log("Not LD → using raw dates");

      startDateEng = fiscalmovstart;
      endDateEng = fiscalmovend;

      updateFiscalYear(startDateEng, endDateEng);
    }

    // 4️⃣ Function to update DB after dates are known
    function updateFiscalYear(startDateEng, endDateEng) {
      const isChecked =
        fiscalmovchecked === "on" ||
        fiscalmovchecked === true ||
        fiscalmovchecked === "true";

      const resetQuery = `UPDATE tbFiscalYearMaster SET CurrentFiscal = 0`;

      const updateQuery = `
        UPDATE tbFiscalYearMaster
        SET CurrentFiscal = ?,
            StartDate = ?,
            EndDate = ?,
            LastSavedDateTime = GETDATE()
        WHERE YearID = ?
      `;

      if (isChecked) {
        // Reset then update
        sql.query(conn, resetQuery, (err1) => {
          if (err1) return res.status(500).send("Error resetting fiscal years");

          sql.query(conn, updateQuery, [1, startDateEng, endDateEng, fisYearID], (err2, result) => {
            if (err2) return res.status(500).send("Error updating fiscal year");

            console.log("✅ Fiscal year updated:", result);
            res.send("Fiscal year updated successfully");
          });
        });
      } else {
        // Only update current one
        sql.query(conn, updateQuery, [0, startDateEng, endDateEng, fisYearID], (err2, result) => {
          if (err2) return res.status(500).send("Error updating fiscal year");

          console.log("✅ Fiscal year updated:", result);
          res.json({ message: "Fiscal year updated successfully", success: true });
        });
      }
    }
  });
});




