app.post('/get-cramount-collector', async (req, res) => {
  const conn = req.session.conn;
  const selectedCollectoerNames = req.body.selectedCollectoerNames;  // Array of IDs

  const { fromDate, toDate } = req.body;

  // Convert Nepali → English dates
  const dateResult1 = await runQuery(connectionString,
    `SELECT M_date FROM tbLocalDate WHERE M_Miti = ?`, [fromDate]);

  if (!dateResult1 || dateResult1.length === 0)
    return res.status(400).json({ error: "Invalid transaction date." });

  const fromDateEng = dateResult1[0].M_date;

  const dateResult2 = await runQuery(connectionString,
    `SELECT M_date FROM tbLocalDate WHERE M_Miti = ?`, [toDate]);

  if (!dateResult2 || dateResult2.length === 0)
    return res.status(400).json({ error: "Invalid transaction date." });

  const toDateEng = dateResult2[0].M_date;

  const fromDateStr = fromDateEng.toISOString().split('T')[0];
  const toDateStr = toDateEng.toISOString().split('T')[0];

  // Convert array → comma-separated IDs (NO quotes)
  // Example: [3,5,7] → "3,5,7"
  const ids = selectedCollectoerNames.join(",");

  console.log("Collector IDs:", ids);

  const query = `
      SELECT 
    JM.CollectorID,
    SUM(JD.CrAmount) AS TotalCrAmount
FROM tbJournalMaster JM
INNER JOIN tbJournalDetails JD
    ON JM.JournalID = JD.JournalID
WHERE JM.CollectorID IN (${ids})
AND JM.JV_Date BETWEEN ? AND ?
GROUP BY JM.CollectorID;

    `;

  sql.query(conn, query, [fromDateStr, toDateStr], (err, rows) => {
    if (err) {
      console.error("❌ SQL Error:", err);
      return res.status(500).json({ error: "Failed to calculate CrAmount" });
    }
    console.log(rows)

    res.json({ data: rows, success: true });


  });
});

app.post('/collector/multi-report', (req, res) => {
  const conn = req.session.conn;
  let { fromDate, toDate } = req.body;

  const dateTypeQuery = `SELECT TOP 1 DateType FROM tbSystemSettings`;

  sql.query(conn, dateTypeQuery, (err, result) => {
    if (err) {
      console.error(err);
      return res.status(500).json({ error: "Failed to get DateType" });
    }

    const DateType = result[0].DateType;
    let dateColumn;

    // ================= LD DATE =================
    if (DateType === 'LD') {
      dateColumn = 'JM.JV_Date';

      const mitiToADQuery = `
        SELECT 
          (SELECT M_date FROM tbLocalDate WHERE M_Miti = ?) AS FromDate,
          (SELECT M_date FROM tbLocalDate WHERE M_Miti = ?) AS ToDate
      `;

      sql.query(connectionString, mitiToADQuery, [fromDate, toDate], (err, dateRes) => {
        if (err) {
          console.error(err);
          return res.status(500).json({ error: "Date conversion failed" });
        }

        runFinalQuery(dateRes[0].FromDate, dateRes[0].ToDate, dateColumn);
      });

    // ================= AD DATE =================
    } else {
      dateColumn = 'JM.JV_Date';

      const from = formatADDate(fromDate); // dd/mm/yyyy → yyyy-mm-dd
      const to = formatADDate(toDate);

      runFinalQuery(from, to, dateColumn);
    }

    // ================= FINAL QUERY =================
    function runFinalQuery(from, to, dateColumn) {
      const query = `
        SELECT 
            C.CollectorID,
            C.CollectorName,
            C.CollectorAlias,
            ISNULL(SUM(JD.CrAmount), 0) AS TotalCrAmount
        FROM tbCollectorMaster C
        LEFT JOIN tbJournalMaster JM 
            ON JM.CollectorID = C.CollectorID
        LEFT JOIN tbJournalDetails JD 
            ON JM.JournalID = JD.JournalID
        WHERE ${dateColumn} BETWEEN ? AND ?
        GROUP BY 
            C.CollectorID, 
            C.CollectorName, 
            C.CollectorAlias
        ORDER BY C.CollectorName;
      `;

      sql.query(conn, query, [from, to], (err, rows) => {
        if (err) {
          console.error(err);
          return res.status(500).json({ error: "Unable to fetch data" });
        }

        const finalOutput = rows.map((row, index) => {
          const percent = 5;
          const commission = (row.TotalCrAmount * percent / 100).toFixed(2);

          return {
            SNO: index + 1,
            CollectorID: row.CollectorID,
            CollectorName: row.CollectorName,
            CollectorAlias: row.CollectorAlias,
            CommissionPercent: percent,
            TotalCrAmount: row.TotalCrAmount,
            CommissionAmount: commission
          };
        });

        console.log("MULTI REPORT →", finalOutput);

        res.json({
          success: true,
          data: finalOutput
        });
      });
    }
  });
});


// 🔹 Date formatter
function formatADDate(dateStr) {
  if (!dateStr) return null;
  const [dd, mm, yyyy] = dateStr.split('/');
  return `${yyyy}-${mm}-${dd}`;
}



app.get("/fetch-loanNaccname-data", (req, res) => {

  const conn = req.session.conn;
  const query = `
SELECT 
      ACD.SLID,
      ACD.SLIDCol,
      ACD.Amount AS ACD_Amount,

      -- SLID Details
      SLM1.GLID AS GLID_SLID,
      SLM1.SLName AS SLName_SLID,
      SLM1.SlAlias AS SlAlias_SLID,
      SLM1.MemberID AS MemberID_SLID,
      MM1.MemberAlias AS MemberAlias_SLID,
      SLM1.LoanAmount AS ApprovedLoan_SLID,
      LGM1.GLName AS GLName_SLID,
      LGM1.GlAlias AS GLAlias_SLID,

      -- Adjusted LoanAmount (Dr add, Cr subtract)
      (
          SLM1.LoanAmount +
          ISNULL(
              (
                  SELECT SUM(ISNULL(JD.DrAmount,0) - ISNULL(JD.CrAmount,0))
                  FROM tbJournalMaster JM
                  INNER JOIN tbJournalDetails JD ON JM.JournalID = JD.JournalID
                  WHERE 
                      JM.SLIDPR = ACD.SLID
                      AND JD.GLID = LGM1.GLID
                      AND JD.GLID = LGM1.GLID    -- Must match same GLID
              ), 0
          )
      ) AS AdjustedLoanAmount_SLID,

      -- SLIDCol Details
      SLM2.GLID AS GLID_SLIDCol,
      SLM2.SLName AS SLName_SLIDCol,
      SLM2.SlAlias AS SlAlias_SLIDCol,
      SLM2.MemberID AS MemberID_SLIDCol,
      MM2.MemberAlias AS MemberAlias_SLIDCol,
      LGM2.GLName AS GLName_SLIDCol,
      LGM2.GlAlias AS GLAlias_SLIDCol

FROM tbAccountCollateralDetails ACD
LEFT JOIN tbSubLedgerMaster SLM1 
       ON ACD.SLID = SLM1.SLID
LEFT JOIN tbLedgerMaster LGM1 
       ON SLM1.GLID = LGM1.GLID
LEFT JOIN tbMemberMaster MM1
       ON SLM1.MemberID = MM1.MemberID

LEFT JOIN tbSubLedgerMaster SLM2 
       ON ACD.SLIDCol = SLM2.SLID
LEFT JOIN tbLedgerMaster LGM2 
       ON SLM2.GLID = LGM2.GLID
LEFT JOIN tbMemberMaster MM2
       ON SLM2.MemberID = MM2.MemberID

WHERE 
      (SLM1.Closed IS NULL OR SLM1.Closed = 0)
  AND (SLM2.Closed IS NULL OR SLM2.Closed = 0)
ORDER BY GLName_SLID asc

      `;

  sql.query(conn, query, (err, rows) => {
    if (err) {
      console.error("Error executing query:", err);
      return res.status(500).send("Error fetching data");
    }
    res.json(rows);

  });
});

