app.post("/fetch-shareSoldRegister-data", (req, res) => {

  const conn = req.session.conn;
  const { dateFromShareR, dateToShareR } = req.body;

  // 1️⃣ First get the DateType (AD / LD)
  const dateTypeQuery = `
      SELECT TOP 1 DateType 
      FROM tbSystemSettings
  `;

  sql.query(conn, dateTypeQuery, (err, result) => {
    if (err) {
      console.error("Error:", err);
      return res.status(500).send("Error checking date type");
    }

    const dateType = result[0].DateType;

    // Will hold final usable dates for SQL query
    let finalFromDate = dateFromShareR;
    let finalToDate = dateToShareR;

    // 2️⃣ If DateType is AD → convert AD to LD using tbLocalDate
    if (dateType === "LD") {
      const strDa = convertToNepaliFormat(dateFromShareR);
      const endDa = convertToNepaliFormat(dateToShareR);
      const convertQuery = `
        SELECT 
            (SELECT TOP 1 M_date FROM tbLocalDate WHERE M_Miti = ?) AS FromMiti,
            (SELECT TOP 1 M_date FROM tbLocalDate WHERE M_Miti = ?) AS ToMiti
      `;

      sql.query(
        connectionString,
        convertQuery,
        [strDa, endDa],
        (err, conv) => {
          if (err) {
            console.error("Error converting dates:", err);
            return res.status(500).send("Error converting AD to LD");
          }

          finalFromDate = conv[0].FromMiti;
          finalToDate = conv[0].ToMiti;
          console.log(finalFromDate, finalToDate)

          runMainQuery(finalFromDate, finalToDate);
        }
      );
    } 
    
    // 3️⃣ If DateType is AD → use raw AD dates directly
    else {
      runMainQuery(finalFromDate, finalToDate);
    }
  });

  // 4️⃣ Main Share Sold Register Query
  function runMainQuery(strdate, enddate) {
    const query = `
      SELECT 
          SLM.SLID,
          SLM.SLName,
          SLM.SlAlias,
          STM.TransactionNo,
          STM.TransactionDate,
          STM.ShareTransactionID,
          STD.*
      FROM tbSubLedgerMaster SLM
      INNER JOIN tbShareTransactionMaster STM
             ON SLM.SLID = STM.SLID
      INNER JOIN tbShareTransactionDetails STD
             ON STM.ShareTransactionID = STD.ShareTransactionID
      WHERE STD.Sold = 0 and STM.TransactionType = 'Issue'
        AND STM.TransactionDate BETWEEN ? AND ?
    `;

    sql.query(conn, query, [strdate, enddate], (err, rows) => {
      if (err) {
        console.error("Error executing query:", err);
        return res.status(500).send("Error fetching data");
      }
      res.json(rows);
     
    });
  }

});
app.post("/fetch-shareSoldRegister-filterdata", (req, res) => {

    const conn = req.session.conn;
    const { dateFromShareR, dateToShareR, SLIDs } = req.body;

    if (!SLIDs || SLIDs.length === 0) {
        return res.status(400).json({ error: "No SLID values received" });
    }

    // Convert SLID array -> only pure numbers
    const onlySLIDs = SLIDs.map(obj => obj.SLID);

    // 1️⃣ First get DateType (AD / LD)
    const dateTypeQuery = `
        SELECT TOP 1 DateType FROM tbSystemSettings
    `;

    sql.query(conn, dateTypeQuery, (err, result) => {
        if (err) {
            console.error("Error checking DateType:", err);
            return res.status(500).send("Error checking date type");
        }

        const dateType = result[0].DateType;

        let finalFromDate = dateFromShareR;
        let finalToDate = dateToShareR;

        // 2️⃣ Convert AD → LD using tbLocalDate when needed
        if (dateType === "LD") {

            const strDa = convertToNepaliFormat(dateFromShareR);
            const endDa = convertToNepaliFormat(dateToShareR);

            const convertQuery = `
                SELECT 
                    (SELECT TOP 1 M_date FROM tbLocalDate WHERE M_Miti = ?) AS FromMiti,
                    (SELECT TOP 1 M_date FROM tbLocalDate WHERE M_Miti = ?) AS ToMiti
            `;

            sql.query(connectionString, convertQuery, [strDa, endDa], (err, conv) => {
                if (err) {
                    console.error("Error converting dates:", err);
                    return res.status(500).send("Error converting AD to LD");
                }

                finalFromDate = conv[0].FromMiti;
                finalToDate = conv[0].ToMiti;

                runMainQuery(finalFromDate, finalToDate, onlySLIDs);
            });

        } else {
            // 3️⃣ DateType = AD → Use dates as sent
            runMainQuery(finalFromDate, finalToDate, onlySLIDs);
        }
    });


    // 4️⃣ Main Query
    function runMainQuery(fromDate, toDate, SLIDlist) {

        const query = `
            SELECT 
                SLM.SLID,
                SLM.SLName,
                SLM.SlAlias,
                STM.TransactionNo,
                STM.TransactionDate,
                STM.ShareTransactionID,
                STD.*
            FROM tbSubLedgerMaster SLM
            INNER JOIN tbShareTransactionMaster STM
                    ON SLM.SLID = STM.SLID
            INNER JOIN tbShareTransactionDetails STD
                    ON STM.ShareTransactionID = STD.ShareTransactionID
            WHERE 
                STD.Sold = 0 
                AND STM.TransactionType = 'Issue'
                AND STM.TransactionDate BETWEEN ? AND ?
                AND SLM.SLID IN (${SLIDlist.map(() => '?').join(',')})
        `;

        const params = [fromDate, toDate, ...SLIDlist];

        sql.query(conn, query, params, (err, rows) => {
            if (err) {
                console.error("Error executing query:", err);
                return res.status(500).send("Error fetching data");
            }

            res.json(rows);
        });
    }

});

